/* TechNuggets - Practice Test loader v2 (AZ-305, Terraform, PCA). Safe to re-run. Auto-publishes.
   RUN: Udemy instructor site (logged in) -> DevTools Console -> paste ALL -> Enter.
   Keep the tab OPEN until you see 'ALL DONE'. */
(async () => {
  const TESTS = [{"name": "AZ-305 Practice Test 1", "cid": 7303525, "duration": 120, "pass_percent": 70, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A company has 5,000 users in an on-premises Active Directory domain. They need users to authenticate to Microsoft 365 and Azure resources using their existing on-premises passwords, without storing password hashes in the cloud, and authentication must continue to work even if the on-premises network link to Azure fails. Which authentication method should you recommend?", "prompt": {"question": "<p>A company has 5,000 users in an on-premises Active Directory domain. They need users to authenticate to Microsoft 365 and Azure resources using their existing on-premises passwords, without storing password hashes in the cloud, and authentication must continue to work even if the on-premises network link to Azure fails. Which authentication method should you recommend?</p>", "answers": ["<p>Password hash synchronization</p>", "<p>Federation with AD FS</p>", "<p>Pass-through Authentication with Seamless SSO</p>", "<p>Pass-through Authentication with a single Authentication Agent</p>"], "feedbacks": ["<p>Password hash synchronization stores a hash of the password hash in Microsoft Entra ID, violating the 'no password hashes in cloud' requirement.</p>", "<p>AD FS federation validates credentials against on-premises AD without syncing password hashes to Microsoft Entra ID, and a properly deployed AD FS farm with multiple servers/agents provides resilience so authentication is not dependent on a single link if designed with redundancy across sites.</p>", "<p>Pass-through Authentication with Seamless SSO still requires the on-premises Authentication Agent to be reachable for every sign-in, and a single agent is a single point of failure.</p>", "<p>A single Authentication Agent is explicitly a single point of failure; Microsoft recommends at least two agents, but this option still doesn't avoid the on-premises dependency requirement as well as federation with proper HA design.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An Azure Function app needs to read secrets from Azure Key Vault. The company's security policy prohibits storing any credentials, connection strings, or certificates in application code or configuration files. Which authentication mechanism should you configure for the Function app?", "prompt": {"question": "<p>An Azure Function app needs to read secrets from Azure Key Vault. The company's security policy prohibits storing any credentials, connection strings, or certificates in application code or configuration files. Which authentication mechanism should you configure for the Function app?</p>", "answers": ["<p>A system-assigned managed identity</p>", "<p>A service principal with a client secret stored in application settings</p>", "<p>Shared access signature tokens generated per request</p>", "<p>Azure AD B2C application registration with client credentials flow</p>"], "feedbacks": ["<p>A system-assigned managed identity is automatically created and managed by Azure, requires no credentials to be stored anywhere, and can be granted access policy or RBAC permissions on the Key Vault directly.</p>", "<p>A service principal with a client secret requires storing that secret somewhere, violating the no-credentials-in-config policy.</p>", "<p>SAS tokens are not a Key Vault authentication mechanism and would still need to be generated and stored, requiring credentials to create them.</p>", "<p>B2C app registrations are for customer-facing authentication scenarios, not for service-to-service authentication to Key Vault, and still require client secret storage.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization wants administrators to have Global Administrator privileges only when needed, requiring justification and time-bound activation, with automatic expiration after 8 hours and approval from a designated approver. Which Microsoft Entra ID feature should you configure?", "prompt": {"question": "<p>An organization wants administrators to have Global Administrator privileges only when needed, requiring justification and time-bound activation, with automatic expiration after 8 hours and approval from a designated approver. Which Microsoft Entra ID feature should you configure?</p>", "answers": ["<p>Conditional Access with sign-in frequency controls</p>", "<p>Microsoft Entra Privileged Identity Management (PIM) with eligible role assignments</p>", "<p>Azure Policy assignment at the tenant root management group</p>", "<p>Azure AD Identity Protection risk-based policies</p>"], "feedbacks": ["<p>Conditional Access controls how and when users authenticate but does not provide time-bound, justification-based role activation.</p>", "<p>PIM allows configuring roles as 'eligible' rather than permanently active, requiring users to activate the role with justification, MFA, and approval, with a maximum activation duration you define (such as 8 hours) after which the role automatically deactivates.</p>", "<p>Azure Policy enforces resource configuration compliance; it has no role for managing just-in-time administrative privilege escalation.</p>", "<p>Identity Protection detects and responds to risky sign-ins and users but does not manage time-bound role elevation or approval workflows.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has three subscriptions: Production, Development, and Shared Services. They need to ensure a specific set of security policies (e.g., requiring encryption at rest, restricting allowed regions) is automatically enforced on all subscriptions, including any subscriptions added in the future, with minimal ongoing administrative effort. What should you implement?", "prompt": {"question": "<p>A company has three subscriptions: Production, Development, and Shared Services. They need to ensure a specific set of security policies (e.g., requiring encryption at rest, restricting allowed regions) is automatically enforced on all subscriptions, including any subscriptions added in the future, with minimal ongoing administrative effort. What should you implement?</p>", "answers": ["<p>Assign an Azure Policy initiative directly to each subscription individually</p>", "<p>Create a resource lock on each subscription's resource groups</p>", "<p>Configure Azure Blueprints assigned manually to each new subscription as it is created</p>", "<p>Create a management group hierarchy and assign an Azure Policy initiative at the management group level</p>"], "feedbacks": ["<p>Assigning to each subscription individually requires manual repetition and does not automatically apply to future subscriptions.</p>", "<p>Resource locks prevent deletion or modification of resources; they do not enforce configuration standards like encryption or region restrictions.</p>", "<p>Blueprints assigned manually per subscription still require administrative action each time a new subscription is created, failing the 'minimal ongoing effort' and 'future subscriptions' requirements.</p>", "<p>Assigning a policy initiative at a management group level ensures inheritance down to all current and future subscriptions placed under that management group, satisfying the requirement with minimal ongoing effort.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A finance team requires that a critical storage account containing regulatory audit logs can never be accidentally deleted by any user, including subscription owners, but administrators must still be able to modify its configuration settings such as network rules. Which governance control should you apply?", "prompt": {"question": "<p>A finance team requires that a critical storage account containing regulatory audit logs can never be accidentally deleted by any user, including subscription owners, but administrators must still be able to modify its configuration settings such as network rules. Which governance control should you apply?</p>", "answers": ["<p>Assign the Reader role to all users on the storage account</p>", "<p>Apply a ReadOnly resource lock on the storage account</p>", "<p>Apply a CanNotDelete resource lock on the storage account</p>", "<p>Create an Azure Policy with a Deny effect for delete operations on storage accounts</p>"], "feedbacks": ["<p>Assigning Reader role would prevent all users, including those who need to manage the storage account, from making any configuration changes, which is too restrictive and doesn't specifically target deletion.</p>", "<p>A ReadOnly lock prevents both deletion AND any modification, including the required network rule changes, which violates the requirement that admins can still modify settings.</p>", "<p>A CanNotDelete lock prevents deletion of the resource regardless of the user's RBAC permissions, while still allowing configuration changes like updating network rules.</p>", "<p>An Azure Policy Deny effect for delete operations is not a standard built-in mechanism for this scenario and locks are the purpose-built Azure feature for delete protection.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs microservices across 15 Azure App Service instances in different resource groups and subscriptions. They need centralized, correlated end-to-end distributed tracing across all services to diagnose latency issues in customer-facing transactions, along with custom business metric tracking. Which monitoring solution should you design?", "prompt": {"question": "<p>A company runs microservices across 15 Azure App Service instances in different resource groups and subscriptions. They need centralized, correlated end-to-end distributed tracing across all services to diagnose latency issues in customer-facing transactions, along with custom business metric tracking. Which monitoring solution should you design?</p>", "answers": ["<p>Deploy Azure Monitor Log Analytics agent on each App Service and query logs manually with KQL</p>", "<p>Configure Azure Service Health alerts for each subscription</p>", "<p>Enable Application Insights on each App Service instance, all sending telemetry to a shared Log Analytics workspace</p>", "<p>Enable diagnostic settings on each App Service to send logs to separate storage accounts per subscription</p>"], "feedbacks": ["<p>The Log Analytics agent alone collects infrastructure/OS-level logs and does not provide application-level distributed tracing or custom business metrics without Application Insights instrumentation.</p>", "<p>Azure Service Health reports on Azure platform incidents and service issues, not application-level performance or custom telemetry.</p>", "<p>Application Insights provides distributed tracing (via operation IDs) and custom metrics/events tracking; connecting all instances to a single shared Log Analytics workspace enables cross-service correlation and centralized end-to-end transaction analysis.</p>", "<p>Sending diagnostic logs to separate storage accounts per subscription prevents centralized correlation and makes cross-service end-to-end tracing very difficult, defeating the stated requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's security team wants administrators to receive standing permissions to Azure resources only when needed, require manager approval before elevation, and automatically expire the elevated access after 8 hours. Which Microsoft Entra ID feature should you implement?", "prompt": {"question": "<p>A company's security team wants administrators to receive standing permissions to Azure resources only when needed, require manager approval before elevation, and automatically expire the elevated access after 8 hours. Which Microsoft Entra ID feature should you implement?</p>", "answers": ["<p>Microsoft Entra Privileged Identity Management (PIM) with eligible assignments and approval workflows</p>", "<p>Conditional Access policies scoped to administrative roles</p>", "<p>Custom RBAC roles with a defined assignment scope</p>", "<p>Access reviews configured on the Global Administrator role</p>"], "feedbacks": ["<p>PIM eligible assignments let users activate a role only when needed, can require approval from a designated approver, and support time-bound activation (e.g., 8-hour maximum duration), directly meeting all three requirements.</p>", "<p>Conditional Access controls sign-in conditions (MFA, location, device) but does not provide time-bound just-in-time elevation with approval workflows.</p>", "<p>Custom RBAC roles define what permissions a role has, but the role would still be a standing (permanent) assignment unless combined with PIM.</p>", "<p>Access reviews periodically recertify existing access but don't provide just-in-time activation with approval before use.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to synchronize on-premises Active Directory identities to Microsoft Entra ID. The security team requires that password changes and account lockouts be enforced instantly in the cloud without deploying any additional on-premises servers beyond the sync agent, and they want to avoid maintaining AD FS infrastructure. Which authentication method should you recommend?", "prompt": {"question": "<p>A company needs to synchronize on-premises Active Directory identities to Microsoft Entra ID. The security team requires that password changes and account lockouts be enforced instantly in the cloud without deploying any additional on-premises servers beyond the sync agent, and they want to avoid maintaining AD FS infrastructure. Which authentication method should you recommend?</p>", "answers": ["<p>Federated authentication with AD FS</p>", "<p>Password Hash Synchronization with Seamless SSO</p>", "<p>Pass-through Authentication with Seamless SSO</p>", "<p>Microsoft Entra Connect cloud sync only, with no authentication method configured</p>"], "feedbacks": ["<p>AD FS federation requires deploying and maintaining highly available AD FS and Web Application Proxy servers, which the requirement explicitly wants to avoid.</p>", "<p>Password Hash Synchronization synchronizes a hash of the password hash to Microsoft Entra ID, enforces password and lockout policies in the cloud, requires no additional on-premises servers beyond the sync engine, and avoids AD FS infrastructure entirely, meeting all stated requirements.</p>", "<p>Pass-through Authentication requires one or more on-premises PTA agents that validate every sign-in against on-premises AD in real time, which is additional infrastructure beyond the sync agent and creates a dependency on on-premises availability.</p>", "<p>Cloud sync alone does not configure an authentication method; identities would sync but sign-in would fail without one of the authentication methods being selected.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization wants every new resource group created in a subscription to automatically receive a 'CostCenter' tag inherited from its parent subscription's tag, without blocking resource group creation if the tag is missing. Which Azure Policy effect should the policy definition use?", "prompt": {"question": "<p>An organization wants every new resource group created in a subscription to automatically receive a 'CostCenter' tag inherited from its parent subscription's tag, without blocking resource group creation if the tag is missing. Which Azure Policy effect should the policy definition use?</p>", "answers": ["<p>Deny</p>", "<p>Append</p>", "<p>Audit</p>", "<p>AuditIfNotExists</p>"], "feedbacks": ["<p>Deny would block the creation of the resource group if the tag is missing, which contradicts the requirement to not block creation.</p>", "<p>The Append effect adds the specified tag (and its value, such as from the parent subscription) to the resource during creation or update without preventing the request, satisfying the requirement to auto-tag without blocking creation.</p>", "<p>Audit only flags non-compliant resources in reporting; it does not add the tag automatically.</p>", "<p>AuditIfNotExists checks whether a related resource exists and flags non-compliance but does not modify the resource or add a tag.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A web application monitored with Application Insights generates over 50 GB of telemetry per day, causing high ingestion costs while most requests are healthy and low-value for analysis. The team wants to automatically reduce data volume while preserving accurate request counts, exception details, and dependency tracking. What should you configure?", "prompt": {"question": "<p>A web application monitored with Application Insights generates over 50 GB of telemetry per day, causing high ingestion costs while most requests are healthy and low-value for analysis. The team wants to automatically reduce data volume while preserving accurate request counts, exception details, and dependency tracking. What should you configure?</p>", "answers": ["<p>Adaptive sampling</p>", "<p>Fixed-rate sampling with a hardcoded percentage</p>", "<p>Daily data cap on the Log Analytics workspace</p>", "<p>Disable request and dependency tracking in the SDK</p>"], "feedbacks": ["<p>Adaptive sampling automatically adjusts the volume of telemetry sent based on current traffic, aiming to keep a target rate of telemetry per second, while preserving correlated data (exceptions, dependencies) and maintaining statistically accurate counts through sampling percentages applied to metrics.</p>", "<p>Fixed-rate sampling uses a static percentage regardless of traffic changes, which can either over-sample during spikes or under-sample during low traffic, and requires manual tuning.</p>", "<p>A daily data cap simply stops ingesting data (and cutting off telemetry) once the cap is reached, which can cause total loss of visibility rather than a controlled statistical reduction.</p>", "<p>Disabling request and dependency tracking removes visibility entirely, which violates the requirement to preserve exception and dependency tracking.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has 30 subscriptions across multiple departments and regions. The central security team must run Kusto queries across all resource logs and Microsoft Defender for Cloud alerts from every subscription, while each department's operations team should only be able to query logs from their own subscription's resources. What is the BEST monitoring design?", "prompt": {"question": "<p>A company has 30 subscriptions across multiple departments and regions. The central security team must run Kusto queries across all resource logs and Microsoft Defender for Cloud alerts from every subscription, while each department's operations team should only be able to query logs from their own subscription's resources. What is the BEST monitoring design?</p>", "answers": ["<p>Deploy one centralized Log Analytics workspace and use table-level Azure RBAC to restrict department access to only their resource data</p>", "<p>Deploy a separate Log Analytics workspace per subscription with no centralization</p>", "<p>Deploy one Log Analytics workspace per department and grant the security team Reader access to each</p>", "<p>Use Azure Monitor Metrics exclusively instead of Log Analytics for all subscriptions</p>"], "feedbacks": ["<p>A centralized Log Analytics workspace lets the central security team run cross-subscription queries in one place, while table-level RBAC (using resource-context or table-level access control) can restrict each department's operations team to querying only the logs relevant to their own resources.</p>", "<p>Separate workspaces per subscription with no centralization would force the security team to query 30 workspaces individually, failing the cross-subscription requirement.</p>", "<p>Per-department workspaces with Reader access would still require the security team to query multiple workspaces separately and doesn't provide a single consolidated query experience.</p>", "<p>Azure Monitor Metrics only stores numeric time-series data and cannot run Kusto log queries across resource logs or Defender for Cloud alerts.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A critical production storage account must never be accidentally deleted, but administrators still need to modify its network rules and access tiers as part of normal operations. Which resource lock type should be applied?", "prompt": {"question": "<p>A critical production storage account must never be accidentally deleted, but administrators still need to modify its network rules and access tiers as part of normal operations. Which resource lock type should be applied?</p>", "answers": ["<p>ReadOnly lock</p>", "<p>Azure Policy with a Deny effect on delete actions</p>", "<p>CanNotDelete lock</p>", "<p>Management group-level Blueprint assignment</p>"], "feedbacks": ["<p>A ReadOnly lock would prevent all modifications, including changing network rules or access tiers, not just deletion.</p>", "<p>Azure Policy can restrict actions but is designed for governance compliance across many resources and is not the standard, purpose-built mechanism for preventing accidental deletion of a single resource; resource locks are the intended tool.</p>", "<p>A CanNotDelete lock prevents authorized users from deleting the resource but still allows configuration changes such as updating network rules or access tiers, meeting both requirements.</p>", "<p>Blueprints are used to package and deploy governance artifacts (policies, RBAC, ARM templates) at scale, not to directly protect an individual resource from deletion.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A global retail company uses Azure Cosmos DB for NoSQL with multi-region writes (multi-master) enabled across three Azure regions to support low-latency writes for customers worldwide. The company wants the strongest consistency guarantee that Cosmos DB supports when multi-region writes are enabled. Which consistency level should be configured?", "prompt": {"question": "<p>A global retail company uses Azure Cosmos DB for NoSQL with multi-region writes (multi-master) enabled across three Azure regions to support low-latency writes for customers worldwide. The company wants the strongest consistency guarantee that Cosmos DB supports when multi-region writes are enabled. Which consistency level should be configured?</p>", "answers": ["<p>Strong</p>", "<p>Session</p>", "<p>Eventual</p>", "<p>Bounded Staleness</p>"], "feedbacks": ["<p>Strong consistency cannot be selected on an account that has multi-region writes (multi-master) enabled; the portal/SDK blocks this combination.</p>", "<p>Session consistency guarantees monotonic reads/writes only within a client session and is weaker than Bounded Staleness.</p>", "<p>Eventual consistency is the weakest level, offering no ordering guarantees, and is not the 'strongest' option requested.</p>", "<p>Bounded Staleness is the strongest consistency level Cosmos DB supports when multi-region writes are enabled. Strong consistency is only available for single-write-region accounts.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company is migrating an on-premises PostgreSQL database to Azure. Requirements: minimize application changes, support zone-redundant high availability with automatic failover, and allow read scale-out via read replicas. Which service should the solutions architect recommend?", "prompt": {"question": "<p>A company is migrating an on-premises PostgreSQL database to Azure. Requirements: minimize application changes, support zone-redundant high availability with automatic failover, and allow read scale-out via read replicas. Which service should the solutions architect recommend?</p>", "answers": ["<p>Azure SQL Managed Instance</p>", "<p>Azure Database for PostgreSQL - Flexible Server</p>", "<p>Azure Database for PostgreSQL - Single Server</p>", "<p>Azure Cosmos DB for PostgreSQL</p>"], "feedbacks": ["<p>Azure SQL Managed Instance runs the SQL Server engine, not PostgreSQL, and would require a full database migration rather than a lift-and-shift.</p>", "<p>Flexible Server supports zone-redundant high availability with automatic failover and native read replicas, while remaining wire-compatible with PostgreSQL, minimizing application changes.</p>", "<p>Single Server is retired (fully retired in 2025), lacks zone-redundant HA, and has limited read replica support, making it unsuitable for a new deployment.</p>", "<p>Azure Cosmos DB for PostgreSQL (Citus) is designed for horizontally distributed, sharded workloads and adds unnecessary architectural complexity for a straightforward HA migration.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company stores application telemetry logs in an Azure Storage account within a single region. The data must be synchronously replicated across three availability zones for high durability, but the company does not require the data to be readable from a secondary region. Which redundancy option should be configured?", "prompt": {"question": "<p>A company stores application telemetry logs in an Azure Storage account within a single region. The data must be synchronously replicated across three availability zones for high durability, but the company does not require the data to be readable from a secondary region. Which redundancy option should be configured?</p>", "answers": ["<p>LRS</p>", "<p>GRS</p>", "<p>ZRS</p>", "<p>RA-GRS</p>"], "feedbacks": ["<p>LRS replicates data only within a single datacenter and provides no protection against a zone-level outage.</p>", "<p>GRS asynchronously copies data to a secondary region but does not provide zone-redundant protection in the primary region and adds unneeded cross-region cost.</p>", "<p>ZRS synchronously replicates data across three availability zones within the primary region, meeting the durability requirement without needing a readable secondary region.</p>", "<p>RA-GRS adds read access to the secondary region, which the company explicitly does not need, and does not itself provide zone redundancy in the primary region.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which Azure SQL Database purchasing model allows independent scaling of compute and storage, supports Azure Hybrid Benefit for existing SQL Server licenses, and prices based on virtual cores and memory selected?", "prompt": {"question": "<p>Which Azure SQL Database purchasing model allows independent scaling of compute and storage, supports Azure Hybrid Benefit for existing SQL Server licenses, and prices based on virtual cores and memory selected?</p>", "answers": ["<p>vCore-based model</p>", "<p>DTU-based model</p>", "<p>Serverless compute tier</p>", "<p>Elastic pool DTU model</p>"], "feedbacks": ["<p>The vCore-based purchasing model lets customers independently choose compute (vCores/memory) and storage, and supports Azure Hybrid Benefit to reduce licensing costs.</p>", "<p>The DTU-based model bundles compute, storage, and I/O into a single blended unit and does not support Azure Hybrid Benefit.</p>", "<p>Serverless is a compute tier available within the vCore model, not a separate purchasing model, so it isn't the best general answer.</p>", "<p>Elastic pool DTU model still uses DTUs to bundle resources across a pool and shares the same limitations as the standalone DTU model.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization stores 50 TB of compliance audit logs in Azure Blob Storage. Logs are accessed frequently for the first 30 days, occasionally between day 31 and day 90, and must be retained for 7 years but are rarely accessed after day 90. Regulations require the logs to be immutable and impossible to delete or modify during the retention period. Which combination of Azure Storage features should the architect implement?", "prompt": {"question": "<p>An organization stores 50 TB of compliance audit logs in Azure Blob Storage. Logs are accessed frequently for the first 30 days, occasionally between day 31 and day 90, and must be retained for 7 years but are rarely accessed after day 90. Regulations require the logs to be immutable and impossible to delete or modify during the retention period. Which combination of Azure Storage features should the architect implement?</p>", "answers": ["<p>Lifecycle management policy to move blobs to Cool tier at 30 days and Archive tier at 90 days, combined with a time-based immutability policy set for 7 years</p>", "<p>Hot tier only, with Azure Backup for retention</p>", "<p>Soft delete enabled on the storage account with a 90-day retention period</p>", "<p>Blob versioning with lifecycle management to delete blobs after 90 days</p>"], "feedbacks": ["<p>A lifecycle management policy automatically tiers blobs (Hot to Cool to Archive) to match the access pattern and minimize cost, while a time-based immutability (WORM) policy enforces regulatory compliance by preventing deletion or modification for the required 7-year retention period.</p>", "<p>Keeping data in the Hot tier for 7 years is far more expensive than necessary, and Azure Backup does not provide object-level WORM immutability guarantees for blob data.</p>", "<p>Soft delete only protects against accidental deletion for up to 365 days and does not provide true regulatory immutability or tier-based cost optimization.</p>", "<p>Deleting blobs after 90 days directly violates the 7-year regulatory retention requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to orchestrate extraction of data from an on-premises SQL Server database, transform it, and load it into Azure Synapse Analytics dedicated SQL pools on a nightly schedule. The solution must support a self-hosted integration runtime to securely access on-premises data without opening inbound firewall ports. Which Azure service should the architect use to build this pipeline?", "prompt": {"question": "<p>A company needs to orchestrate extraction of data from an on-premises SQL Server database, transform it, and load it into Azure Synapse Analytics dedicated SQL pools on a nightly schedule. The solution must support a self-hosted integration runtime to securely access on-premises data without opening inbound firewall ports. Which Azure service should the architect use to build this pipeline?</p>", "answers": ["<p>Azure Functions</p>", "<p>Azure Logic Apps</p>", "<p>AzCopy</p>", "<p>Azure Data Factory</p>"], "feedbacks": ["<p>Azure Functions can execute custom code but lacks built-in ETL orchestration, scheduling, and self-hosted integration runtime support that Data Factory provides natively.</p>", "<p>Logic Apps is designed for application/workflow integration scenarios and is not optimized for large-scale, scheduled data movement and transformation pipelines.</p>", "<p>AzCopy is a command-line tool for copying data to and from storage accounts; it does not provide orchestration, transformation, or scheduled pipeline capabilities.</p>", "<p>Azure Data Factory natively supports self-hosted integration runtimes for secure on-premises connectivity, provides built-in orchestration and scheduling, and has a native connector to load data into Synapse dedicated SQL pools.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company stores compliance data in an Azure Storage account in the East US region. During a regional outage, applications in a different application must still be able to read the data (writes can be delayed) without the company performing a manual failover. Which redundancy option should you configure for the storage account?", "prompt": {"question": "<p>A company stores compliance data in an Azure Storage account in the East US region. During a regional outage, applications in a different application must still be able to read the data (writes can be delayed) without the company performing a manual failover. Which redundancy option should you configure for the storage account?</p>", "answers": ["<p>Locally redundant storage (LRS)</p>", "<p>Zone-redundant storage (ZRS)</p>", "<p>Geo-redundant storage (GRS)</p>", "<p>Read-access geo-redundant storage (RA-GRS)</p>"], "feedbacks": ["<p>LRS only replicates within a single datacenter and provides no protection against a regional outage.</p>", "<p>ZRS replicates synchronously across availability zones in the same region, so it does not protect against a full regional outage.</p>", "<p>GRS replicates to a paired region for disaster recovery, but the secondary copy is not readable until a full account failover is performed, which does not meet the 'without manual failover' requirement.</p>", "<p>RA-GRS replicates data to a paired secondary region and exposes a read-only secondary endpoint, allowing applications to read data from the secondary region during an outage without requiring a manual account failover.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A development team is migrating an existing application that uses the MongoDB wire protocol and driver libraries. They want to move the database to Azure with the least amount of application code change. Which Azure Cosmos DB API should you select?", "prompt": {"question": "<p>A development team is migrating an existing application that uses the MongoDB wire protocol and driver libraries. They want to move the database to Azure with the least amount of application code change. Which Azure Cosmos DB API should you select?</p>", "answers": ["<p>Cosmos DB for NoSQL</p>", "<p>Cosmos DB for Apache Cassandra</p>", "<p>Cosmos DB for MongoDB</p>", "<p>Cosmos DB for Table</p>"], "feedbacks": ["<p>The NoSQL API uses its own SQL-like query language and SDKs, requiring the application to be rewritten to use Cosmos DB's native API.</p>", "<p>The Cassandra API implements the CQL wire protocol for Cassandra applications, not MongoDB, so it would not support existing MongoDB drivers.</p>", "<p>Azure Cosmos DB for MongoDB implements the MongoDB wire protocol, so existing MongoDB drivers, SDKs, and tools work with minimal or no code changes.</p>", "<p>The Table API is designed for key-value workloads originally built on Azure Table Storage and does not support the MongoDB protocol.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "You need to configure a lifecycle management policy on a blob container so that blobs are moved to the Cool access tier if they have not been modified for 30 days, and moved to the Archive tier if not modified for 90 days, to reduce storage costs automatically. Which feature should you configure?", "prompt": {"question": "<p>You need to configure a lifecycle management policy on a blob container so that blobs are moved to the Cool access tier if they have not been modified for 30 days, and moved to the Archive tier if not modified for 90 days, to reduce storage costs automatically. Which feature should you configure?</p>", "answers": ["<p>Blob versioning with soft delete enabled</p>", "<p>A scheduled Azure Automation runbook that changes blob tiers nightly</p>", "<p>Object replication rules between two storage accounts</p>", "<p>Storage account lifecycle management policy rules based on last modification time</p>"], "feedbacks": ["<p>Blob versioning and soft delete protect against accidental deletion or overwrite; they do not move blobs between access tiers.</p>", "<p>A custom Automation runbook could technically work but requires building and maintaining custom code, whereas a native lifecycle policy is the built-in, exam-preferred mechanism for this exact scenario.</p>", "<p>Object replication copies blobs to another storage account for redundancy or latency purposes; it does not change access tiers based on age.</p>", "<p>Lifecycle management policies let you define rules using conditions such as daysAfterModificationGreaterThan to automatically transition blobs between Hot, Cool, and Archive tiers, exactly matching the described requirement without custom code.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An Azure Cosmos DB container stores order records and uses 'orderStatus' (values: New, Processing, Shipped, Closed) as the partition key. The team notices severe throttling (429 errors) and uneven RU consumption concentrated on a small number of physical partitions. What is the BEST change to resolve this?", "prompt": {"question": "<p>An Azure Cosmos DB container stores order records and uses 'orderStatus' (values: New, Processing, Shipped, Closed) as the partition key. The team notices severe throttling (429 errors) and uneven RU consumption concentrated on a small number of physical partitions. What is the BEST change to resolve this?</p>", "answers": ["<p>Change the partition key to a high-cardinality property such as customerId or orderId</p>", "<p>Increase the provisioned RU/s on the container until throttling stops</p>", "<p>Enable autoscale throughput on the container without changing the partition key</p>", "<p>Switch the container's consistency level from Session to Eventual</p>"], "feedbacks": ["<p>orderStatus has very low cardinality and highly skewed access (most active orders are New/Processing), causing a 'hot partition' where requests concentrate on few physical partitions regardless of total RU/s. Choosing a high-cardinality key like customerId or orderId distributes requests and storage evenly across logical and physical partitions.</p>", "<p>Raising RU/s increases overall throughput capacity but does not fix uneven distribution across physical partitions, so the hot partition will still throttle while other partitions sit idle.</p>", "<p>Autoscale adjusts RU/s dynamically within a range but does not address skewed partition key distribution, so hot-partition throttling persists.</p>", "<p>Consistency level affects read latency and staleness guarantees, not RU distribution across partitions, so changing it would not resolve throttling caused by a poor partition key.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to orchestrate a nightly pipeline that extracts data from an on-premises SQL Server database behind a corporate firewall, transforms it, and loads it into Azure Synapse Analytics dedicated SQL pools. Which solution should you use to connect to and extract from the on-premises source?", "prompt": {"question": "<p>A company needs to orchestrate a nightly pipeline that extracts data from an on-premises SQL Server database behind a corporate firewall, transforms it, and loads it into Azure Synapse Analytics dedicated SQL pools. Which solution should you use to connect to and extract from the on-premises source?</p>", "answers": ["<p>Azure Synapse serverless SQL pool querying the on-premises database directly</p>", "<p>Azure Data Factory with a Self-hosted Integration Runtime installed on-premises</p>", "<p>Azure Data Factory using only the default Azure Integration Runtime</p>", "<p>Azure Database Migration Service configured for continuous replication</p>"], "feedbacks": ["<p>Synapse serverless SQL pools query data in Azure Data Lake or external tables; they cannot directly reach an on-premises SQL Server behind a firewall without a gateway.</p>", "<p>A Self-hosted Integration Runtime is installed on a machine inside the corporate network and acts as a secure bridge, allowing Azure Data Factory pipelines to connect to on-premises data sources that are not directly reachable from Azure, then move data into Synapse.</p>", "<p>The default Azure Integration Runtime runs in the Azure cloud and cannot reach resources isolated behind an on-premises firewall without a self-hosted component.</p>", "<p>Azure Database Migration Service is designed for one-time or continuous database migrations, not for scheduled ETL/ELT transformation pipelines feeding a data warehouse.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An architecture team is comparing purchasing models for a new Azure SQL Database deployment. The company already owns SQL Server licenses with Software Assurance and wants to apply Azure Hybrid Benefit to reduce compute costs. Which purchasing model must they choose?", "prompt": {"question": "<p>An architecture team is comparing purchasing models for a new Azure SQL Database deployment. The company already owns SQL Server licenses with Software Assurance and wants to apply Azure Hybrid Benefit to reduce compute costs. Which purchasing model must they choose?</p>", "answers": ["<p>DTU-based purchasing model</p>", "<p>vCore-based purchasing model</p>", "<p>Serverless compute tier only</p>", "<p>Elastic pool with DTU-based pricing</p>"], "feedbacks": ["<p>The DTU-based model bundles compute, memory, and storage into fixed tiers and does not support applying Azure Hybrid Benefit licensing discounts.</p>", "<p>Azure Hybrid Benefit, which lets customers apply existing SQL Server licenses with Software Assurance to reduce compute costs in Azure, is only available with the vCore-based purchasing model, not DTU-based options.</p>", "<p>Serverless is a compute tier available within the vCore model, but selecting 'serverless only' does not by itself indicate the purchasing model change needed; the key requirement is vCore, which serverless is a subset of.</p>", "<p>DTU-based elastic pools have the same limitation as standalone DTU databases and do not support Azure Hybrid Benefit.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs 200 on-premises VMs and needs to fail them over to Azure during a datacenter outage. The business requires an RTO of 1 hour and an RPO of 15 minutes. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A company runs 200 on-premises VMs and needs to fail them over to Azure during a datacenter outage. The business requires an RTO of 1 hour and an RPO of 15 minutes. Which solution BEST meets these requirements?</p>", "answers": ["<p>Configure Azure Backup with a daily backup policy for each VM</p>", "<p>Use Azure Migrate to perform a one-time lift-and-shift migration to Azure</p>", "<p>Configure Azure Site Recovery to continuously replicate the on-premises VMs to Azure</p>", "<p>Create a weekly scheduled VM image export to an Azure storage account</p>"], "feedbacks": ["<p>Azure Backup with a daily policy only gives an RPO of 24 hours, far exceeding the 15-minute requirement.</p>", "<p>Azure Migrate performs a one-time migration, not ongoing replication for disaster recovery — it does not maintain an up-to-date failover target.</p>", "<p>Azure Site Recovery (ASR) performs continuous, near-real-time replication of on-premises VMs to Azure, supporting RPOs as low as 30 seconds to a few minutes and orchestrated failover that can meet a 1-hour RTO.</p>", "<p>Weekly image exports would give an RPO of up to 7 days, which is unacceptable.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants to replicate a fleet of Azure VMs from the East US region to West US so they can be failed over as a group using an orchestrated recovery plan during a regional outage. Which Azure service should be used?", "prompt": {"question": "<p>A company wants to replicate a fleet of Azure VMs from the East US region to West US so they can be failed over as a group using an orchestrated recovery plan during a regional outage. Which Azure service should be used?</p>", "answers": ["<p>Azure Backup</p>", "<p>Azure Traffic Manager</p>", "<p>Azure Migrate</p>", "<p>Azure Site Recovery</p>"], "feedbacks": ["<p>Azure Backup protects data via point-in-time recovery points, but it does not provide continuous replication or orchestrated multi-VM failover.</p>", "<p>Azure Traffic Manager is a DNS-based traffic router; it does not replicate VM data.</p>", "<p>Azure Migrate is designed for assessment and one-time migration, not ongoing DR replication.</p>", "<p>Azure Site Recovery supports Azure-to-Azure replication between region pairs and lets administrators group VMs into recovery plans for coordinated, ordered failover.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company backs up its Azure VMs to a Recovery Services vault and must be able to restore VMs to a secondary Azure region if the primary region becomes completely unavailable. Which vault storage redundancy setting must be configured to support this requirement?", "prompt": {"question": "<p>A company backs up its Azure VMs to a Recovery Services vault and must be able to restore VMs to a secondary Azure region if the primary region becomes completely unavailable. Which vault storage redundancy setting must be configured to support this requirement?</p>", "answers": ["<p>Geo-redundant storage (GRS)</p>", "<p>Locally-redundant storage (LRS)</p>", "<p>Zone-redundant storage (ZRS)</p>", "<p>Hot access tier</p>"], "feedbacks": ["<p>Cross Region Restore requires the Recovery Services vault to be configured with geo-redundant storage (GRS), which replicates backup data to a paired secondary region and allows restoring VMs there during a regional outage.</p>", "<p>LRS only replicates within a single datacenter, so backup data is lost if the region fails.</p>", "<p>ZRS replicates across availability zones in the same region, but does not protect against a full regional outage.</p>", "<p>Access tier (Hot/Cool/Archive) applies to blob storage cost management, not to backup vault redundancy or cross-region restore capability.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An application uses Azure SQL Database and requires automatic failover to a secondary region with near-zero RPO and a single, stable connection endpoint that applications don't need to reconfigure after failover. Which feature should be used?", "prompt": {"question": "<p>An application uses Azure SQL Database and requires automatic failover to a secondary region with near-zero RPO and a single, stable connection endpoint that applications don't need to reconfigure after failover. Which feature should be used?</p>", "answers": ["<p>Manual active geo-replication with application-managed connection strings</p>", "<p>Azure SQL Managed Instance with geo-restore</p>", "<p>Scheduled export to a BACPAC file in another region</p>", "<p>Auto-failover groups</p>"], "feedbacks": ["<p>Manual active geo-replication requires the application or an operator to initiate failover and update connection strings, failing the automatic and stable-endpoint requirements.</p>", "<p>Geo-restore from Managed Instance backups has an RPO of up to 1 hour and requires manual restore, not automatic near-zero-RPO failover.</p>", "<p>BACPAC exports are for logical backups/migration, not disaster recovery, and offer no automatic failover or near-zero RPO.</p>", "<p>Auto-failover groups provide automatic failover, near-zero RPO through synchronous-like geo-replication, and a read-write listener endpoint that stays the same across failover, so applications don't need connection string changes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly distinguishes Azure Availability Zones from Availability Sets?", "prompt": {"question": "<p>Which statement correctly distinguishes Azure Availability Zones from Availability Sets?</p>", "answers": ["<p>Availability Sets protect against physically separate datacenter failures within a region and provide a 99.99% SLA, while Availability Zones protect against single-rack failures with a 99.95% SLA</p>", "<p>Availability Zones and Availability Sets provide identical fault isolation and the same 99.99% SLA</p>", "<p>Availability Sets replicate VMs to a secondary Azure region, while Availability Zones only work within a single datacenter</p>", "<p>Availability Zones protect against physically separate datacenter failures within a region with independent power, cooling, and networking, providing a 99.99% SLA, while Availability Sets protect against single-rack failures within one datacenter and provide a 99.95% SLA</p>"], "feedbacks": ["<p>This reverses the SLA and protection scope of the two features.</p>", "<p>The SLAs and fault-isolation scope differ (99.99% vs 99.95%); they are not identical.</p>", "<p>Neither feature replicates VMs to another region — that is the role of Azure Site Recovery; both zones and sets operate within a single region.</p>", "<p>Availability Zones are physically separate locations within an Azure region, each with independent power, cooling, and networking, offering a 99.99% VM SLA when two or more VMs are spread across zones. Availability Sets distribute VMs across fault domains and update domains within a single datacenter, offering a 99.95% SLA.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A global e-commerce company needs its order-processing application to remain fully available for both reads and writes with near-zero RTO if an entire Azure region fails, and users worldwide must be routed to the closest healthy region automatically. Which design BEST meets these requirements?", "prompt": {"question": "<p>A global e-commerce company needs its order-processing application to remain fully available for both reads and writes with near-zero RTO if an entire Azure region fails, and users worldwide must be routed to the closest healthy region automatically. Which design BEST meets these requirements?</p>", "answers": ["<p>Deploy the application to a single region with availability zones and back up the database nightly</p>", "<p>Deploy an active/passive design in two regions with manual DNS updates to redirect traffic during an outage</p>", "<p>Deploy the application in one region and use Azure Site Recovery to replicate VMs to a second region for manual failover</p>", "<p>Deploy the application active/active across multiple regions behind Azure Front Door, using Azure Cosmos DB configured for multi-region writes</p>"], "feedbacks": ["<p>A single-region design with only nightly backups leaves no protection against a regional outage and has a high RPO/RTO.</p>", "<p>Active/passive with manual DNS updates introduces significant delay (high RTO) and does not provide simultaneous multi-region writes.</p>", "<p>Azure Site Recovery with manual failover is intended for VM-level DR, not multi-region active/active application architectures, and manual failover increases RTO.</p>", "<p>An active/active multi-region deployment with Azure Front Door for global routing and Cosmos DB multi-region writes allows simultaneous read/write availability in every region and automatic traffic rerouting, achieving near-zero RTO during a regional failure.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A global retailer runs a web application that serves both static assets and dynamic API responses. Traffic originates from users in North America, Europe, and Asia. The company requires SSL offloading, path-based routing to different backend pools, and a Web Application Firewall (WAF) that inspects traffic before it reaches any regional backend. The solution must minimize latency for users worldwide. Which service should the architect choose?", "prompt": {"question": "<p>A global retailer runs a web application that serves both static assets and dynamic API responses. Traffic originates from users in North America, Europe, and Asia. The company requires SSL offloading, path-based routing to different backend pools, and a Web Application Firewall (WAF) that inspects traffic before it reaches any regional backend. The solution must minimize latency for users worldwide. Which service should the architect choose?</p>", "answers": ["<p>Azure Traffic Manager with WAF enabled on each regional backend</p>", "<p>Azure Load Balancer (Standard SKU) in front of each regional App Service</p>", "<p>Azure Front Door (Premium tier) with WAF policies and path-based routing rules</p>", "<p>A single regional Azure Application Gateway with WAF_v2 SKU</p>"], "feedbacks": ["<p>Traffic Manager is DNS-based routing only — it cannot perform SSL offload, path-based routing, or WAF inspection; it just resolves to an endpoint.</p>", "<p>Azure Load Balancer operates at Layer 4 and has no concept of path-based routing or WAF; it can't inspect HTTP paths.</p>", "<p>Azure Front Door Premium is a global, Layer 7 entry point that terminates SSL at the edge, supports path-based routing, and includes an integrated WAF that inspects traffic before it is routed to the closest healthy regional backend, minimizing latency for a worldwide user base.</p>", "<p>A single regional Application Gateway does not provide global points of presence, so users far from that region incur higher latency.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An order-processing system has one publisher and four independent downstream services, each of which must receive a copy of every order message. Some services need to filter which messages they receive based on message properties, and undelivered messages must be moved to a dead-letter queue for later inspection. Which Azure messaging service should be used?", "prompt": {"question": "<p>An order-processing system has one publisher and four independent downstream services, each of which must receive a copy of every order message. Some services need to filter which messages they receive based on message properties, and undelivered messages must be moved to a dead-letter queue for later inspection. Which Azure messaging service should be used?</p>", "answers": ["<p>Azure Storage Queues</p>", "<p>Azure Service Bus Topics and Subscriptions</p>", "<p>Azure Event Hubs</p>", "<p>Azure Event Grid with a webhook endpoint</p>"], "feedbacks": ["<p>Storage Queues support only a single competing-consumer pattern; a message read by one consumer is removed and not available to others, so it can't fan out to four independent services.</p>", "<p>Service Bus Topics implement a publish/subscribe pattern where each subscription receives a copy of every message, subscriptions can apply SQL or correlation filters, and dead-lettering is a built-in feature — matching all stated requirements.</p>", "<p>Event Hubs is built for high-throughput streaming/telemetry ingestion with consumer groups reading a partitioned log — it lacks native message-level filtering and dead-lettering semantics for enterprise messaging.</p>", "<p>Event Grid is designed for reactive, near-real-time event notifications and does not provide the enterprise messaging guarantees (like built-in dead-lettering per subscription with rich filtering) that this scenario requires as reliably as Service Bus.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "You are designing the node subnet for an AKS cluster using Azure CNI networking. The cluster will initially run 20 nodes with a maximum of 30 pods per node, and it must be able to scale to 40 nodes without requiring a subnet resize. Which subnet size should you provision?", "prompt": {"question": "<p>You are designing the node subnet for an AKS cluster using Azure CNI networking. The cluster will initially run 20 nodes with a maximum of 30 pods per node, and it must be able to scale to 40 nodes without requiring a subnet resize. Which subnet size should you provision?</p>", "answers": ["<p>/24</p>", "<p>/22</p>", "<p>/21</p>", "<p>/23</p>"], "feedbacks": ["<p>/24 provides only 256 usable addresses, nowhere near enough for 40 nodes × 30 pods.</p>", "<p>/22 provides 1,024 addresses, which is short of the ~1,245 needed at full scale (1,240 + 5 reserved).</p>", "<p>At 40 nodes with 30 pods each, up to 1,240 IP addresses are needed for nodes and pods combined, plus 5 addresses reserved by Azure for the subnet. A /21 provides 2,048 addresses, comfortably covering this requirement with room for cluster upgrades and surge nodes.</p>", "<p>/23 provides 512 addresses, which is also insufficient once the cluster scales to 40 nodes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company must migrate an on-premises SQL Server database to Azure SQL Managed Instance. The database is 2 TB and business requirements state that application downtime during cutover must be less than 5 minutes. Which migration approach should the architect choose?", "prompt": {"question": "<p>A company must migrate an on-premises SQL Server database to Azure SQL Managed Instance. The database is 2 TB and business requirements state that application downtime during cutover must be less than 5 minutes. Which migration approach should the architect choose?</p>", "answers": ["<p>Use the Azure Database Migration Service in online migration mode</p>", "<p>Export the database to a BACPAC file and import it into Azure SQL Managed Instance</p>", "<p>Use Azure Data Factory to copy data on a nightly schedule</p>", "<p>Use the Azure Database Migration Service in offline migration mode</p>"], "feedbacks": ["<p>DMS online migration performs continuous data synchronization from the source to the target while the source stays online, and only requires a brief cutover window to redirect the application — meeting the sub-5-minute downtime requirement.</p>", "<p>BACPAC export/import requires taking the database offline for the full duration of the export and import, which for a 2 TB database would far exceed 5 minutes.</p>", "<p>Data Factory nightly copies are for ETL/analytics scenarios and do not provide transactional consistency or a low-downtime cutover mechanism suitable for an OLTP migration.</p>", "<p>DMS offline mode stops the source database during the entire migration process, causing extended downtime unsuitable for this requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A security team requires that traffic from a virtual network to an Azure Storage account travel entirely over the Microsoft backbone network, receive a private IP address from within the VNet's address space, and be completely inaccessible from the public internet — even if the storage account's firewall allows public network access. Which solution meets these requirements?", "prompt": {"question": "<p>A security team requires that traffic from a virtual network to an Azure Storage account travel entirely over the Microsoft backbone network, receive a private IP address from within the VNet's address space, and be completely inaccessible from the public internet — even if the storage account's firewall allows public network access. Which solution meets these requirements?</p>", "answers": ["<p>A Private Endpoint with a corresponding Private DNS Zone</p>", "<p>A Network Security Group rule blocking inbound internet traffic to the storage account</p>", "<p>A VNet Service Endpoint for Microsoft.Storage</p>", "<p>A Site-to-Site VPN Gateway connection to the storage account</p>"], "feedbacks": ["<p>A Private Endpoint provisions a network interface with a private IP address from the VNet, maps the storage account's FQDN to that private IP via a Private DNS Zone, and removes the public endpoint's reachability entirely, ensuring traffic never traverses the public internet regardless of firewall settings.</p>", "<p>An NSG only filters traffic at the subnet/NIC level; it doesn't change how the storage account is reached and doesn't assign a private IP to the service itself.</p>", "<p>A Service Endpoint extends the VNet identity to the service over the Microsoft backbone but the storage account still retains a public IP address and endpoint, so it isn't fully private.</p>", "<p>A VPN Gateway is used for hybrid connectivity between networks, not for privately accessing a PaaS service's data plane endpoint.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has internal line-of-business applications hosted on-premises and in Azure, connected via ExpressRoute. They want to expose a set of internal REST APIs through Azure API Management, but the APIM instance and its APIs must be reachable only from the corporate network and Azure VNets — never from the public internet. Which APIM deployment configuration should be used?", "prompt": {"question": "<p>A company has internal line-of-business applications hosted on-premises and in Azure, connected via ExpressRoute. They want to expose a set of internal REST APIs through Azure API Management, but the APIM instance and its APIs must be reachable only from the corporate network and Azure VNets — never from the public internet. Which APIM deployment configuration should be used?</p>", "answers": ["<p>Deploy API Management in Consumption tier with public network access disabled</p>", "<p>Deploy API Management in Internal VNet mode</p>", "<p>Deploy API Management in External VNet mode with a public IP restricted by NSG</p>", "<p>Deploy API Management in the default (non-VNet) mode with IP filtering configured on the developer portal</p>"], "feedbacks": ["<p>The Consumption tier does not support VNet integration, so it cannot be fully isolated from the internet in this way.</p>", "<p>Internal VNet mode injects APIM entirely inside the VNet with no public IP for the gateway, making it reachable only from within the VNet, peered VNets, and on-premises networks connected via ExpressRoute or VPN — matching the requirement exactly.</p>", "<p>External VNet mode still exposes the gateway through a public IP/endpoint; NSGs on the VNet don't remove that public entry point.</p>", "<p>The default (non-VNet) deployment mode always exposes the gateway endpoint publicly; portal IP filtering doesn't block API gateway traffic.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a globally distributed e-commerce website hosted across multiple Azure regions. They need a solution that provides global HTTP/HTTPS load balancing, SSL offloading, a Web Application Firewall (WAF), and routes users to the closest healthy backend based on latency. Which service should they use?", "prompt": {"question": "<p>A company runs a globally distributed e-commerce website hosted across multiple Azure regions. They need a solution that provides global HTTP/HTTPS load balancing, SSL offloading, a Web Application Firewall (WAF), and routes users to the closest healthy backend based on latency. Which service should they use?</p>", "answers": ["<p>Azure Traffic Manager</p>", "<p>Azure Load Balancer (Standard)</p>", "<p>Azure Front Door</p>", "<p>Azure Application Gateway (regional)</p>"], "feedbacks": ["<p>Traffic Manager performs DNS-based global routing only — it has no WAF, no SSL offload, and no health-based Layer-7 traffic switching within a request.</p>", "<p>Azure Load Balancer operates at Layer 4 and is regional, not global, and has no WAF or SSL offload capability.</p>", "<p>Azure Front Door is a global, Layer-7 (HTTP/HTTPS) load balancer that includes WAF, SSL offload, and latency-based routing to the closest healthy backend across regions.</p>", "<p>Application Gateway is a regional Layer-7 load balancer with WAF, but it cannot route traffic across multiple Azure regions on its own.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A retail company needs an event-driven architecture where inventory changes in Azure SQL Database trigger reactive workflows in multiple independent Azure Functions, and new subscribers may be added over time without modifying the publisher. Which service should distribute these events?", "prompt": {"question": "<p>A retail company needs an event-driven architecture where inventory changes in Azure SQL Database trigger reactive workflows in multiple independent Azure Functions, and new subscribers may be added over time without modifying the publisher. Which service should distribute these events?</p>", "answers": ["<p>Azure Service Bus Topics</p>", "<p>Azure Queue Storage</p>", "<p>Azure Event Hubs</p>", "<p>Azure Event Grid</p>"], "feedbacks": ["<p>Service Bus Topics require explicit subscription provisioning and are better suited for enterprise messaging with ordering/transactions, not lightweight reactive event fan-out.</p>", "<p>Queue Storage is a simple single-consumer queue with no pub/sub fan-out capability.</p>", "<p>Event Hubs is designed for high-throughput streaming/telemetry ingestion, not discrete event routing to multiple independent subscribers.</p>", "<p>Event Grid is purpose-built for reactive, event-driven pub/sub scenarios, supports dynamic subscriber addition without publisher changes, and integrates natively with Azure resource events.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company hosts an Azure SQL Database and requires that all traffic from their VNet-connected application servers travel over the Microsoft backbone network without traversing the public internet, while completely disabling any public endpoint access to the database. Which solution should they implement?", "prompt": {"question": "<p>A financial services company hosts an Azure SQL Database and requires that all traffic from their VNet-connected application servers travel over the Microsoft backbone network without traversing the public internet, while completely disabling any public endpoint access to the database. Which solution should they implement?</p>", "answers": ["<p>Service Endpoint on the SQL subnet</p>", "<p>VNet Peering to the SQL Database</p>", "<p>Private Endpoint with Private Link</p>", "<p>A Network Security Group rule allowing only VNet traffic</p>"], "feedbacks": ["<p>Service Endpoints optimize routing but the database still has a reachable public IP; public access cannot be fully eliminated at the network layer this way.</p>", "<p>VNet Peering connects two VNets — it cannot be used to connect to a PaaS service like Azure SQL Database.</p>", "<p>Private Endpoint assigns a private IP address from the VNet to the SQL Database via Private Link, keeps all traffic on the Microsoft backbone, and allows the public endpoint to be fully disabled.</p>", "<p>NSGs filter traffic to resources with network interfaces in a VNet; they cannot control access to a PaaS service still exposed via a public endpoint.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has a business-critical hybrid connectivity requirement to Azure and wants to eliminate a single point of failure for their ExpressRoute connectivity to achieve maximum resiliency. What should they configure?", "prompt": {"question": "<p>A company has a business-critical hybrid connectivity requirement to Azure and wants to eliminate a single point of failure for their ExpressRoute connectivity to achieve maximum resiliency. What should they configure?</p>", "answers": ["<p>Two ExpressRoute circuits provisioned in different peering locations connected to different edge routers</p>", "<p>A single ExpressRoute circuit with the Premium add-on enabled</p>", "<p>A single ExpressRoute circuit with a zone-redundant virtual network gateway</p>", "<p>A single ExpressRoute circuit backed up by an active-active VPN Gateway over the public internet</p>"], "feedbacks": ["<p>Microsoft's recommended design for maximum ExpressRoute resiliency is to provision two circuits in different peering locations connected via different edge routers, eliminating a single circuit as a point of failure.</p>", "<p>The Premium add-on increases route table size and enables global reach — it does not add circuit-level redundancy.</p>", "<p>A zone-redundant gateway protects against gateway/zone failure on the Azure side, but does not address failure of the single ExpressRoute circuit itself.</p>", "<p>A VPN Gateway failover over the public internet is a valid resilience pattern but does not meet the requirement of eliminating the single point of failure within the ExpressRoute circuit design itself.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A development team is building containerized microservices that require complex custom networking policies, custom Kubernetes operators, and direct access to the Kubernetes API for advanced orchestration control. The team has staff experienced in Kubernetes administration. Which Azure compute service should they choose?", "prompt": {"question": "<p>A development team is building containerized microservices that require complex custom networking policies, custom Kubernetes operators, and direct access to the Kubernetes API for advanced orchestration control. The team has staff experienced in Kubernetes administration. Which Azure compute service should they choose?</p>", "answers": ["<p>Azure Container Apps</p>", "<p>Azure App Service for Containers</p>", "<p>Azure Kubernetes Service (AKS)</p>", "<p>Azure Container Instances</p>"], "feedbacks": ["<p>Container Apps abstracts away the underlying Kubernetes layer entirely — there is no direct API access or support for custom operators.</p>", "<p>App Service for Containers hosts a single container per app in a simplified PaaS model without orchestration or API-level control.</p>", "<p>AKS provides full access to the Kubernetes API, supports custom operators, and allows advanced networking policy configuration, making it ideal for teams with dedicated Kubernetes expertise.</p>", "<p>Container Instances runs single containers or simple container groups without orchestration, scaling policies, or Kubernetes API access.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to migrate an on-premises SQL Server database to Azure SQL Managed Instance with minimal application downtime, using continuous data replication until a final cutover. Which Azure service is purpose-built for this online migration scenario?", "prompt": {"question": "<p>A company needs to migrate an on-premises SQL Server database to Azure SQL Managed Instance with minimal application downtime, using continuous data replication until a final cutover. Which Azure service is purpose-built for this online migration scenario?</p>", "answers": ["<p>Azure Database Migration Service (online migration mode)</p>", "<p>Azure Data Factory</p>", "<p>Azure Migrate: Server Migration</p>", "<p>SQL Server Import/Export Wizard</p>"], "feedbacks": ["<p>Azure Database Migration Service in online mode supports continuous data replication from the source database and a minimal-downtime cutover, purpose-built for this exact migration pattern.</p>", "<p>Data Factory is an ETL/data integration service used for batch data movement and transformation, not a minimal-downtime online database migration tool.</p>", "<p>Azure Migrate: Server Migration handles rehosting of VMs/servers, not database-level continuous replication migration.</p>", "<p>The Import/Export Wizard is a manual, offline tool that requires downtime and is not suited for continuous replication at enterprise scale.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a customer-facing web application on Azure App Service deployed across three regions worldwide. They need global HTTP load balancing with SSL offload, path-based routing, and a Web Application Firewall (WAF) to protect against Layer 7 attacks like SQL injection. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A company runs a customer-facing web application on Azure App Service deployed across three regions worldwide. They need global HTTP load balancing with SSL offload, path-based routing, and a Web Application Firewall (WAF) to protect against Layer 7 attacks like SQL injection. Which solution BEST meets these requirements?</p>", "answers": ["<p>Azure Load Balancer (Standard SKU) with health probes configured across all three regions</p>", "<p>Azure Front Door with a WAF policy attached</p>", "<p>Azure Application Gateway with WAF_v2 SKU deployed in each region</p>", "<p>Azure Traffic Manager with priority routing and endpoint monitoring</p>"], "feedbacks": ["<p>Azure Load Balancer operates at Layer 4 and cannot do SSL offload, path-based routing, or WAF inspection — it also isn't global.</p>", "<p>Azure Front Door is a global, Anycast Layer 7 load balancer that supports SSL offload, path-based routing, and integrates directly with Azure WAF policies at the edge, making it the only option that provides global HTTP(S) load balancing plus WAF in a single service.</p>", "<p>Application Gateway with WAF is regional; deploying one per region gives per-region WAF but doesn't provide global load balancing or a single global entry point across regions.</p>", "<p>Traffic Manager is DNS-based routing only — it doesn't inspect HTTP traffic, cannot do SSL offload or path-based routing, and has no WAF capability.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services application must process payment transaction messages that require strict FIFO ordering per customer account, support atomic batch operations across multiple messages, and provide dead-lettering for failed transactions. Which messaging service should be used?", "prompt": {"question": "<p>A financial services application must process payment transaction messages that require strict FIFO ordering per customer account, support atomic batch operations across multiple messages, and provide dead-lettering for failed transactions. Which messaging service should be used?</p>", "answers": ["<p>Azure Event Grid with a custom topic</p>", "<p>Azure Event Hubs with a dedicated consumer group</p>", "<p>Azure Storage Queues with poison message handling</p>", "<p>Azure Service Bus using sessions and a transactional batch</p>"], "feedbacks": ["<p>Event Grid is a pub/sub eventing service for reactive, discrete events; it provides no ordering guarantees and no transactional semantics.</p>", "<p>Event Hubs is designed for high-throughput telemetry/streaming ingestion; while it preserves order within a partition, it has no built-in transactional batch support or dead-lettering.</p>", "<p>Storage Queues offer basic at-least-once delivery and a poison-message pattern but provide no ordering guarantee and no native transaction support.</p>", "<p>Azure Service Bus supports message sessions to guarantee FIFO ordering per session (e.g., per customer account), native transactions for atomic multi-message operations, and built-in dead-lettering — matching all three requirements exactly.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to connect from resources inside a VNet to an Azure SQL Database over a private IP address, ensure traffic never traverses the public internet, and resolve the database's fully qualified domain name to that private IP using a private DNS zone. Which solution should be implemented?", "prompt": {"question": "<p>A company needs to connect from resources inside a VNet to an Azure SQL Database over a private IP address, ensure traffic never traverses the public internet, and resolve the database's fully qualified domain name to that private IP using a private DNS zone. Which solution should be implemented?</p>", "answers": ["<p>Configure a Service Endpoint for Microsoft.Sql on the subnet</p>", "<p>Deploy a Private Endpoint for the Azure SQL Database and link a Private DNS zone</p>", "<p>Establish VNet Peering between the application VNet and the SQL Database's underlying network</p>", "<p>Provision an ExpressRoute circuit with private peering to the Azure region</p>"], "feedbacks": ["<p>Service Endpoints extend the VNet identity to the service over the Azure backbone and restrict access by VNet, but the SQL Database still uses its public endpoint IP and does not integrate with a private DNS zone for a private IP.</p>", "<p>A Private Endpoint provisions a private IP address from the VNet directly into Azure SQL Database, and linking a Private DNS zone (privatelink.database.windows.net) resolves the server's FQDN to that private IP, keeping all traffic on the Microsoft backbone and off the public internet — satisfying every stated requirement.</p>", "<p>VNet Peering connects two Azure virtual networks together — Azure SQL Database is a PaaS service with no VNet of its own to peer with.</p>", "<p>ExpressRoute provides private hybrid connectivity from on-premises to Azure over a dedicated circuit, but on its own does not create a private IP for a specific PaaS resource inside the VNet.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}], "expected": 45}, {"name": "AZ-305 Practice Test 2", "cid": 7303525, "duration": 120, "pass_percent": 70, "questions": [{"assessment_type": "multiple-choice", "question_plain": "Contoso requires that access to Azure resources by IT administrators be restricted to compliant, Intune-managed devices with MFA enforced. Two emergency-access 'break-glass' accounts must remain fully accessible without these restrictions in case Microsoft Entra ID Conditional Access misconfigures access for everyone else. What should you implement?", "prompt": {"question": "<p>Contoso requires that access to Azure resources by IT administrators be restricted to compliant, Intune-managed devices with MFA enforced. Two emergency-access 'break-glass' accounts must remain fully accessible without these restrictions in case Microsoft Entra ID Conditional Access misconfigures access for everyone else. What should you implement?</p>", "answers": ["<p>Create a Conditional Access policy requiring MFA and device compliance for all users, and exclude the break-glass accounts from that policy.</p>", "<p>Enable Security defaults in Microsoft Entra ID and manually add the break-glass accounts to the Global Administrator role.</p>", "<p>Configure Identity Protection sign-in risk policies requiring MFA for administrative roles only.</p>", "<p>Apply an Azure Policy definition that denies resource creation unless an MFA claim is present in the request token.</p>"], "feedbacks": ["<p>Conditional Access policies support granular targeting (all users/admins) with explicit exclusions, allowing MFA and device-compliance enforcement while keeping break-glass accounts exempt from those controls.</p>", "<p>Security defaults are an all-or-nothing baseline with no exclusion capability for break-glass accounts and no device-compliance option.</p>", "<p>Risk-based sign-in policies address risky sign-ins, not the requirement for mandatory device compliance for administrators.</p>", "<p>Azure Policy governs resource management plane deployments, not identity authentication controls like MFA or device compliance.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "You must create a custom Azure RBAC role allowing members to read and restart virtual machines and view their metrics, while explicitly preventing them from managing VM extensions or reading boot diagnostics blob data in the storage account. Which role definition structure is correct?", "prompt": {"question": "<p>You must create a custom Azure RBAC role allowing members to read and restart virtual machines and view their metrics, while explicitly preventing them from managing VM extensions or reading boot diagnostics blob data in the storage account. Which role definition structure is correct?</p>", "answers": ["<p>\"Actions\": [\"Microsoft.Compute/virtualMachines/read\", \"Microsoft.Compute/virtualMachines/restart/action\", \"Microsoft.Insights/metrics/read\"], \"NotActions\": [\"Microsoft.Compute/virtualMachines/extensions/*\"], \"DataActions\": [], \"NotDataActions\": [\"Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read\"]</p>", "<p>\"Actions\": [\"*\"], \"NotActions\": [\"Microsoft.Compute/virtualMachines/extensions/*\", \"Microsoft.Storage/*\"]</p>", "<p>\"Actions\": [\"Microsoft.Compute/virtualMachines/read\", \"Microsoft.Compute/virtualMachines/restart/action\"], \"DataActions\": [\"Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read\"], \"NotActions\": []</p>", "<p>\"DataActions\": [\"Microsoft.Compute/virtualMachines/restart/action\"], \"Actions\": [\"Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read\"]</p>"], "feedbacks": ["<p>This structure grants only the required management-plane Actions, uses NotActions to remove extension management, and leaves DataActions empty with NotDataActions explicitly blocking blob read, correctly separating management-plane and data-plane permissions.</p>", "<p>A wildcard Actions grant is far broader than required (violates least privilege) and the Microsoft.Storage/* NotActions removes storage management entirely rather than just scoping VM diagnostics data access.</p>", "<p>Explicitly granting blob read via DataActions violates the requirement to prevent boot diagnostics data access.</p>", "<p>The Actions and DataActions are reversed: restarting a VM is a management-plane Action, and reading blob data is a data-plane DataAction, making this definition structurally invalid.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A global company enforces an Azure Policy initiative with a Deny effect requiring an 'Owner' tag on all resources, assigned at the root management group and inherited by every subscription. A subsidiary migrating a legacy ERP system needs a 60-day exclusion from just this tag requirement for one resource group, without weakening enforcement anywhere else. What should you do?", "prompt": {"question": "<p>A global company enforces an Azure Policy initiative with a Deny effect requiring an 'Owner' tag on all resources, assigned at the root management group and inherited by every subscription. A subsidiary migrating a legacy ERP system needs a 60-day exclusion from just this tag requirement for one resource group, without weakening enforcement anywhere else. What should you do?</p>", "answers": ["<p>Temporarily move the subsidiary's subscription out of the management group hierarchy.</p>", "<p>Edit the policy initiative assignment at the root management group to add a resource group exclusion parameter.</p>", "<p>Assign a new policy definition at the subscription level with an Audit effect to override the inherited Deny effect.</p>", "<p>Create a policy exemption scoped to the subsidiary's resource group, with an expiration date and a documented exemption category.</p>"], "feedbacks": ["<p>Removing the subscription from the hierarchy disables all inherited governance controls, not just the tag policy, and is disruptive and non-compliant for other requirements.</p>", "<p>Editing the root assignment changes governance for every subscription under it and lacks a built-in time-bound expiration mechanism suited to a temporary exception.</p>", "<p>A less restrictive effect assigned at a lower scope does not override a Deny effect inherited from a higher scope; the more restrictive effect always wins.</p>", "<p>Azure Policy exemptions provide a scoped, time-bound way to exclude a specific resource or resource group from one or more policy effects without altering the parent assignment, and support an automatic expiration date and exemption category for auditability.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A multinational retailer must keep diagnostic and security logs from EU and US resources within their respective regions to satisfy data-residency law, but the central SOC team needs a single set of workbooks and alert rules correlating events across all regions in near real time. What should you implement?", "prompt": {"question": "<p>A multinational retailer must keep diagnostic and security logs from EU and US resources within their respective regions to satisfy data-residency law, but the central SOC team needs a single set of workbooks and alert rules correlating events across all regions in near real time. What should you implement?</p>", "answers": ["<p>One global Log Analytics workspace in a central region with data export disabled.</p>", "<p>Regional Log Analytics workspaces in the EU and US, with cross-workspace Kusto queries used in shared workbooks and alert rules.</p>", "<p>Azure Monitor Private Link Scope only, with all diagnostic settings pointed at a single US-based workspace.</p>", "<p>Application Insights classic (non-workspace-based) resources deployed independently in each region.</p>"], "feedbacks": ["<p>A single global workspace violates residency requirements regardless of export settings, because data is ingested and stored in one region.</p>", "<p>Deploying a workspace per region satisfies data-residency requirements since ingestion stays local, while cross-workspace Log Analytics queries allow the central SOC to build unified workbooks and alerts spanning all regional workspaces.</p>", "<p>Routing all diagnostics to a single US workspace violates EU data-residency requirements outright; Private Link Scope only secures connectivity, it doesn't address residency.</p>", "<p>Classic Application Insights resources are a deprecated model, provide no cross-region correlation, and don't cover infrastructure logs like NSG or VM diagnostics needed by the SOC.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "The security team wants users eligible for the Global Administrator role via Privileged Identity Management to activate the role only after providing a business justification and receiving manager approval, for a maximum of 4 hours per activation, with an alert sent to security operations whenever activation occurs. Which PIM configuration meets these requirements?", "prompt": {"question": "<p>The security team wants users eligible for the Global Administrator role via Privileged Identity Management to activate the role only after providing a business justification and receiving manager approval, for a maximum of 4 hours per activation, with an alert sent to security operations whenever activation occurs. Which PIM configuration meets these requirements?</p>", "answers": ["<p>Require multi-factor authentication only, set maximum activation duration to 8 hours, and use eligible assignments.</p>", "<p>Require justification and approval with designated approvers, set maximum activation duration to 4 hours, and configure activation alert notifications.</p>", "<p>Require Azure AD Identity Protection risk assessment with a permanent eligible assignment and no approval required.</p>", "<p>Assign the role as Active (permanent) and require a compliant device via Conditional Access.</p>"], "feedbacks": ["<p>This omits the required approval and justification steps and exceeds the 4-hour maximum duration with an 8-hour setting.</p>", "<p>PIM role settings support requiring justification, requiring approval from specified approvers, setting a maximum activation duration, and configuring notifications/alerts on activation — matching every stated requirement exactly.</p>", "<p>This has no approval workflow at all and uses a permanent eligible assignment, directly contradicting the manager-approval requirement.</p>", "<p>An Active (permanent) assignment bypasses PIM's activation workflow entirely, so there is no justification, approval, or time-bound elevation to configure.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "You create an Azure Policy assignment using a DeployIfNotExists effect that must automatically remediate non-compliant resources by deploying a diagnostic setting. Which identity does the remediation task require, and how is it typically provisioned?", "prompt": {"question": "<p>You create an Azure Policy assignment using a DeployIfNotExists effect that must automatically remediate non-compliant resources by deploying a diagnostic setting. Which identity does the remediation task require, and how is it typically provisioned?</p>", "answers": ["<p>The remediation task uses the signed-in user's own Microsoft Entra ID session credentials at assignment time; no separate identity is needed.</p>", "<p>A system-assigned managed identity (or an optional user-assigned managed identity) is configured for the policy assignment and must be granted the roles specified in the policy definition's roleDefinitionIds.</p>", "<p>A user-assigned managed identity is mandatory, and the policy definition cannot use a DeployIfNotExists effect without one being created first.</p>", "<p>A service principal with a client secret must be manually created and embedded in the policy definition's parameters.</p>"], "feedbacks": ["<p>Remediation tasks run independently of any user session and require a persistent identity, not the ad hoc credentials of the person creating the assignment.</p>", "<p>DeployIfNotExists and Modify policy effects require a managed identity on the policy assignment — either system-assigned or user-assigned — which must be granted the role(s) listed in roleDefinitionIds so it can deploy the remediation resources on the assignment's behalf.</p>", "<p>A user-assigned identity is optional, not mandatory — you can choose either system-assigned or user-assigned when configuring the assignment.</p>", "<p>Azure Policy remediation uses the managed identity model specifically to avoid manual secret management; service principals with client secrets are not used for this purpose.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company requires that Global Administrator access to Microsoft Entra ID be granted only when needed, require manager approval, enforce MFA at the moment of activation, and automatically expire after 8 hours. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A financial services company requires that Global Administrator access to Microsoft Entra ID be granted only when needed, require manager approval, enforce MFA at the moment of activation, and automatically expire after 8 hours. Which solution BEST meets these requirements?</p>", "answers": ["<p>Assign the Global Administrator role permanently to a security group and require MFA for all sign-ins using a Conditional Access policy</p>", "<p>Use Azure Policy to assign the Global Administrator directory role and configure a policy exemption that expires after 8 hours</p>", "<p>Create a Conditional Access policy requiring MFA and use an Azure Automation runbook that removes the role assignment 8 hours after it is granted</p>", "<p>Configure Microsoft Entra Privileged Identity Management (PIM) to make the users eligible for the Global Administrator role, with an activation policy that requires approval, MFA, and a maximum activation duration of 8 hours</p>"], "feedbacks": ["<p>A permanent assignment with only sign-in MFA does not provide just-in-time access, approval workflow, or automatic expiration — it fails the core requirement of time-bound privileged access.</p>", "<p>Azure Policy governs resource configuration compliance; it cannot assign or exempt Microsoft Entra directory roles, and 'policy exemption' is a Resource Manager concept, not an identity governance concept.</p>", "<p>A custom Automation runbook can technically remove a role assignment after a delay, but it requires building and maintaining custom automation, doesn't natively enforce approval or activation-time MFA, and duplicates functionality PIM already provides natively.</p>", "<p>PIM natively supports just-in-time eligible role assignments with configurable approval workflows, mandatory MFA on activation, and a maximum activation duration — exactly matching all four requirements without custom tooling.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Your organization enforces Conditional Access policies that require MFA and a compliant device for all users, including every Global Administrator. You need to ensure administrators can still sign in to Microsoft Entra ID if the MFA service or Conditional Access policy engine experiences an outage. What should you do?", "prompt": {"question": "<p>Your organization enforces Conditional Access policies that require MFA and a compliant device for all users, including every Global Administrator. You need to ensure administrators can still sign in to Microsoft Entra ID if the MFA service or Conditional Access policy engine experiences an outage. What should you do?</p>", "answers": ["<p>Manually disable all Conditional Access policies whenever an outage is suspected</p>", "<p>Create two or more emergency access (\"break-glass\") accounts, exclude them from all Conditional Access policies, protect them with strong non-expiring credentials stored securely offline, avoid syncing them from on-premises AD, and configure alerts on any sign-in to them</p>", "<p>Configure a second Conditional Access policy with a reduced MFA requirement to act as a fallback for administrators</p>", "<p>Grant the emergency access accounts the Global Reader role instead of Global Administrator to reduce the security exposure during an outage</p>"], "feedbacks": ["<p>Manually disabling Conditional Access policies during an outage is reactive, slow, and itself requires administrative access that may be blocked — it is not a resilient design.</p>", "<p>Microsoft's documented emergency access account pattern requires dedicated cloud-only accounts excluded from all Conditional Access policies, with strong offline-stored credentials and active sign-in monitoring, so administrators retain a guaranteed path into the tenant during an identity service outage.</p>", "<p>A fallback policy with reduced MFA requirements weakens security posture permanently and is not the Microsoft-recommended pattern for outage resilience.</p>", "<p>Global Reader is a read-only role and cannot perform the administrative actions (such as re-enabling services or fixing Conditional Access misconfigurations) needed to recover the tenant during an outage — break-glass accounts must retain Global Administrator privileges.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "You create a custom RBAC role named 'Log Reader Restricted' with Actions set to [\"Microsoft.Insights/*/read\"] and NotActions set to [\"Microsoft.Insights/*/delete\"]. You assign this role to a user at the subscription scope. The same user is also a member of a group assigned the built-in Monitoring Contributor role at the same subscription scope. What is the user's effective permission regarding deleting Insights resources?", "prompt": {"question": "<p>You create a custom RBAC role named 'Log Reader Restricted' with Actions set to [\"Microsoft.Insights/*/read\"] and NotActions set to [\"Microsoft.Insights/*/delete\"]. You assign this role to a user at the subscription scope. The same user is also a member of a group assigned the built-in Monitoring Contributor role at the same subscription scope. What is the user's effective permission regarding deleting Insights resources?</p>", "answers": ["<p>The user cannot delete Insights resources because NotActions explicitly denies the delete action</p>", "<p>The role assignment fails at creation time because the two roles conflict, and Azure blocks the assignment</p>", "<p>The user CAN delete Insights resources, because Azure RBAC permissions are additive across separate role assignments — NotActions only subtracts from the Actions listed in the SAME role definition, not from permissions granted by a different role assignment</p>", "<p>The user can delete Insights resources only if the custom role's AssignableScopes explicitly lists the Microsoft.Insights resource provider</p>"], "feedbacks": ["<p>This is the most common misconception — NotActions does not function as an explicit deny; it never overrides permissions granted by an entirely separate role assignment.</p>", "<p>Azure does not detect or block 'conflicting' role assignments; multiple roles can be assigned to the same principal at the same scope without any validation error.</p>", "<p>Azure RBAC is purely additive: NotActions is only used to carve out exceptions within the effective permissions granted by that specific role definition, not an explicit deny across all assignments. Because the user separately holds Monitoring Contributor (which allows delete), the union of permissions grants delete access.</p>", "<p>AssignableScopes only controls where a custom role definition is allowed to be assigned (e.g., which subscriptions or management groups); it has no effect on which actions are permitted once assigned.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "You are designing an automated landing zone deployment strategy for a company adopting Azure. The design must package a set of ARM templates, resource group definitions, and Azure Policy initiative assignments into a versioned artifact that can be repeatedly deployed and tracked as a single lifecycle unit. Azure Blueprints was retired in July 2026 and is unavailable for new deployments. Which combination of services should you use instead?", "prompt": {"question": "<p>You are designing an automated landing zone deployment strategy for a company adopting Azure. The design must package a set of ARM templates, resource group definitions, and Azure Policy initiative assignments into a versioned artifact that can be repeatedly deployed and tracked as a single lifecycle unit. Azure Blueprints was retired in July 2026 and is unavailable for new deployments. Which combination of services should you use instead?</p>", "answers": ["<p>Azure Automation Desired State Configuration (DSC) combined with a Log Analytics workspace</p>", "<p>Azure Resource Manager Template Specs combined with Deployment Stacks, alongside separate Azure Policy initiative assignments</p>", "<p>Microsoft Entra Application Proxy combined with custom RBAC role definitions</p>", "<p>Azure Migrate assessment projects combined with Cost Management budgets</p>"], "feedbacks": ["<p>Automation DSC and Log Analytics are used for VM configuration state management and log collection respectively; they have no capability to package or version ARM templates and policy assignments as a deployable artifact.</p>", "<p>Microsoft's documented replacement pattern for Azure Blueprints uses Template Specs to package and version ARM/Bicep templates, Deployment Stacks to manage the deployed resources as a single lifecycle unit (including deny-delete protection), and separate Azure Policy assignments/initiatives to enforce governance — together replicating Blueprint's artifact-packaging and lifecycle-management capability.</p>", "<p>Application Proxy is an identity feature for publishing on-premises web apps externally and has nothing to do with landing zone infrastructure deployment or governance packaging.</p>", "<p>Azure Migrate assesses on-premises workloads for migration, and Cost Management budgets track spend — neither relates to packaging or deploying landing zone infrastructure artifacts.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has a single centralized Log Analytics workspace collecting logs from resources across all subscriptions. Different application teams must be able to query only the logs belonging to resources they own, without being granted any explicit permission on the shared workspace itself. Which configuration should you apply?", "prompt": {"question": "<p>A company has a single centralized Log Analytics workspace collecting logs from resources across all subscriptions. Different application teams must be able to query only the logs belonging to resources they own, without being granted any explicit permission on the shared workspace itself. Which configuration should you apply?</p>", "answers": ["<p>Set the workspace's access control mode to 'Workspace-context' and assign the Log Analytics Reader role to each team at the workspace scope</p>", "<p>Set the workspace's access control mode to 'Resource-context' and ensure each team has Reader or Monitoring Reader RBAC permission only on the resources they own</p>", "<p>Create a separate Log Analytics workspace per team and configure Azure Lighthouse delegation between workspaces</p>", "<p>Enable a Microsoft Entra Conditional Access policy scoped to the Log Analytics workspace resource to filter query results by resource owner</p>"], "feedbacks": ["<p>Workspace-context mode requires explicit permission at the workspace scope and, once granted, exposes ALL data in the workspace to that principal — it cannot restrict a team to only their own resources' logs.</p>", "<p>Resource-context access control mode allows a user who has RBAC read access on a specific monitored resource to query that resource's logs directly from a shared workspace, without needing any explicit permission granted on the workspace itself — exactly satisfying the isolation requirement while keeping a single centralized workspace.</p>", "<p>Splitting into per-team workspaces defeats the stated requirement for a single centralized workspace, and Azure Lighthouse is designed for cross-tenant delegated administration (e.g., for Managed Service Providers), not intra-tenant log filtering.</p>", "<p>Conditional Access governs authentication and session controls for sign-ins; it has no mechanism to filter or scope Log Analytics query results by resource ownership.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A subscription has an Azure Policy initiative assigned with a Deny effect at a management group, blocking creation of public IP addresses. One resource group needs a temporary, time-limited exception for 30 days to complete a migration, after which the restriction must automatically re-apply with no manual re-enablement step required. What should you configure?", "prompt": {"question": "<p>A subscription has an Azure Policy initiative assigned with a Deny effect at a management group, blocking creation of public IP addresses. One resource group needs a temporary, time-limited exception for 30 days to complete a migration, after which the restriction must automatically re-apply with no manual re-enablement step required. What should you configure?</p>", "answers": ["<p>Create an Azure Policy exemption at the resource group scope with an expiration date set 30 days in the future</p>", "<p>Temporarily move the resource group out of the management group hierarchy for 30 days</p>", "<p>Add the resource group to the policy assignment's 'Excluded scopes' list and remove it manually after 30 days</p>", "<p>Change the policy assignment's effect from Deny to Audit specifically for that resource group</p>"], "feedbacks": ["<p>Azure Policy exemptions are designed exactly for this scenario: they allow a specific scope to be exempted from an assignment's effect for a defined reason, with an optional expiration date, after which enforcement automatically resumes without any manual intervention.</p>", "<p>Moving the resource group out of the management group is a manual, error-prone structural change that also removes it from ALL other policies and governance controls applied at that management group, not just the one in question, and requires manual re-adding.</p>", "<p>Excluded scopes on an assignment are a static configuration, not time-bound — the restriction would remain excluded indefinitely until someone manually edits the assignment, failing the 'automatically re-apply' requirement.</p>", "<p>A single policy assignment applies one uniform effect across its entire assigned scope; you cannot set a different effect (Audit vs Deny) for a specific child resource group within the same assignment.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A global retail company uses Azure Cosmos DB (SQL API) with multi-region writes enabled across three regions. The application must guarantee that a user immediately sees their own writes on their next read within the same session, while keeping RU consumption and latency as low as possible. Which consistency level BEST meets these requirements?", "prompt": {"question": "<p>A global retail company uses Azure Cosmos DB (SQL API) with multi-region writes enabled across three regions. The application must guarantee that a user immediately sees their own writes on their next read within the same session, while keeping RU consumption and latency as low as possible. Which consistency level BEST meets these requirements?</p>", "answers": ["<p>Bounded staleness</p>", "<p>Session consistency</p>", "<p>Consistent prefix</p>", "<p>Strong consistency</p>"], "feedbacks": ["<p>Bounded staleness guarantees reads lag writes by a bounded window or count, but it does not guarantee a user immediately sees their own write, and it consumes more RU than Session for this workload.</p>", "<p>Session consistency guarantees read-your-own-writes and monotonic reads within the client session while still allowing multi-region writes, at far lower latency and RU cost than stronger consistency levels — ideal for user-facing write scenarios in a multi-master account.</p>", "<p>Consistent prefix only guarantees writes are never seen out of order — it provides no freshness guarantee and does not satisfy the 'read your own write' requirement.</p>", "<p>Strong consistency is not supported when multiple write regions are enabled in Cosmos DB, and even where supported it adds the highest possible latency and RU cost.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An IoT platform ingests telemetry from 50 million devices into a Cosmos DB container. A small percentage of devices are far more active than the rest, and queries frequently filter by device and by date. The current partition key of deviceId is causing hot partitions on the busiest devices. Which partition key strategy BEST resolves this while keeping queries efficient?", "prompt": {"question": "<p>An IoT platform ingests telemetry from 50 million devices into a Cosmos DB container. A small percentage of devices are far more active than the rest, and queries frequently filter by device and by date. The current partition key of deviceId is causing hot partitions on the busiest devices. Which partition key strategy BEST resolves this while keeping queries efficient?</p>", "answers": ["<p>Use deviceId alone as the partition key</p>", "<p>Use date alone as the partition key</p>", "<p>Use a synthetic partition key that combines deviceId and date (e.g., deviceId_date)</p>", "<p>Use a randomly generated GUID as the partition key</p>"], "feedbacks": ["<p>deviceId alone still causes a hot partition because a small subset of devices generate a disproportionate share of writes, concentrating RU consumption on a few physical partitions.</p>", "<p>Partitioning by date alone concentrates all of 'today's' writes onto a single logical partition, an extreme hot-partition scenario, and yields very low overall cardinality.</p>", "<p>Combining deviceId and date creates a high-cardinality synthetic key that spreads writes across many logical partitions, even for the busiest devices, while still enabling efficient queries filtered by device and date without cross-partition fan-out.</p>", "<p>A random GUID distributes writes evenly but destroys query locality — every device/date query would require an expensive cross-partition fan-out scan.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services firm must retain trade records for 7 years in Azure Blob Storage in a way that even a Storage Account Owner cannot alter or delete during that period, satisfying regulator audit requirements. During active litigation, some records also need an indefinite legal hold applied without disturbing the retention timers on unrelated blobs. Which configuration BEST meets these requirements?", "prompt": {"question": "<p>A financial services firm must retain trade records for 7 years in Azure Blob Storage in a way that even a Storage Account Owner cannot alter or delete during that period, satisfying regulator audit requirements. During active litigation, some records also need an indefinite legal hold applied without disturbing the retention timers on unrelated blobs. Which configuration BEST meets these requirements?</p>", "answers": ["<p>Enable soft delete on the blob container with a 2555-day retention period</p>", "<p>Set the storage account to read-only using an Azure RBAC deny assignment</p>", "<p>Configure version-level immutability policies with time-based retention and apply legal holds to specific blob versions</p>", "<p>Enable Azure Backup for the storage account with vaulted backups</p>"], "feedbacks": ["<p>Soft delete only protects against accidental deletion by allowing recovery of removed data — it does not prevent an existing blob from being modified and is not considered compliance-grade WORM storage.</p>", "<p>An RBAC deny assignment can be edited or removed by anyone with sufficient administrative permissions, so it cannot provide the tamper-proof, auditable guarantee regulators require.</p>", "<p>Version-level immutability policies provide WORM (write once, read many) protection that no principal, including an Owner, can override during the retention period, and legal holds can be applied per version independently of the time-based policy on other blobs — this satisfies compliant, auditable immutability.</p>", "<p>Azure Backup creates recoverable copies of data but does not enforce immutability or WORM compliance on the original blobs themselves.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company is migrating an on-premises SQL Server 2016 workload that heavily relies on SQL Server Agent jobs, cross-database transactions, linked servers, and CLR integration. The target platform must offer near-100% engine compatibility, built-in automatic high availability without manually configuring Availability Groups, no OS patching responsibility, and in-memory OLTP performance. Which target BEST meets all requirements?", "prompt": {"question": "<p>A company is migrating an on-premises SQL Server 2016 workload that heavily relies on SQL Server Agent jobs, cross-database transactions, linked servers, and CLR integration. The target platform must offer near-100% engine compatibility, built-in automatic high availability without manually configuring Availability Groups, no OS patching responsibility, and in-memory OLTP performance. Which target BEST meets all requirements?</p>", "answers": ["<p>Azure SQL Database, Hyperscale service tier</p>", "<p>SQL Server on an Azure VM with Always On Availability Groups</p>", "<p>Azure SQL Database, serverless compute tier</p>", "<p>Azure SQL Managed Instance, Business Critical service tier</p>"], "feedbacks": ["<p>Hyperscale is a single-database deployment option — it does not support cross-database transactions, SQL Agent jobs, or full instance-scoped compatibility.</p>", "<p>SQL Server on a VM does support Agent, CLR, and cross-database features, but it requires the customer to design, configure, and maintain the Availability Group and patch the OS, failing the 'minimal management overhead' requirement.</p>", "<p>Serverless is a single-database compute tier intended for intermittent workloads and lacks instance-level features like cross-database transactions and SQL Agent.</p>", "<p>Managed Instance provides near-100% SQL Server engine compatibility, including SQL Agent, cross-database transactions, linked servers, and CLR, and the Business Critical tier includes built-in automatic HA (three synchronous replicas plus in-memory OLTP) with no manual Availability Group configuration or OS patching required.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An application running on Azure Database for PostgreSQL Flexible Server must survive a complete failure of an entire Azure availability zone with automatic failover and near-zero RPO, and the standby replica must reside in a different zone than the primary. Which configuration BEST satisfies this requirement?", "prompt": {"question": "<p>An application running on Azure Database for PostgreSQL Flexible Server must survive a complete failure of an entire Azure availability zone with automatic failover and near-zero RPO, and the standby replica must reside in a different zone than the primary. Which configuration BEST satisfies this requirement?</p>", "answers": ["<p>Enable Same-zone high availability</p>", "<p>Configure read replicas in a different Azure region</p>", "<p>Enable Zone-redundant high availability</p>", "<p>Use Azure Database for PostgreSQL Single Server with geo-redundant backup</p>"], "feedbacks": ["<p>Same-zone HA places the standby in the same availability zone as the primary, so it protects against node-level failures but not a zone-wide outage.</p>", "<p>Cross-region read replicas use asynchronous replication and require manual promotion, resulting in higher RPO and no automatic failover.</p>", "<p>Zone-redundant HA deploys the standby replica in a different availability zone from the primary, using synchronous replication with automatic failover, providing protection against a full zone/datacenter failure with near-zero RPO.</p>", "<p>Single Server is a legacy deployment option being retired, and geo-redundant backup only supports restoring from backup — it provides no automatic failover and a much higher RPO.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A media company stores read-heavy static assets in an Azure Storage account. The design must tolerate the loss of an entire datacenter within the primary region via synchronous replication, and must also allow the application to read data from a secondary region immediately during a regional outage, without waiting for a failover to complete. Which redundancy option should be selected?", "prompt": {"question": "<p>A media company stores read-heavy static assets in an Azure Storage account. The design must tolerate the loss of an entire datacenter within the primary region via synchronous replication, and must also allow the application to read data from a secondary region immediately during a regional outage, without waiting for a failover to complete. Which redundancy option should be selected?</p>", "answers": ["<p>LRS (Locally Redundant Storage)</p>", "<p>GRS (Geo-Redundant Storage)</p>", "<p>ZRS (Zone-Redundant Storage)</p>", "<p>RA-GZRS (Read-Access Geo-Zone-Redundant Storage)</p>"], "feedbacks": ["<p>LRS only replicates within a single datacenter and provides no protection against a zone or region failure.</p>", "<p>GRS replicates to a secondary region but uses only LRS within the primary region (no zone redundancy), and it does not allow read access to the secondary region unless it is also configured as RA-GRS.</p>", "<p>ZRS protects against a zone failure within the primary region but does not replicate data to a secondary region, so it offers no protection against a regional outage.</p>", "<p>RA-GZRS combines synchronous zone-redundant replication within the primary region (surviving a datacenter/zone failure) with asynchronous geo-replication to a secondary region, and the 'RA' capability grants read access to the secondary region's data at any time, even before a failover occurs.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A global retail platform uses Azure Cosmos DB (SQL API) to store shopping cart data. Business requirements state: (1) all clients globally must observe writes in the same order, never out of order, (2) reads may lag behind writes by at most a few seconds, and (3) write latency must stay low across multiple write regions. Which consistency level should be configured?", "prompt": {"question": "<p>A global retail platform uses Azure Cosmos DB (SQL API) to store shopping cart data. Business requirements state: (1) all clients globally must observe writes in the same order, never out of order, (2) reads may lag behind writes by at most a few seconds, and (3) write latency must stay low across multiple write regions. Which consistency level should be configured?</p>", "answers": ["<p>Strong</p>", "<p>Session</p>", "<p>Eventual</p>", "<p>Bounded Staleness</p>"], "feedbacks": ["<p>Strong consistency requires synchronous replication across regions, which adds significant write latency and is not supported with multiple write regions.</p>", "<p>Session consistency only guarantees monotonic ordering within a single client's session token, not global ordering across all clients.</p>", "<p>Eventual consistency provides no ordering guarantee at all — clients could see writes in any order, violating the requirement.</p>", "<p>Bounded Staleness guarantees consistent prefix ordering globally (no client ever sees writes out of order) while bounding the lag by a configurable time interval or number of versions, and it supports multi-region writes with lower latency than Strong consistency.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services firm must retain trade confirmation blobs in Azure Storage for exactly 7 years to meet regulatory requirements. During that period, the data must be unmodifiable and undeletable by anyone, including the storage account owner or an administrator with full RBAC permissions, and the retention period must automatically enforce this without ongoing manual action. Which feature should be configured?", "prompt": {"question": "<p>A financial services firm must retain trade confirmation blobs in Azure Storage for exactly 7 years to meet regulatory requirements. During that period, the data must be unmodifiable and undeletable by anyone, including the storage account owner or an administrator with full RBAC permissions, and the retention period must automatically enforce this without ongoing manual action. Which feature should be configured?</p>", "answers": ["<p>Apply a time-based retention immutability policy in the Locked state</p>", "<p>Enable soft delete on the storage account</p>", "<p>Apply a legal hold on the container</p>", "<p>Configure Azure Backup to protect the storage account</p>"], "feedbacks": ["<p>A time-based retention immutability policy, once set to Locked, enforces WORM (write once, read many) protection for the exact configured duration and cannot be shortened or removed by any user, including the account owner — it can only be extended, satisfying the fixed 7-year regulatory requirement automatically.</p>", "<p>Soft delete allows recovery of deleted blobs within a retention window, but it does not prevent an account owner with sufficient permissions from eventually purging or overwriting data, and it has no compliance-grade lock.</p>", "<p>Legal hold prevents deletion indefinitely until manually removed by an authorized user — it has no automatic time-based expiration, so it doesn't enforce a fixed 7-year period on its own.</p>", "<p>Azure Backup protects against accidental data loss via backup/restore but does not provide WORM immutability guarantees for blob data.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company is migrating an on-premises SQL Server database to Azure. The application relies heavily on SQL Server Agent jobs, cross-database queries joining three databases, and linked servers to another system. The company wants near 100% engine compatibility with minimal ongoing patching and OS management overhead. Which service should be used?", "prompt": {"question": "<p>A company is migrating an on-premises SQL Server database to Azure. The application relies heavily on SQL Server Agent jobs, cross-database queries joining three databases, and linked servers to another system. The company wants near 100% engine compatibility with minimal ongoing patching and OS management overhead. Which service should be used?</p>", "answers": ["<p>Azure SQL Database (single database)</p>", "<p>Azure SQL Managed Instance</p>", "<p>SQL Server on an Azure VM</p>", "<p>Azure SQL Database elastic pool</p>"], "feedbacks": ["<p>Azure SQL Database does not support cross-database queries or SQL Server Agent, and lacks full instance-scoped features required here.</p>", "<p>Azure SQL Managed Instance is a PaaS offering with near 100% SQL Server engine compatibility, and it natively supports SQL Server Agent, cross-database queries, and linked servers, while Microsoft manages OS and engine patching.</p>", "<p>SQL Server on an Azure VM would support all these features but requires the customer to manage OS patching, backups, and clustering — exactly the overhead the company wants to avoid.</p>", "<p>An elastic pool is a set of single databases sharing resources; it inherits the same cross-database and SQL Agent limitations as Azure SQL Database.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An application uses Azure Database for PostgreSQL Flexible Server. The company requires automatic failover to a fully synchronized standby in the event an entire Azure Availability Zone becomes unavailable, with no data loss and no manual intervention. Which configuration meets this requirement?", "prompt": {"question": "<p>An application uses Azure Database for PostgreSQL Flexible Server. The company requires automatic failover to a fully synchronized standby in the event an entire Azure Availability Zone becomes unavailable, with no data loss and no manual intervention. Which configuration meets this requirement?</p>", "answers": ["<p>Deploy a read replica in a different region</p>", "<p>Enable same-zone high availability</p>", "<p>Enable zone-redundant high availability</p>", "<p>Configure geo-redundant backup</p>"], "feedbacks": ["<p>A cross-region read replica uses asynchronous replication and requires manual promotion — it doesn't provide automatic zero-data-loss failover.</p>", "<p>Same-zone HA places the standby in the same availability zone as the primary, so it does not protect against a zone failure.</p>", "<p>Zone-redundant HA deploys a synchronously replicated standby server in a different availability zone within the same region and performs automatic failover if the primary zone fails, providing zero data loss protection against a zone-level outage.</p>", "<p>Geo-redundant backup only enables restoring data to another region after an outage; it doesn't provide automatic failover or a live standby.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An IoT solution stores telemetry in Azure Cosmos DB (SQL API) partitioned on the property 'deviceType', which has only 5 distinct values. As the number of connected devices has grown into the millions, the workload experiences frequent 429 (throttling) errors even though the container's RU/s has already been increased multiple times. What is the BEST solution?", "prompt": {"question": "<p>An IoT solution stores telemetry in Azure Cosmos DB (SQL API) partitioned on the property 'deviceType', which has only 5 distinct values. As the number of connected devices has grown into the millions, the workload experiences frequent 429 (throttling) errors even though the container's RU/s has already been increased multiple times. What is the BEST solution?</p>", "answers": ["<p>Increase the provisioned RU/s further</p>", "<p>Enable autoscale throughput on the container</p>", "<p>Change the partition key to a high-cardinality property such as deviceId</p>", "<p>Add a composite index on the deviceType and timestamp properties</p>"], "feedbacks": ["<p>Increasing RU/s raises cost but throughput is still capped per physical partition (max 10,000 RU/s per partition), so hot partitions will continue to throttle regardless of the total provisioned RU/s.</p>", "<p>Autoscale adjusts RU/s dynamically within a range but does not resolve uneven distribution across partitions — hot partitions will still throttle at the autoscale max.</p>", "<p>With only 5 distinct values, 'deviceType' creates hot logical partitions that each accumulate a huge share of the storage and RU consumption, since Cosmos DB spreads throughput across physical partitions based on partition key distribution. Choosing a high-cardinality key like deviceId (or a synthetic key combining deviceType and deviceId) evenly distributes requests and storage across many partitions, resolving the throttling at its root cause.</p>", "<p>Indexing affects query performance, not RU distribution across partitions, and does not address the throttling caused by partition key skew.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company stores critical data in an Azure Storage account. Requirements: data must be synchronously replicated across at least three availability zones within the primary region to survive a zone outage with zero data loss, AND the application must be able to read the data from a secondary region if the entire primary region becomes unavailable. Which redundancy option should be selected?", "prompt": {"question": "<p>A company stores critical data in an Azure Storage account. Requirements: data must be synchronously replicated across at least three availability zones within the primary region to survive a zone outage with zero data loss, AND the application must be able to read the data from a secondary region if the entire primary region becomes unavailable. Which redundancy option should be selected?</p>", "answers": ["<p>Locally redundant storage (LRS)</p>", "<p>Zone-redundant storage (ZRS)</p>", "<p>Read-access geo-redundant storage (RA-GRS)</p>", "<p>Read-access geo-zone-redundant storage (RA-GZRS)</p>"], "feedbacks": ["<p>LRS only replicates within a single data center and provides no zone or region resilience.</p>", "<p>ZRS replicates synchronously across zones in the primary region but has no secondary region copy, so it cannot satisfy the cross-region read requirement.</p>", "<p>RA-GRS replicates the primary region using LRS (a single location, not zone-redundant) before geo-replicating to the secondary, so it does not protect against a zone failure in the primary region.</p>", "<p>RA-GZRS combines zone-redundant storage in the primary region (synchronous replication across three availability zones) with asynchronous geo-replication to a secondary region, and grants read access to that secondary region's data — satisfying both the zone-resilience and cross-region read requirements.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a mission-critical Azure SQL Database (PaaS, not a Managed Instance) that must automatically fail over to a paired region with an RPO of about 5 seconds and no application connection string changes. Which design meets this requirement?", "prompt": {"question": "<p>A company runs a mission-critical Azure SQL Database (PaaS, not a Managed Instance) that must automatically fail over to a paired region with an RPO of about 5 seconds and no application connection string changes. Which design meets this requirement?</p>", "answers": ["<p>Configure an auto-failover group with active geo-replication</p>", "<p>Configure Always On availability groups on Azure SQL Database</p>", "<p>Configure manual active geo-replication only</p>", "<p>Protect the database with Azure Site Recovery</p>"], "feedbacks": ["<p>Auto-failover groups build on active geo-replication and add a listener endpoint plus automatic (or triggered) failover, giving a low RPO (typically seconds) without changing the app's connection string.</p>", "<p>Always On availability groups are a SQL Server on Azure VM (IaaS) technology, not something you configure directly on the Azure SQL Database PaaS service.</p>", "<p>Manual active geo-replication requires an admin to trigger failover manually, so it can't meet an automatic-failover requirement and increases effective RTO/operational risk.</p>", "<p>Azure Site Recovery does not support replicating Azure SQL Database as a PaaS resource; it targets VMs and some other workloads, not this service.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A security team is concerned that a compromised Global Administrator account could delete or disable backups in a Recovery Services vault before ransomware is detected, defeating the recovery strategy. Which single configuration change on the vault BEST mitigates this risk?", "prompt": {"question": "<p>A security team is concerned that a compromised Global Administrator account could delete or disable backups in a Recovery Services vault before ransomware is detected, defeating the recovery strategy. Which single configuration change on the vault BEST mitigates this risk?</p>", "answers": ["<p>Enable soft delete only (default 14-day retention)</p>", "<p>Apply an Azure Resource Manager lock (CanNotDelete) to the Recovery Services vault</p>", "<p>Enable vault immutability (locked) together with Multi-User Authorization (MUA) on the Recovery Services vault</p>", "<p>Configure geo-redundant storage (GRS) for the vault</p>"], "feedbacks": ["<p>Soft delete alone can itself be disabled by an account with sufficient vault permissions, and the 14-day window may not be enough time to detect and respond to an attack.</p>", "<p>A CanNotDelete resource lock only blocks ARM-level deletion/update of the vault resource; it does not prevent backup-specific operations like deleting recovery points or disabling protection from within the Backup service.</p>", "<p>Locked immutability prevents backup data from being deleted or having its retention shortened, and MUA (via Azure Resource Guard) requires approval from a separate, isolated authority for critical operations, protecting against a single compromised account.</p>", "<p>GRS improves durability against a regional outage but does nothing to stop a malicious or compromised identity from deleting backup data through normal Backup service operations.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "You are configuring an Azure Site Recovery replication policy for Azure VM-to-Azure DR. The business requires the ability to recover using a recovery point up to 5 days old. Crash-consistent recovery points are generated automatically at a fixed interval that cannot be changed. What should you configure?", "prompt": {"question": "<p>You are configuring an Azure Site Recovery replication policy for Azure VM-to-Azure DR. The business requires the ability to recover using a recovery point up to 5 days old. Crash-consistent recovery points are generated automatically at a fixed interval that cannot be changed. What should you configure?</p>", "answers": ["<p>Set the crash-consistent recovery point interval to 5 days</p>", "<p>Enable app-consistent snapshots every 5 days and disable crash-consistent points</p>", "<p>Set 'Recovery point retention' to at least 120 hours in the replication policy, leaving the crash-consistent recovery point interval at its fixed 5-minute default</p>", "<p>Configure a custom backup policy in the Recovery Services vault instead of a replication policy</p>"], "feedbacks": ["<p>The crash-consistent point interval for Azure-to-Azure replication is fixed at 5 minutes and cannot be changed to 5 days.</p>", "<p>App-consistent snapshot frequency can only be set up to 12 hours, not 5 days, and disabling crash-consistent points removes the frequent recovery points needed for a low RPO.</p>", "<p>For Azure VM-to-Azure replication, crash-consistent recovery points are generated automatically every 5 minutes and this interval isn't user-configurable; the retention window (how far back you can restore) is configurable up to 15 days, so setting retention to at least 120 hours satisfies the 5-day requirement.</p>", "<p>Backup policies in a Recovery Services vault configure Azure Backup schedules, a separate construct from the ASR replication policy that governs Site Recovery recovery points.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A global retail platform uses Azure Cosmos DB and requires zero data loss (RPO = 0) along with active-active multi-region writes for the lowest possible write latency worldwide. Which design should you recommend?", "prompt": {"question": "<p>A global retail platform uses Azure Cosmos DB and requires zero data loss (RPO = 0) along with active-active multi-region writes for the lowest possible write latency worldwide. Which design should you recommend?</p>", "answers": ["<p>Disable multi-region writes, use a single write region with Strong consistency, and add additional regions as read replicas with automatic failover for RTO</p>", "<p>Enable multi-region writes with Session consistency across all regions</p>", "<p>Enable multi-region writes with Strong consistency across all regions</p>", "<p>Enable multi-region writes with Bounded Staleness and a staleness window of 0 seconds</p>"], "feedbacks": ["<p>Cosmos DB Strong consistency (which is required to guarantee RPO = 0) is only available with a single write region; other regions can be added as read replicas with automatic failover to satisfy RTO, but true zero-data-loss multi-master writes are not achievable.</p>", "<p>Session consistency does not guarantee zero data loss across regions and is incompatible with an RPO = 0 requirement.</p>", "<p>Cosmos DB does not allow Strong consistency to be combined with multi-region writes at all — Strong consistency is disabled the moment multi-region writes are enabled.</p>", "<p>A Bounded Staleness window of 0 seconds is not a valid/meaningful configuration under multi-master writes, and staleness still permits some replication lag, so it cannot guarantee RPO = 0.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "You need a VM-based application tier design that qualifies for Azure's guaranteed 99.99% compute SLA. Which configuration meets this requirement?", "prompt": {"question": "<p>You need a VM-based application tier design that qualifies for Azure's guaranteed 99.99% compute SLA. Which configuration meets this requirement?</p>", "answers": ["<p>Deploy two VMs with Premium SSD disks in the same Availability Set</p>", "<p>Deploy a single VM using Ultra Disk storage</p>", "<p>Deploy two VMs with Standard HDD disks in the same Availability Set</p>", "<p>Deploy two or more VMs with Premium SSD disks, one instance in each of three Availability Zones</p>"], "feedbacks": ["<p>Two VMs in the same Availability Set (with Premium disks) qualify for 99.95%, not 99.99% — Availability Zones are required for the higher tier.</p>", "<p>A single VM, even with Ultra Disk, has no compute-instance redundancy and is only eligible for the 99.9% single-instance SLA (which itself requires all Premium/Ultra disks).</p>", "<p>VMs in an Availability Set are only SLA-eligible at all if every disk is Premium SSD or Ultra Disk; Standard HDD disqualifies the deployment from any Azure compute SLA.</p>", "<p>Azure guarantees 99.99% VM availability when instances are deployed across two or more Availability Zones within a region.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Azure VMs are protected in a Recovery Services vault configured with geo-redundant storage (GRS). A regional outage occurs in the primary region, and you need to restore the VMs in the paired secondary region during the outage. What must have been configured in advance for this to be possible?", "prompt": {"question": "<p>Azure VMs are protected in a Recovery Services vault configured with geo-redundant storage (GRS). A regional outage occurs in the primary region, and you need to restore the VMs in the paired secondary region during the outage. What must have been configured in advance for this to be possible?</p>", "answers": ["<p>Enable the Cross Region Restore (CRR) setting on the vault while it was still configured with GRS, before the outage occurred</p>", "<p>Nothing extra — GRS automatically allows restore operations in the secondary region at any time</p>", "<p>Convert the vault storage redundancy to LRS before the outage</p>", "<p>Create a new Recovery Services vault in the secondary region and manually copy the backup data after the outage begins</p>"], "feedbacks": ["<p>Cross Region Restore is an explicit opt-in setting on a GRS-configured vault that must be enabled before the outage; once enabled, backup data replicated to the secondary region becomes restorable there during a regional outage.</p>", "<p>GRS replicates backup data for durability, but restoring from the secondary region is not exposed by default — CRR must be explicitly enabled in advance.</p>", "<p>LRS keeps backup data only within the primary region and provides no geo-redundancy, so it cannot support any secondary-region restore.</p>", "<p>Manually copying backup data after an outage begins is generally not feasible, since the primary region's control plane and data may be inaccessible, and this is not how Azure Backup's CRR mechanism works.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A global retailer's web application requires: SSL offload, a Web Application Firewall (WAF), path-based routing across three Azure regions, and automatic failover if a regional backend becomes unhealthy. Which single service BEST meets ALL these requirements?", "prompt": {"question": "<p>A global retailer's web application requires: SSL offload, a Web Application Firewall (WAF), path-based routing across three Azure regions, and automatic failover if a regional backend becomes unhealthy. Which single service BEST meets ALL these requirements?</p>", "answers": ["<p>Azure Traffic Manager with priority routing</p>", "<p>Application Gateway v2 deployed in each region with manual DNS failover</p>", "<p>Azure Load Balancer (Standard SKU) with cross-region load balancing</p>", "<p>Azure Front Door (Premium tier)</p>"], "feedbacks": ["<p>Traffic Manager is DNS-based (Layer 3), has no WAF or path-based routing, and failover relies on DNS TTL expiry which introduces delay.</p>", "<p>Application Gateway is regional; you'd need Front Door or Traffic Manager on top to route across regions, so it alone doesn't satisfy the global requirement.</p>", "<p>Standard Load Balancer operates at Layer 4 and cannot inspect URLs, offload SSL, or provide WAF capabilities.</p>", "<p>Front Door Premium operates at Layer 7, provides global anycast entry, integrated WAF, path-based/URL routing, SSL offload, and automatic health-probe-based failover across regions from a single global service.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has an ExpressRoute circuit as primary connectivity and a Site-to-Site VPN Gateway configured in coexistence mode as backup, both connected to the same virtual network. During a planned ExpressRoute maintenance window, traffic did not fail over to the VPN Gateway as expected until the circuit was fully down. What is the MOST likely cause?", "prompt": {"question": "<p>A company has an ExpressRoute circuit as primary connectivity and a Site-to-Site VPN Gateway configured in coexistence mode as backup, both connected to the same virtual network. During a planned ExpressRoute maintenance window, traffic did not fail over to the VPN Gateway as expected until the circuit was fully down. What is the MOST likely cause?</p>", "answers": ["<p>BGP AS-path prepending was not configured on the VPN Gateway connection</p>", "<p>The VPN Gateway SKU was too small to accept traffic during ExpressRoute maintenance</p>", "<p>Azure always prefers routes learned via ExpressRoute over routes learned via the VPN Gateway, regardless of AS-path length, until the ExpressRoute path is actually unavailable</p>", "<p>The Local Network Gateway was misconfigured with an incorrect address space</p>"], "feedbacks": ["<p>AS-path prepending affects preference between two BGP peers of similar priority, but ExpressRoute is preferred by Azure regardless of AS-path length, so prepending would not change this behavior.</p>", "<p>VPN Gateway SKU size affects throughput, not route preference — undersizing would cause performance issues, not delayed failover.</p>", "<p>Azure's route selection always prioritizes ExpressRoute over VPN Gateway paths as a platform behavior, independent of any BGP AS-path prepending on the VPN side — failover only occurs once the ExpressRoute path is genuinely down, which explains the observed behavior during maintenance (brief BGP convergence delay is expected, not a misconfiguration).</p>", "<p>A misconfigured Local Network Gateway address space would typically cause complete connectivity failure over VPN, not merely a delay in failover.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company wants to deploy AKS such that the Kubernetes API server has NO public IP address and is reachable only from their on-premises network over an existing ExpressRoute private peering connection. Which design satisfies this requirement?", "prompt": {"question": "<p>A financial services company wants to deploy AKS such that the Kubernetes API server has NO public IP address and is reachable only from their on-premises network over an existing ExpressRoute private peering connection. Which design satisfies this requirement?</p>", "answers": ["<p>Deploy a private AKS cluster and configure a private DNS zone linked to the on-premises network via Azure Private DNS Resolver (or a custom DNS forwarder VM)</p>", "<p>Deploy a public AKS cluster and restrict access using API server authorized IP ranges scoped to the on-premises CIDR</p>", "<p>Deploy AKS with an internal load balancer for the API server and expose it via Azure Front Door</p>", "<p>Deploy a public AKS cluster behind Azure Firewall with DNAT rules for API traffic</p>"], "feedbacks": ["<p>A private AKS cluster provisions the API server with only a private IP in the cluster's VNet. Because the API server FQDN resolves via a private DNS zone, on-premises clients need DNS resolution forwarded to Azure (via Private DNS Resolver or a forwarder VM) over ExpressRoute private peering to reach it — satisfying the 'no public IP' requirement.</p>", "<p>Authorized IP ranges on a public cluster still expose the API server via a public IP; it restricts source IPs but does not eliminate the public endpoint, failing the 'no public IP' requirement.</p>", "<p>Front Door is designed for HTTP(S) application traffic, not Kubernetes API server (mTLS-based) traffic, and doesn't apply to private cluster control-plane access.</p>", "<p>Azure Firewall DNAT would still require a public-facing entry point and adds unnecessary complexity versus the native private cluster feature designed for this exact scenario.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company must migrate a 5TB on-premises SQL Server database to Azure with the LEAST possible downtime during cutover, while allowing the source database to remain online and serving production traffic during the majority of the migration window. Which approach BEST meets this requirement?", "prompt": {"question": "<p>A company must migrate a 5TB on-premises SQL Server database to Azure with the LEAST possible downtime during cutover, while allowing the source database to remain online and serving production traffic during the majority of the migration window. Which approach BEST meets this requirement?</p>", "answers": ["<p>Use Azure Migrate: Server Migration to lift-and-shift the entire VM, then restore the database from backup</p>", "<p>Use Azure Database Migration Service in online (continuous replication) migration mode</p>", "<p>Export a BACPAC file and import it into Azure SQL Database using SqlPackage</p>", "<p>Use the Data Migration Assistant to assess compatibility, then perform a manual detach/attach migration</p>"], "feedbacks": ["<p>Server Migration replicates the whole VM at the infrastructure level; it doesn't provide continuous, transactionally-consistent database sync and would require significant downtime to finalize.</p>", "<p>Azure Database Migration Service's online migration mode performs an initial full backup/restore followed by continuous transaction log replication, keeping the source database live and in sync until a brief final cutover — minimizing downtime to just the final switchover.</p>", "<p>BACPAC export/import is an offline, point-in-time operation on a database that must be taken offline (or frozen) for consistency, and is impractical/slow at 5TB scale.</p>", "<p>Data Migration Assistant only assesses compatibility and generates schema scripts — it doesn't perform data migration or replication itself, and detach/attach requires the database to be fully offline.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An IoT platform ingests millions of telemetry events per second, needs events partitioned and processed in the exact order they arrived per device, and requires the ability to reprocess the last 5 days of events for reprocessing/debugging by resetting a stream offset. Which service BEST fits this requirement?", "prompt": {"question": "<p>An IoT platform ingests millions of telemetry events per second, needs events partitioned and processed in the exact order they arrived per device, and requires the ability to reprocess the last 5 days of events for reprocessing/debugging by resetting a stream offset. Which service BEST fits this requirement?</p>", "answers": ["<p>Azure Event Hubs with device ID used as the partition key and extended retention configured</p>", "<p>Azure Service Bus Queue with sessions enabled</p>", "<p>Azure Event Grid with a custom topic and event subscriptions</p>", "<p>Azure Storage Queues with poison message handling</p>"], "feedbacks": ["<p>Event Hubs is built for high-throughput event streaming, partitions events by a partition key (here, device ID) to preserve per-partition order, and supports configurable retention (up to 7 days, longer with Premium/Dedicated) that allows consumers to reset their offset and replay historical events — exactly matching the reprocessing requirement.</p>", "<p>Service Bus sessions provide ordered, related-message grouping, but once a message is consumed and completed it's removed from the queue — there's no offset-based replay mechanism for 5 days of history.</p>", "<p>Event Grid is a push-based eventing service for reactive, discrete events (not high-throughput streaming) and does not retain a durable, replayable log of events.</p>", "<p>Storage Queues provide simple, at-least-once queuing without partition-based ordering guarantees or offset-based replay capability, and are not designed for millions of events per second.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A development team wants to deploy several containerized microservices that must scale to zero instances when idle, scale out automatically based on custom event metrics (such as queue length) using KEDA, and require NO Kubernetes cluster management overhead. Which compute service BEST meets these requirements?", "prompt": {"question": "<p>A development team wants to deploy several containerized microservices that must scale to zero instances when idle, scale out automatically based on custom event metrics (such as queue length) using KEDA, and require NO Kubernetes cluster management overhead. Which compute service BEST meets these requirements?</p>", "answers": ["<p>Azure Kubernetes Service with the cluster autoscaler enabled</p>", "<p>Azure Container Apps</p>", "<p>Azure Functions Premium plan</p>", "<p>Azure Batch with auto-scaling pools</p>"], "feedbacks": ["<p>AKS requires the team to manage the Kubernetes cluster (nodes, upgrades, control plane considerations for non-managed parts), directly violating the 'no cluster management overhead' requirement even with autoscaler enabled.</p>", "<p>Azure Container Apps is a fully managed serverless container platform built on Kubernetes and KEDA under the hood, supporting scale-to-zero and event-driven autoscaling (including custom KEDA scalers like queue length) without exposing any Kubernetes cluster management to the user.</p>", "<p>Functions Premium supports scale-to-zero-like behavior (with pre-warmed instances) but is designed for discrete function executions, not for running arbitrary long-lived containerized microservices with custom KEDA scalers.</p>", "<p>Azure Batch is designed for large-scale parallel and batch compute jobs, not for hosting persistent containerized microservices with HTTP endpoints and event-driven scaling.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A global retail company runs an App Service-based web application in three Azure regions: East US, West Europe, and Southeast Asia. They need to route users to the closest healthy region, terminate SSL at the edge, apply a Web Application Firewall to block SQL injection and XSS attacks, and perform path-based routing to different backend pools within each region. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A global retail company runs an App Service-based web application in three Azure regions: East US, West Europe, and Southeast Asia. They need to route users to the closest healthy region, terminate SSL at the edge, apply a Web Application Firewall to block SQL injection and XSS attacks, and perform path-based routing to different backend pools within each region. Which solution BEST meets these requirements?</p>", "answers": ["<p>Azure Front Door (Premium tier) with WAF policies and routing rules</p>", "<p>Azure Traffic Manager with priority routing method</p>", "<p>Azure Load Balancer (Standard SKU) with a public frontend in each region</p>", "<p>Application Gateway (WAF_v2 SKU) deployed in each region</p>"], "feedbacks": ["<p>Azure Front Door Premium operates at Layer 7 on Microsoft's global edge network, providing anycast-based latency routing to the nearest healthy backend, SSL offload, integrated WAF with managed rule sets (including SQLi/XSS protection), and path-based routing rules — all in a single global service.</p>", "<p>Traffic Manager is DNS-based load balancing only; it does not terminate SSL, inspect traffic, or provide a WAF, and DNS TTL caching causes slower failover than Front Door's real-time health probing.</p>", "<p>Azure Load Balancer is a Layer 4 regional service — it cannot do SSL offload, WAF inspection, or path-based routing, and it doesn't route across regions at all.</p>", "<p>Application Gateway WAF_v2 provides WAF and path-based routing but is a regional resource; deploying it in each region still requires a global traffic distribution layer in front of it, so it alone does not meet the 'route to nearest region' requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has a single ExpressRoute circuit connecting their on-premises datacenter to an Azure hub virtual network. They require that if the ExpressRoute circuit becomes unavailable, traffic automatically fails over to a Site-to-Site VPN connection without any manual intervention. Which solution meets this requirement?", "prompt": {"question": "<p>A company has a single ExpressRoute circuit connecting their on-premises datacenter to an Azure hub virtual network. They require that if the ExpressRoute circuit becomes unavailable, traffic automatically fails over to a Site-to-Site VPN connection without any manual intervention. Which solution meets this requirement?</p>", "answers": ["<p>Provision a second ExpressRoute circuit in a different peering location</p>", "<p>Configure ExpressRoute and VPN Gateway coexistence in the same virtual network, using BGP to control route preference</p>", "<p>Configure Azure Traffic Manager to distribute traffic between the ExpressRoute and VPN endpoints</p>", "<p>Manually update the route tables to point to the VPN gateway whenever ExpressRoute goes down</p>"], "feedbacks": ["<p>A second ExpressRoute circuit improves ExpressRoute resiliency but does not provide failover to a VPN connection, and doubles circuit cost without meeting the stated requirement.</p>", "<p>ExpressRoute/VPN Gateway coexistence deploys both gateways in the same GatewaySubnet. With BGP enabled, ExpressRoute routes are advertised with a lower AS path length (preferred), and if the circuit drops, BGP automatically withdraws those routes so traffic fails over to the VPN path with no manual action — this is the documented Microsoft pattern for ExpressRoute resiliency.</p>", "<p>Traffic Manager is a DNS-based load balancer for public-facing endpoints; it has no concept of private connectivity paths like ExpressRoute circuits or VPN tunnels and cannot control network-layer routing.</p>", "<p>Manually updating route tables is explicitly not automatic and introduces downtime while waiting for a human to notice and act — this violates the core requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has a queue-triggered processing workload where jobs run for up to 45 minutes each, use custom Linux container images with specific library dependencies, and occur sporadically (sometimes zero jobs for hours). The architect must minimize cost during idle periods while supporting long-running executions. Which compute service should be recommended?", "prompt": {"question": "<p>A company has a queue-triggered processing workload where jobs run for up to 45 minutes each, use custom Linux container images with specific library dependencies, and occur sporadically (sometimes zero jobs for hours). The architect must minimize cost during idle periods while supporting long-running executions. Which compute service should be recommended?</p>", "answers": ["<p>Azure Container Apps with KEDA-based scaling rules tied to the queue</p>", "<p>Azure Functions on the Premium plan</p>", "<p>Azure Batch</p>", "<p>Azure Kubernetes Service with cluster autoscaler enabled</p>"], "feedbacks": ["<p>Azure Container Apps supports custom container images, uses KEDA to scale on external event sources like queue length, can scale to zero replicas when idle (eliminating cost), and does not impose the Functions execution time ceiling — it comfortably supports 45-minute job runs.</p>", "<p>Functions Premium plan keeps at least one 'always ready' instance running to avoid cold starts, so it does not scale to zero and incurs baseline cost even when idle; Consumption plan would scale to zero but caps execution at 10 minutes, which is too short for a 45-minute job.</p>", "<p>Azure Batch is designed for large-scale parallel/HPC compute jobs with job scheduling overhead; it is not optimized for lightweight sporadic queue-triggered single-job workloads and has slower pool scale-down behavior.</p>", "<p>AKS with cluster autoscaler can scale nodes down but rarely to true zero cost (system node pool must stay running), and it introduces significantly more management overhead than Container Apps for this simple event-driven pattern.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A hub-and-spoke network has a private endpoint for an Azure SQL Database deployed in the hub VNet. The Azure Private DNS zone privatelink.database.windows.net is linked only to the hub VNet. Spoke VNets are peered to the hub. Applications in the spoke VNets resolve the SQL Database FQDN to its public IP address instead of the private endpoint's private IP. What should the architect do to fix this?", "prompt": {"question": "<p>A hub-and-spoke network has a private endpoint for an Azure SQL Database deployed in the hub VNet. The Azure Private DNS zone privatelink.database.windows.net is linked only to the hub VNet. Spoke VNets are peered to the hub. Applications in the spoke VNets resolve the SQL Database FQDN to its public IP address instead of the private endpoint's private IP. What should the architect do to fix this?</p>", "answers": ["<p>Enable a service endpoint for Microsoft.Sql on the spoke subnets</p>", "<p>Manually create a public DNS A record for the private endpoint IP in each spoke's DNS server</p>", "<p>Enable 'Use remote gateways' on each spoke VNet peering connection</p>", "<p>Link the privatelink.database.windows.net private DNS zone to each spoke VNet as well</p>"], "feedbacks": ["<p>Service endpoints extend a VNet's identity to a service over the Microsoft backbone but are unrelated to Private Link/private endpoint DNS resolution — they solve a different problem and won't fix name resolution here.</p>", "<p>Manually maintaining static DNS records per spoke is not scalable, breaks if the private endpoint IP ever changes, and is not the Microsoft-recommended pattern for centralized private DNS.</p>", "<p>'Use remote gateways' relates to allowing a spoke to use a hub's VPN/ExpressRoute gateway for transit connectivity — it has no effect on private DNS zone resolution.</p>", "<p>VNet peering does not propagate Private DNS zone virtual network links. Each VNet that needs to resolve the private endpoint's FQDN to its private IP must either have the zone linked directly, or use a custom DNS server/forwarder pointed at a resolver in the hub that has the zone linked. Simply linking the zone to the spokes resolves the issue.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An IoT solution ingests over 5 million telemetry events per minute from industrial sensors. Consumers must process events in the order they were sent per device, and the solution must support replaying events from any point within the last 7 days for reprocessing after a bug fix. Which service should the architect select?", "prompt": {"question": "<p>An IoT solution ingests over 5 million telemetry events per minute from industrial sensors. Consumers must process events in the order they were sent per device, and the solution must support replaying events from any point within the last 7 days for reprocessing after a bug fix. Which service should the architect select?</p>", "answers": ["<p>Azure Service Bus topics with sessions enabled</p>", "<p>Azure Event Grid with a custom topic</p>", "<p>Azure Event Hubs, using partition keys per device and enabling Capture with a 7-day retention period</p>", "<p>Azure Storage Queues with multiple queue instances</p>"], "feedbacks": ["<p>Service Bus is designed for enterprise messaging with guaranteed delivery and transactions at much lower throughput (thousands, not millions, of messages/sec); sessions provide ordering but the service isn't built for this ingestion scale.</p>", "<p>Event Grid is a push-based, low-latency eventing service for reactive event notifications, not for high-throughput telemetry streaming; it does not offer 7-day replay of an event stream.</p>", "<p>Event Hubs is purpose-built for massive-throughput event streaming (millions of events/sec), preserves order within a partition (using device ID as the partition key), and supports configurable retention up to 7 days (90 days on Premium/Dedicated), allowing consumers to replay from any offset — exactly matching the requirements.</p>", "<p>Storage Queues offer no strict ordering guarantee across consumers at scale and have a 7-day maximum message TTL for individual messages, not a replay/offset model — it cannot support historical replay processing.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company must migrate an on-premises SQL Server database that processes continuous transactions 24/7 to Azure SQL Managed Instance. The business requires the final cutover downtime to be no more than a few minutes. Which migration approach should the architect use?", "prompt": {"question": "<p>A company must migrate an on-premises SQL Server database that processes continuous transactions 24/7 to Azure SQL Managed Instance. The business requires the final cutover downtime to be no more than a few minutes. Which migration approach should the architect use?</p>", "answers": ["<p>Azure Database Migration Service in offline (one-time) migration mode</p>", "<p>Manual native backup and restore of the database to Azure SQL Managed Instance</p>", "<p>Azure Migrate: Server Migration to lift-and-shift the database server as a VM</p>", "<p>Azure Database Migration Service in online (continuous data sync) migration mode</p>"], "feedbacks": ["<p>DMS offline mode takes a point-in-time copy and requires the source to be taken offline (or frozen) for the full duration of the data transfer, which for a continuously transacting database could mean hours of downtime — unacceptable here.</p>", "<p>Manual backup/restore requires stopping writes during backup, transfer, and restore of potentially large databases, causing extended downtime far beyond a few minutes.</p>", "<p>Azure Migrate: Server Migration migrates entire VMs (OS, disks) for infrastructure lift-and-shift; it does not perform database-level continuous replication and is the wrong tool for a database-to-Managed-Instance migration.</p>", "<p>DMS online migration mode continuously replicates transactions from the source SQL Server to the target Managed Instance while the source stays online and operational. Cutover only requires a brief pause to let the final transactions sync and then redirect connections — typically a few minutes of downtime, meeting the requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has an ExpressRoute circuit with private peering connecting its on-premises datacenter to a hub VNet. On-premises application servers must query an Azure SQL Database and read blobs from a Storage account using private IP addresses only, with zero traffic traversing the public internet, and no public endpoint may remain enabled on either service. What should you configure?", "prompt": {"question": "<p>A company has an ExpressRoute circuit with private peering connecting its on-premises datacenter to a hub VNet. On-premises application servers must query an Azure SQL Database and read blobs from a Storage account using private IP addresses only, with zero traffic traversing the public internet, and no public endpoint may remain enabled on either service. What should you configure?</p>", "answers": ["<p>Enable Service Endpoints for Microsoft.Sql and Microsoft.Storage on the subnet connected via ExpressRoute</p>", "<p>Configure ExpressRoute Microsoft peering and keep public endpoint access enabled with IP firewall rules restricting to the on-premises range</p>", "<p>Deploy Private Endpoints for the SQL Database and Storage account in the hub VNet and configure DNS to resolve to their private IP addresses</p>", "<p>Add a Point-to-Site VPN connection alongside the existing ExpressRoute circuit to reach the services</p>"], "feedbacks": ["<p>Service Endpoints only extend a subnet's identity to a PaaS service for traffic originating inside that VNet — they do not provide a routable private IP and are not reachable from on-premises over ExpressRoute private peering, so on-prem servers cannot use this path.</p>", "<p>Microsoft peering plus a public endpoint means traffic still uses public IP addressing and the resource remains internet-exposed (even if firewall-restricted), which violates the 'no public endpoint' requirement.</p>", "<p>Private Endpoints give the SQL Database and Storage account private IP addresses inside the VNet. Traffic from on-premises over the ExpressRoute private peering path is routed to those private IPs, and both services' public endpoints can then be disabled entirely, satisfying the internet-avoidance and no-public-endpoint requirements.</p>", "<p>A Point-to-Site VPN is a client-to-VNet remote access solution and does nothing to provide private connectivity to PaaS resource endpoints; it also duplicates connectivity that ExpressRoute already provides.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A logistics company ingests roughly 2 million telemetry events per second from vehicle sensors. The solution must support replaying the raw event stream for up to 7 days, feed Azure Stream Analytics in near real time, and automatically archive every raw event to Azure Data Lake Storage Gen2 without writing custom archival code. Which service should be used for ingestion?", "prompt": {"question": "<p>A logistics company ingests roughly 2 million telemetry events per second from vehicle sensors. The solution must support replaying the raw event stream for up to 7 days, feed Azure Stream Analytics in near real time, and automatically archive every raw event to Azure Data Lake Storage Gen2 without writing custom archival code. Which service should be used for ingestion?</p>", "answers": ["<p>Azure Service Bus Topics with sessions enabled</p>", "<p>Azure Storage Queues with a peek-lock consumption pattern</p>", "<p>Azure Event Grid with a custom topic and a Data Lake event subscriber</p>", "<p>Azure Event Hubs with Capture enabled</p>"], "feedbacks": ["<p>Service Bus is designed for enterprise messaging with ordering, transactions, and sessions at far lower throughput; it cannot sustain millions of events per second and has no built-in stream replay or Capture-style archival.</p>", "<p>Storage Queues are simple, low-throughput queues with a 7-day max TTL but no replay semantics, no native Stream Analytics ingestion pattern, and no automatic archival capability.</p>", "<p>Event Grid is a discrete, reactive event notification service (push-based, at-least-once delivery of small event payloads) — it is not designed for high-throughput telemetry streaming or long-term replay and has no Capture equivalent.</p>", "<p>Event Hubs is built for massive-scale event streaming (millions of events/sec), supports configurable retention for replay (up to 7 days on Standard/Dedicated tiers), integrates natively with Stream Analytics, and its Capture feature automatically writes raw events to Data Lake Storage or Blob Storage with zero custom code.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team is building a microservices application that uses Dapr for service invocation and pub/sub. The design requires scaling individual services to zero when idle, scaling out automatically based on Azure Service Bus queue length using KEDA, and the team explicitly wants to avoid managing Kubernetes control planes, node pools, or cluster upgrades. Which compute service best fits these requirements?", "prompt": {"question": "<p>A team is building a microservices application that uses Dapr for service invocation and pub/sub. The design requires scaling individual services to zero when idle, scaling out automatically based on Azure Service Bus queue length using KEDA, and the team explicitly wants to avoid managing Kubernetes control planes, node pools, or cluster upgrades. Which compute service best fits these requirements?</p>", "answers": ["<p>Azure Container Apps</p>", "<p>Azure Kubernetes Service with the KEDA add-on and Dapr extension enabled</p>", "<p>Azure App Service Premium v3 plan with autoscale rules</p>", "<p>Azure Batch with an autoscaling pool</p>"], "feedbacks": ["<p>Azure Container Apps is a fully managed, serverless container platform with built-in Dapr integration and native KEDA-based event-driven autoscaling, including scale-to-zero, while completely abstracting away cluster nodes, control plane management, and upgrades.</p>", "<p>AKS can technically run Dapr and KEDA via add-ons and achieves the same scaling behavior, but it still requires the team to manage node pools, cluster upgrades, and (unless using the automatic SKU) the control plane — directly violating the stated requirement to avoid that overhead.</p>", "<p>App Service Premium v3 autoscale is based on CPU/memory/HTTP metrics, not Service Bus queue length via KEDA, and it has no native Dapr sidecar integration.</p>", "<p>Azure Batch is designed for large-scale parallel and HPC batch workloads dispatched to compute pools, not for long-running microservices communicating via Dapr.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}], "expected": 45}, {"name": "Terraform Associate Practice Test 1", "cid": 7301147, "duration": 60, "pass_percent": 70, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A company's operations team manually configures each new server through ad-hoc SSH sessions. Over time, servers that were supposed to be identical have started behaving differently, and nobody can explain why. Which IaC advantage BEST addresses this problem?", "prompt": {"question": "<p>A company's operations team manually configures each new server through ad-hoc SSH sessions. Over time, servers that were supposed to be identical have started behaving differently, and nobody can explain why. Which IaC advantage BEST addresses this problem?</p>", "answers": ["<p>Cost optimization through pay-as-you-go billing</p>", "<p>Declarative, version-controlled configuration that eliminates configuration drift</p>", "<p>Real-time monitoring and alerting for infrastructure health</p>", "<p>Automatic scaling based on traffic patterns</p>"], "feedbacks": ["<p>Cost optimization is unrelated to the described drift problem and isn't the core IaC concept being tested here.</p>", "<p>IaC written declaratively and stored in version control ensures every environment is provisioned from the same source of truth, eliminating the drift caused by manual, undocumented changes.</p>", "<p>Monitoring/alerting is an operational concern that detects problems but doesn't prevent drift the way IaC's repeatable provisioning does.</p>", "<p>Autoscaling is a compute-management feature, not an IaC concept related to consistency or drift.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to provision resources across AWS, Azure, and an on-premises VMware cluster using a single configuration language and workflow. Which Terraform capability makes this possible?", "prompt": {"question": "<p>A company needs to provision resources across AWS, Azure, and an on-premises VMware cluster using a single configuration language and workflow. Which Terraform capability makes this possible?</p>", "answers": ["<p>Terraform's built-in cloud-specific SDKs bundled directly into Terraform Core for AWS and Azure only</p>", "<p>Terraform's provider plugin architecture, which lets one core engine manage resources across multiple platforms</p>", "<p>Terraform Cloud's mandatory SaaS billing model</p>", "<p>Terraform's requirement that configuration be rewritten in each vendor's native templating language</p>"], "feedbacks": ["<p>Terraform Core doesn't bundle vendor SDKs directly; providers are pluggable and not restricted to AWS/Azure.</p>", "<p>Terraform Core is provider-agnostic; provider plugins translate a single HCL workflow (init/plan/apply) into calls against each platform's API, enabling true multi-cloud and hybrid-cloud management.</p>", "<p>The billing model of Terraform Cloud has nothing to do with multi-cloud provisioning capability.</p>", "<p>This is the opposite of how Terraform works — HCL abstraction specifically avoids needing separate native templating languages per vendor.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team is choosing between manually documenting server setup steps in a wiki versus defining infrastructure as code artifacts stored in a Git repository. Which advantage does the team gain by choosing the code-based approach?", "prompt": {"question": "<p>A platform team is choosing between manually documenting server setup steps in a wiki versus defining infrastructure as code artifacts stored in a Git repository. Which advantage does the team gain by choosing the code-based approach?</p>", "answers": ["<p>Guaranteed zero-downtime deployments for every change</p>", "<p>Repeatable, auditable infrastructure changes through version control history</p>", "<p>Elimination of the need for any testing before deployment</p>", "<p>Automatic conversion of legacy infrastructure to cloud-native services</p>"], "feedbacks": ["<p>IaC does not guarantee zero downtime; that depends on deployment strategy, not the fact that config is code.</p>", "<p>Storing infrastructure definitions as code in Git provides commit history, peer review, and rollback capability — giving repeatable and auditable changes, a core IaC benefit over wiki-based documentation.</p>", "<p>IaC does not eliminate testing — plan review and validation are still recommended practices.</p>", "<p>IaC has no mechanism to automatically migrate or convert legacy infrastructure to cloud-native services.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement BEST describes a core problem that infrastructure as code is designed to solve?", "prompt": {"question": "<p>Which statement BEST describes a core problem that infrastructure as code is designed to solve?</p>", "answers": ["<p>The lack of consistent, repeatable processes when infrastructure is provisioned and modified manually</p>", "<p>The need to rewrite application code for each new cloud provider</p>", "<p>The requirement for infrastructure teams to use only open-source software</p>", "<p>The inability of virtual machines to run containerized workloads</p>"], "feedbacks": ["<p>IaC's foundational purpose is to replace manual, ad-hoc, inconsistent infrastructure provisioning with declarative, version-controlled, repeatable processes.</p>", "<p>IaC concerns infrastructure provisioning workflows, not application code portability across cloud providers.</p>", "<p>There is no such requirement; IaC tools can be open-source or commercial, and this isn't a problem IaC solves.</p>", "<p>This describes a container/virtualization concern unrelated to the core purpose of infrastructure as code.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team currently uses shell scripts to imperatively call cloud provider APIs to create VMs, networks, and load balancers, one command at a time. They want to move to a tool that describes the desired end state of infrastructure, automatically determines the order of operations, and shows a preview of changes before anything is applied. Which approach BEST meets these requirements?", "prompt": {"question": "<p>A platform team currently uses shell scripts to imperatively call cloud provider APIs to create VMs, networks, and load balancers, one command at a time. They want to move to a tool that describes the desired end state of infrastructure, automatically determines the order of operations, and shows a preview of changes before anything is applied. Which approach BEST meets these requirements?</p>", "answers": ["<p>Continue using shell scripts but add version control</p>", "<p>Use Ansible playbooks with imperative tasks executed in sequence</p>", "<p>Use a bash-based CI/CD pipeline calling cloud CLI commands in parallel</p>", "<p>Adopt Terraform's declarative configuration and run `terraform plan` before every apply</p>"], "feedbacks": ["<p>Version-controlling shell scripts does not change their imperative nature — the scripts still hard-code the order of API calls and provide no dependency graph or change preview.</p>", "<p>Ansible playbooks are primarily imperative, task-by-task instructions; while Ansible can provision infrastructure, it is not designed around a persistent desired-state model with a built-in plan/preview step like Terraform.</p>", "<p>Parallel CLI calls in a pipeline still require the engineer to manually determine and encode dependency order, and there is no automatic diff/preview of pending changes.</p>", "<p>Terraform's HCL is declarative — you describe the desired end state, and Terraform's engine builds a resource graph to determine dependency order automatically. `terraform plan` generates an execution plan showing exactly what will be created, changed, or destroyed before any action is taken.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization is deciding how to divide responsibilities between Terraform and Ansible when managing both the provisioning of new AWS EC2 instances and the ongoing installation of packages on those instances. Which statement BEST describes how the two tools typically complement each other in this scenario?", "prompt": {"question": "<p>An organization is deciding how to divide responsibilities between Terraform and Ansible when managing both the provisioning of new AWS EC2 instances and the ongoing installation of packages on those instances. Which statement BEST describes how the two tools typically complement each other in this scenario?</p>", "answers": ["<p>Terraform should handle package installation while Ansible provisions the underlying infrastructure</p>", "<p>Terraform is best suited for provisioning and managing infrastructure resources via state, while Ansible is best suited for configuration management tasks on top of that infrastructure</p>", "<p>Terraform and Ansible are interchangeable and either can fully replace the other for both tasks</p>", "<p>Ansible should be used exclusively because it does not require maintaining a state file</p>"], "feedbacks": ["<p>This reverses the tools' core strengths — Terraform is not designed as a general configuration-management/package-installation tool, and Ansible is not built around a persistent infrastructure state file the way Terraform is.</p>", "<p>Terraform excels at provisioning cloud infrastructure resources and tracking their real-world state in a state file, enabling create/update/destroy planning. Ansible excels at configuration management — installing packages, managing files, and configuring software on already-provisioned hosts. Using each tool for its strength is the standard complementary pattern.</p>", "<p>The tools solve different problems (declarative infrastructure provisioning vs. procedural configuration management) and are commonly used together rather than as substitutes for one another.</p>", "<p>Ansible's agentless, stateless design is a real architectural difference, but that alone is not a reason to use it exclusively — it does not track infrastructure state or compute a dependency-based execution plan the way Terraform does, which is needed for reliable provisioning.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "What is the primary purpose of Terraform's resource dependency graph?", "prompt": {"question": "<p>What is the primary purpose of Terraform's resource dependency graph?</p>", "answers": ["<p>To provide a graphical dashboard for monitoring live infrastructure metrics</p>", "<p>To determine the correct order to create, update, or destroy resources based on their dependencies</p>", "<p>To store the state of all deployed resources in a single file</p>", "<p>To enforce role-based access control policies on HCP Terraform workspaces</p>"], "feedbacks": ["<p>Terraform does not provide a metrics-monitoring dashboard; that is outside its scope as a provisioning tool.</p>", "<p>Terraform builds a directed acyclic graph (DAG) from resource and data source dependencies in the configuration. This graph lets Terraform determine which resources are independent (and can be processed in parallel) and which must wait on others, ensuring operations happen in a safe, correct order.</p>", "<p>The resource graph is separate from the state file — the state file records the mapped real-world attributes of resources, while the graph models dependency relationships for execution ordering.</p>", "<p>RBAC policy enforcement in HCP Terraform is handled through workspace/organization permissions and Sentinel/OPA policies, not the internal dependency graph used during plan/apply.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Which Terraform command allows engineers to preview the exact changes that will be made to infrastructure before those changes are actually applied?", "prompt": {"question": "<p>Which Terraform command allows engineers to preview the exact changes that will be made to infrastructure before those changes are actually applied?</p>", "answers": ["<p>terraform validate</p>", "<p>terraform graph</p>", "<p>terraform state list</p>", "<p>terraform plan</p>"], "feedbacks": ["<p>`terraform validate` only checks that the configuration syntax and internal consistency are correct; it does not compare against real infrastructure or produce a change preview.</p>", "<p>`terraform graph` outputs a visual representation of the dependency graph in DOT format; it does not show pending resource changes.</p>", "<p>`terraform state list` simply lists the resources currently tracked in the state file — it shows what already exists, not what will change on the next apply.</p>", "<p>`terraform plan` compares the current state against the configuration and desired state, then outputs a detailed execution plan showing which resources will be added, changed, or destroyed — without making any actual changes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Your team wants the AWS provider to automatically pick up patch-level bug fixes (e.g., 5.10.1, 5.10.2) but never accept a minor or major version bump like 5.11.0 or 6.0.0. Which version constraint should you use in the required_providers block?", "prompt": {"question": "<p>Your team wants the AWS provider to automatically pick up patch-level bug fixes (e.g., 5.10.1, 5.10.2) but never accept a minor or major version bump like 5.11.0 or 6.0.0. Which version constraint should you use in the required_providers block?</p>", "answers": ["<p>version = \"&gt;= 5.10.0\"</p>", "<p>version = \"~&gt; 5.10.0\"</p>", "<p>version = \"= 5.10.0\"</p>", "<p>version = \"~&gt; 5.10\"</p>"], "feedbacks": ["<p>&gt;= 5.10.0 places no upper bound at all, allowing minor and major upgrades including 6.0.0.</p>", "<p>The pessimistic constraint operator ~&gt; 5.10.0 (three-part version) locks the rightmost segment, allowing only patch releases within 5.10.x (5.10.1, 5.10.2, etc.) while blocking 5.11.0 or higher.</p>", "<p>= 5.10.0 pins to the exact version with zero flexibility, so patch releases would never be picked up automatically.</p>", "<p>~&gt; 5.10 (two-part version) locks only the major version, so 5.11.0 and 5.99.0 would still be allowed — this is a common mix-up with the three-part form.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "What is the primary purpose of the .terraform.lock.hcl file?", "prompt": {"question": "<p>What is the primary purpose of the .terraform.lock.hcl file?</p>", "answers": ["<p>It stores the current state of managed infrastructure resources so Terraform can detect drift.</p>", "<p>It records the exact provider versions and package checksums selected during init, ensuring consistent provider installs across team members and CI runs.</p>", "<p>It defines the minimum required Terraform CLI version for the configuration.</p>", "<p>It stores sensitive variable values so they are not exposed in plan output.</p>"], "feedbacks": ["<p>Tracking real-world resource state and drift is the job of the Terraform state file (terraform.tfstate), not the lock file.</p>", "<p>The dependency lock file is generated by terraform init and records the specific provider versions and cryptographic checksums that satisfy the required_providers constraints, guaranteeing everyone on the team gets the same provider builds.</p>", "<p>The minimum required CLI version is declared with required_version inside the terraform block, which is unrelated to the lock file's content.</p>", "<p>Sensitive values are handled through variables, tfvars, and state encryption/backends — the lock file only concerns provider versions and hashes, never variable values.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A configuration must create EC2 instances in both us-east-1 and eu-west-1 using the same AWS provider plugin. What is the correct way to configure this in Terraform?", "prompt": {"question": "<p>A configuration must create EC2 instances in both us-east-1 and eu-west-1 using the same AWS provider plugin. What is the correct way to configure this in Terraform?</p>", "answers": ["<p>Declare two separate provider \"aws\" blocks that both use the same alias attribute.</p>", "<p>Declare a single provider \"aws\" block and pass the region as a per-resource variable inside each resource block.</p>", "<p>Declare a second provider \"aws\" block with an alias attribute set to a unique name, then reference it on specific resources using provider = aws.alias_name.</p>", "<p>List both regions under the required_providers block's version constraint for the aws provider.</p>"], "feedbacks": ["<p>Two provider blocks cannot share the same alias — each alias must be unique or Terraform will error on duplicate configuration.</p>", "<p>Region is a provider-level connection setting, not a resource attribute; you cannot override it per-resource without configuring a second aliased provider.</p>", "<p>Provider aliases let you define multiple configurations of the same provider (e.g., different regions) in one configuration; resources opt into the non-default configuration with the provider meta-argument, such as provider = aws.eu_west.</p>", "<p>required_providers only pins the provider source and version constraints — it has no concept of regions or provider configuration values.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement best describes the primary purpose of Terraform state?", "prompt": {"question": "<p>Which statement best describes the primary purpose of Terraform state?</p>", "answers": ["<p>It maps real-world resources to your configuration, records resource metadata, and improves performance when managing large amounts of infrastructure.</p>", "<p>It stores the HCL source code so configurations can be reused across unrelated projects.</p>", "<p>It locks provider plugin versions and checksums during terraform init.</p>", "<p>It generates a human-readable audit log of every API call Terraform makes to the provider.</p>"], "feedbacks": ["<p>Terraform state is the source of truth that maps configuration blocks to actual infrastructure objects, tracks metadata and dependencies, and lets Terraform avoid querying every resource's full attributes on every run — critical for performance at scale.</p>", "<p>State files never contain HCL source — they contain a JSON-serialized snapshot of resource attributes and metadata.</p>", "<p>Locking provider versions and checksums is the responsibility of the .terraform.lock.hcl file, not the state file.</p>", "<p>Terraform state is not an audit log of API calls; that kind of logging is handled separately (e.g., TF_LOG or provider-side cloud audit trails).</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "Which block correctly declares a required provider named aws with a specific source and version constraint?", "prompt": {"question": "<p>Which block correctly declares a required provider named aws with a specific source and version constraint?</p>", "answers": ["<p>terraform {\n  required_providers {\n    aws = \"hashicorp/aws\"\n    version = \"~&gt; 5.0\"\n  }\n}</p>", "<p>provider \"aws\" {\n  required_providers {\n    source = \"hashicorp/aws\"\n    version = \"~&gt; 5.0\"\n  }\n}</p>", "<p>terraform {\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~&gt; 5.0\"\n    }\n  }\n}</p>", "<p>required_providers {\n  aws = {\n    source  = \"hashicorp/aws\"\n    version = \"~&gt; 5.0\"\n  }\n}</p>"], "feedbacks": ["<p>Assigning aws directly to a string and putting version as a sibling key is invalid syntax — source and version must be nested together as an object under the provider name.</p>", "<p>required_providers is not valid inside a provider block; it only belongs inside the top-level terraform block.</p>", "<p>required_providers must live inside the terraform block, and each provider entry is an object with source and version keys, exactly as shown in option C — this is the syntax Terraform expects to resolve and lock the provider.</p>", "<p>required_providers cannot exist as a bare top-level block — it must be nested inside the terraform configuration block or Terraform will fail to parse it.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A repository has a committed .terraform.lock.hcl that locks the aws provider to version 5.14.0. A teammate changes required_providers to version = \">= 5.20\" and pushes the change, but does not update the lock file. What happens when another engineer runs terraform init on a clean checkout?", "prompt": {"question": "<p>A repository has a committed .terraform.lock.hcl that locks the aws provider to version 5.14.0. A teammate changes required_providers to version = \"&gt;= 5.20\" and pushes the change, but does not update the lock file. What happens when another engineer runs terraform init on a clean checkout?</p>", "answers": ["<p>Terraform automatically rewrites the lock file to the newest matching version without any warning or extra flags.</p>", "<p>Terraform ignores the lock file entirely and always installs the newest available provider release from the registry.</p>", "<p>Terraform pauses and interactively prompts the user to approve installing a newer provider version.</p>", "<p>terraform init fails with an error because the locked version 5.14.0 no longer satisfies the constraint, requiring terraform init -upgrade to resolve it.</p>"], "feedbacks": ["<p>Terraform never silently rewrites the lock file on a plain init — that behavior only occurs with the explicit -upgrade flag.</p>", "<p>The lock file is honored by default precisely to prevent uncontrolled provider drift; it is not ignored during normal init runs.</p>", "<p>Terraform init is non-interactive by design in this scenario — it fails with a clear error message rather than prompting for confirmation.</p>", "<p>By default terraform init respects the existing lock file. If the locked version no longer satisfies an updated version constraint, init errors out and instructs the user to run terraform init -upgrade to select and record a new compatible version.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A DevOps engineer runs `terraform plan` and sees a resource listed as: `-/+ resource \"aws_instance\" \"web\" will be replaced, as requested`. What does the `-/+` symbol combination indicate?", "prompt": {"question": "<p>A DevOps engineer runs `terraform plan` and sees a resource listed as: `-/+ resource \"aws_instance\" \"web\" will be replaced, as requested`. What does the `-/+` symbol combination indicate?</p>", "answers": ["<p>The resource will be updated in place with zero downtime</p>", "<p>Terraform detected drift and will only refresh the state file</p>", "<p>The plan failed and no changes will be applied</p>", "<p>The resource will be destroyed and then a new resource will be created to replace it</p>"], "feedbacks": ["<p>In-place updates are shown with a `~` symbol, not `-/+`</p>", "<p>Drift refresh alone doesn't produce a `-/+` action; that would show as `~` or no change after refresh</p>", "<p>A `-/+` line means Terraform successfully generated a plan showing a replacement, not a failure</p>", "<p>The `-/+` prefix in plan output means destroy-then-create replacement — the resource cannot be updated in place because a changed attribute forces recreation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which command checks that a Terraform configuration is syntactically valid and internally consistent, without contacting any remote APIs or backends?", "prompt": {"question": "<p>Which command checks that a Terraform configuration is syntactically valid and internally consistent, without contacting any remote APIs or backends?</p>", "answers": ["<p>terraform validate</p>", "<p>terraform init</p>", "<p>terraform apply -auto-approve</p>", "<p>terraform plan</p>"], "feedbacks": ["<p>terraform validate checks syntax and internal consistency (e.g., argument types, references) using only the local configuration and cached provider schema; it does not need network or backend access.</p>", "<p>terraform init downloads providers/modules and configures the backend, which requires network access</p>", "<p>terraform apply -auto-approve provisions real infrastructure and requires provider API calls</p>", "<p>terraform plan contacts providers to refresh state and compare against real infrastructure</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A team's configuration specifies a provider version constraint of `~> 5.0`, and a newer 5.x version has been released. Which command should they run to update the installed provider plugin to the latest version allowed by the constraint?", "prompt": {"question": "<p>A team's configuration specifies a provider version constraint of `~&gt; 5.0`, and a newer 5.x version has been released. Which command should they run to update the installed provider plugin to the latest version allowed by the constraint?</p>", "answers": ["<p>terraform apply -refresh-only</p>", "<p>terraform init -upgrade</p>", "<p>terraform providers schema</p>", "<p>terraform plan -refresh-only</p>"], "feedbacks": ["<p>-refresh-only on apply only reconciles state with real infrastructure attributes; it does not install providers</p>", "<p>terraform init -upgrade re-evaluates version constraints and installs the latest provider and module versions permitted by the configuration, updating the lock file accordingly.</p>", "<p>terraform providers schema just outputs provider schema information for debugging, it doesn't upgrade anything</p>", "<p>-refresh-only on plan previews state drift reconciliation, not provider installation</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An engineer changes the `availability_zone` argument on an existing `aws_instance` resource already tracked in state. Running `terraform plan` shows the instance will be destroyed and recreated instead of updated. What is the most likely explanation?", "prompt": {"question": "<p>An engineer changes the `availability_zone` argument on an existing `aws_instance` resource already tracked in state. Running `terraform plan` shows the instance will be destroyed and recreated instead of updated. What is the most likely explanation?</p>", "answers": ["<p>The state file has become corrupted and must be manually repaired</p>", "<p>Terraform always destroys and recreates any resource that has any argument changed</p>", "<p>The AWS provider version installed is incompatible with the configuration</p>", "<p>availability_zone is a ForceNew attribute for this resource type, so the provider requires replacement to apply the change</p>"], "feedbacks": ["<p>Nothing in the scenario suggests state corruption; a `-/+` plan is expected, normal behavior</p>", "<p>Many attributes support in-place updates (shown with `~`); replacement only happens for attributes marked ForceNew in the provider schema</p>", "<p>A provider/config version mismatch would typically produce an error, not a clean replacement plan</p>", "<p>Some attributes are defined by the provider schema as requiring resource replacement (ForceNew) because the underlying cloud API doesn't support updating that attribute in place — availability_zone on an EC2 instance is a classic example.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "What is the primary purpose of the resource dependency graph that Terraform builds internally during plan and apply?", "prompt": {"question": "<p>What is the primary purpose of the resource dependency graph that Terraform builds internally during plan and apply?</p>", "answers": ["<p>To encrypt sensitive values before writing them to the state file</p>", "<p>To determine the correct order of create, update, and destroy operations and enable safe parallel execution</p>", "<p>To automatically generate module documentation from resource definitions</p>", "<p>To validate that HCL syntax follows canonical formatting conventions</p>"], "feedbacks": ["<p>State encryption is a backend/storage concern, unrelated to the dependency graph</p>", "<p>Terraform constructs a dependency graph from resource references and explicit depends_on relationships, then walks the graph to determine which operations can run in parallel and which must be sequenced.</p>", "<p>Terraform has no built-in documentation generator tied to the dependency graph (terraform-docs is a separate third-party tool)</p>", "<p>Formatting validation is handled by terraform fmt/validate, not the dependency graph</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A developer wants to destroy only a single misbehaving resource, `aws_instance.web`, so it will be recreated fresh on the next apply, without touching any other resource in the configuration. Which command should they run?", "prompt": {"question": "<p>A developer wants to destroy only a single misbehaving resource, `aws_instance.web`, so it will be recreated fresh on the next apply, without touching any other resource in the configuration. Which command should they run?</p>", "answers": ["<p>terraform taint aws_instance.web</p>", "<p>terraform state rm aws_instance.web</p>", "<p>terraform plan -destroy</p>", "<p>terraform destroy -target=aws_instance.web</p>"], "feedbacks": ["<p>terraform taint marks a resource for replacement on the next apply but does not destroy it immediately by itself</p>", "<p>terraform state rm only removes the resource from Terraform's state file — the real infrastructure object is not destroyed and becomes unmanaged</p>", "<p>terraform plan -destroy only previews what a full destroy would do; it does not actually destroy anything and isn't scoped to a single resource by default</p>", "<p>terraform destroy -target=&lt;address&gt; actually destroys the specified resource in real infrastructure while leaving all other resources untouched, allowing it to be recreated on the next apply.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A developer runs `terraform plan` and sees the following in the output:\n\n  # aws_instance.web must be replaced\n-/+ resource \"aws_instance\" \"web\" {\n      ~ availability_zone = \"us-east-1a\" -> (known after apply)\n      ~ id                 = \"i-0123456789\" -> (known after apply)\n      ~ subnet_id          = \"subnet-abc123\" -> \"subnet-def456\" # forces replacement\n    }\n\nWhat is the BEST explanation for why Terraform is proposing to destroy and recreate this resource instead of updating it in place?", "prompt": {"question": "<p>A developer runs `terraform plan` and sees the following in the output:\n\n  # aws_instance.web must be replaced\n-/+ resource \"aws_instance\" \"web\" {\n      ~ availability_zone = \"us-east-1a\" -&gt; (known after apply)\n      ~ id                 = \"i-0123456789\" -&gt; (known after apply)\n      ~ subnet_id          = \"subnet-abc123\" -&gt; \"subnet-def456\" # forces replacement\n    }\n\nWhat is the BEST explanation for why Terraform is proposing to destroy and recreate this resource instead of updating it in place?</p>", "answers": ["<p>Terraform always destroys and recreates aws_instance resources when any attribute in the configuration changes</p>", "<p>The state file is corrupted and Terraform cannot reconcile the drift, so it defaults to recreating the resource</p>", "<p>The subnet_id argument is defined in the provider schema as ForceNew, meaning it cannot be updated on an existing instance and requires replacement</p>", "<p>The developer forgot to run terraform validate before terraform plan, causing Terraform to treat the change as invalid</p>"], "feedbacks": ["<p>Not all attribute changes force replacement — many attributes (like tags) can be updated in place with a '~' symbol alone and no replacement; the behavior depends on the specific attribute's schema definition, not a blanket rule for the resource type.</p>", "<p>State corruption would typically surface as drift detection errors or an inability to refresh state, not a clean '-/+' replacement plan with a specific attribute called out as the cause via 'forces replacement'.</p>", "<p>Terraform provider schemas mark certain attributes as requiring replacement (commonly labeled ForceNew internally, shown as '# forces replacement' in plan output). subnet_id for aws_instance is one such attribute — AWS does not support changing the subnet of a running EC2 instance, so the only way to apply the change is to destroy the existing instance and create a new one in the target subnet. The plan output explicitly annotates this with the 'forces replacement' comment next to the changed line.</p>", "<p>terraform validate only checks configuration syntax and internal consistency (e.g., correct argument names/types); it does not detect or relate to provider-level replacement requirements, and skipping it does not cause plan to fabricate a replacement action.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A Terraform configuration includes this variable block:\n\nvariable \"instance_count\" {\n  type = number\n}\n\nThe team wants to enforce that instance_count is always greater than 0, and display a custom error message if it is not, without using a separate provider or external tool. Which block should be added inside the variable block to satisfy this requirement?", "prompt": {"question": "<p>A Terraform configuration includes this variable block:\n\nvariable \"instance_count\" {\n  type = number\n}\n\nThe team wants to enforce that instance_count is always greater than 0, and display a custom error message if it is not, without using a separate provider or external tool. Which block should be added inside the variable block to satisfy this requirement?</p>", "answers": ["<p>A validation block containing condition = var.instance_count &gt; 0 and error_message = \"Instance count must be greater than 0.\"</p>", "<p>A lifecycle block containing precondition = var.instance_count &gt; 0</p>", "<p>A check block containing assert = var.instance_count &gt; 0</p>", "<p>A validation block containing condition = var.instance_count &gt; 0 and message = \"Instance count must be greater than 0.\"</p>"], "feedbacks": ["<p>Input variable custom validation requires a validation block nested inside the variable block, and that block must contain exactly two arguments: condition (a boolean expression) and error_message (the string shown when condition is false).</p>", "<p>lifecycle with precondition is used inside resource/data/output blocks (via a lifecycle block) to validate assumptions about resources, not inside variable blocks for input validation.</p>", "<p>check blocks are a top-level construct (Terraform 1.5+) used for post-apply assertions about infrastructure state, not for validating input variables.</p>", "<p>The argument name is error_message, not message — using 'message' will cause Terraform to fail to parse the validation block.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A module needs to create one aws_iam_user resource for each name in a list that may be reordered or have items removed from the middle over time. The team wants removing a single name from the list to destroy only that user's resource, without forcing Terraform to destroy and recreate other users due to index shifting. Which approach should be used?", "prompt": {"question": "<p>A module needs to create one aws_iam_user resource for each name in a list that may be reordered or have items removed from the middle over time. The team wants removing a single name from the list to destroy only that user's resource, without forcing Terraform to destroy and recreate other users due to index shifting. Which approach should be used?</p>", "answers": ["<p>Use count = length(var.user_names) and index into var.user_names[count.index]</p>", "<p>Use count with a fixed number greater than the list length and pad the list with empty strings</p>", "<p>Use for_each = var.user_names directly without converting the list to a set or map</p>", "<p>Convert the list to a set with toset(var.user_names) and use for_each = toset(var.user_names)</p>"], "feedbacks": ["<p>count uses numeric indices (count.index). Removing an item from the middle of the list shifts all subsequent indices, causing Terraform to plan destroy/recreate for every user after the removed one, not just the target.</p>", "<p>Padding the list with empty strings to keep count fixed is not a real Terraform pattern and would create invalid or unwanted IAM user resources with empty names.</p>", "<p>for_each requires a map or a set of strings as its argument; passing a list directly (var.user_names) is not supported and Terraform will raise an error requiring conversion via toset() or a map.</p>", "<p>for_each keys resources by a stable identifier (map key or set element) rather than a numeric index. Converting the list to a set with toset() and using for_each = toset(var.user_names) means each resource instance is tracked by its name value, so removing one name only destroys that specific instance — the others are unaffected.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An aws_security_group resource needs a variable number of ingress rules generated from a list variable called var.ingress_rules, where each element is an object with from_port, to_port, and cidr_blocks. Which HCL construct correctly generates repeated nested ingress blocks from this list?", "prompt": {"question": "<p>An aws_security_group resource needs a variable number of ingress rules generated from a list variable called var.ingress_rules, where each element is an object with from_port, to_port, and cidr_blocks. Which HCL construct correctly generates repeated nested ingress blocks from this list?</p>", "answers": ["<p>A for expression assigned directly to the ingress argument: ingress = [for r in var.ingress_rules : r]</p>", "<p>A count argument set on the security group resource itself with count = length(var.ingress_rules)</p>", "<p>A dynamic block named \"ingress_rules\" with for_each = var.ingress_rules, since the block name must match the variable name</p>", "<p>A dynamic \"ingress\" block with for_each = var.ingress_rules and a content block referencing ingress.value.from_port, ingress.value.to_port, and ingress.value.cidr_blocks</p>"], "feedbacks": ["<p>Assigning a for expression list directly to the ingress argument does not work because ingress is a nested block type, not a list-typed argument — nested blocks cannot be set with a simple assignment.</p>", "<p>count applies to the entire resource, creating multiple separate security groups, not multiple ingress rules within a single security group.</p>", "<p>The dynamic block's label must match the nested block type it's generating (ingress), not the source variable's name — using 'ingress_rules' as the label would attempt to generate a nonexistent nested block type and fail.</p>", "<p>To generate a variable number of nested configuration blocks (like ingress inside aws_security_group), Terraform requires a dynamic block. The block is named after the nested block type being generated (dynamic \"ingress\"), takes for_each to iterate the list, and uses a content block that references each element via the iterator's default name (ingress.value.&lt;attribute&gt;).</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A resource block for an aws_instance includes a lifecycle block with a precondition that checks self.ami is not empty, and the condition evaluates to false during terraform apply. What is the correct description of Terraform's behavior?", "prompt": {"question": "<p>A resource block for an aws_instance includes a lifecycle block with a precondition that checks self.ami is not empty, and the condition evaluates to false during terraform apply. What is the correct description of Terraform's behavior?</p>", "answers": ["<p>Terraform halts execution and reports an error referencing the precondition's error_message before the resource is created or updated</p>", "<p>Terraform logs a warning but continues applying the resource, since preconditions are advisory only</p>", "<p>Terraform silently skips creating that resource but continues applying all other resources in the configuration</p>", "<p>Terraform automatically substitutes a default AMI value and continues the apply</p>"], "feedbacks": ["<p>A precondition inside a lifecycle block is evaluated before the resource is created or updated. If the condition expression evaluates to false, Terraform halts with an error displaying the specified error_message, preventing the apply from proceeding for that resource (and any dependents).</p>", "<p>Preconditions and postconditions are enforced, not advisory — a failed condition stops the apply, it does not just log a warning.</p>", "<p>Terraform does not silently skip failed-precondition resources; it raises a blocking error that must be fixed before apply can succeed.</p>", "<p>Terraform has no mechanism to auto-substitute default values for a failed precondition — there is no such fallback behavior.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An output value in a root module is defined as:\n\noutput \"db_password\" {\n  value     = var.db_password\n  sensitive = true\n}\n\nWhich statement correctly describes the effect of setting sensitive = true on this output?", "prompt": {"question": "<p>An output value in a root module is defined as:\n\noutput \"db_password\" {\n  value     = var.db_password\n  sensitive = true\n}\n\nWhich statement correctly describes the effect of setting sensitive = true on this output?</p>", "answers": ["<p>Terraform CLI redacts the value from plan and apply console output, but the value is still stored in plain text in the state file</p>", "<p>The value is encrypted before being written to the state file, so it cannot be read even with access to the state</p>", "<p>The output is excluded entirely from the state file, so terraform output cannot retrieve it under any circumstances</p>", "<p>Terraform automatically integrates with HashiCorp Vault to store the value externally instead of in state</p>"], "feedbacks": ["<p>Marking an output (or variable) sensitive only affects Terraform's CLI display behavior — the value is hidden/redacted (shown as (sensitive value)) in plan, apply, and console output. It does not encrypt or remove the value from the state file; the raw value is still persisted in plain text in terraform.tfstate, which is why state files must be protected via a secure backend and access controls.</p>", "<p>Terraform does not encrypt sensitive values within the state file itself — sensitive marking is a CLI display feature, not encryption at rest; state encryption/protection must be handled separately (e.g., encrypted backend storage).</p>", "<p>The value remains fully present in the state file; sensitive marking does not remove or omit it. terraform output -raw db_password can still retrieve the actual value when explicitly requested.</p>", "<p>There is no automatic Vault integration triggered by the sensitive flag; integrating with Vault requires explicitly using the Vault provider/data source to fetch secrets, it's unrelated to the sensitive attribute.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A configuration creates an aws_iam_policy resource and a separate aws_instance resource whose user_data script calls an internal API that requires the IAM policy to already exist, but the aws_instance resource's arguments do not reference any attribute of the aws_iam_policy resource. Which construct ensures Terraform creates the IAM policy before the EC2 instance, given there is no implicit attribute reference to create a dependency?", "prompt": {"question": "<p>A configuration creates an aws_iam_policy resource and a separate aws_instance resource whose user_data script calls an internal API that requires the IAM policy to already exist, but the aws_instance resource's arguments do not reference any attribute of the aws_iam_policy resource. Which construct ensures Terraform creates the IAM policy before the EC2 instance, given there is no implicit attribute reference to create a dependency?</p>", "answers": ["<p>Add depends_on = [aws_iam_policy.example] inside the aws_instance resource block</p>", "<p>Add a precondition block on the aws_instance resource checking that the policy exists</p>", "<p>Rename the aws_instance resource so it alphabetically sorts after aws_iam_policy in the configuration file</p>", "<p>Add a provisioner \"local-exec\" block that sleeps for 30 seconds before instance creation</p>"], "feedbacks": ["<p>When two resources have a dependency that Terraform cannot infer from resource attribute references (no interpolation from one to the other), an explicit depends_on argument must be added to force the correct ordering. depends_on = [aws_iam_policy.example] tells Terraform to always create/update aws_iam_policy.example before the aws_instance resource, regardless of attribute references.</p>", "<p>A precondition validates a boolean expression about resource attributes at plan/apply time; it does not create an ordering dependency between unrelated resources and cannot guarantee the policy already exists before the instance is created.</p>", "<p>Terraform's dependency graph is based on references and depends_on, not on file order or alphabetical resource naming — reordering resource names in configuration has no effect on apply ordering.</p>", "<p>A local-exec provisioner with a sleep is an unreliable workaround that doesn't guarantee the policy exists, adds unnecessary delay, and is explicitly discouraged as a substitute for proper dependency declarations like depends_on.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A data source block in your configuration reads an AWS AMI and must fail the plan with a custom error message if the returned AMI is not tagged \"encrypted = true\". Which construct should you add inside the data block to enforce this?", "prompt": {"question": "<p>A data source block in your configuration reads an AWS AMI and must fail the plan with a custom error message if the returned AMI is not tagged \"encrypted = true\". Which construct should you add inside the data block to enforce this?</p>", "answers": ["<p>A variable \"validation\" block referencing the data source's attribute</p>", "<p>A \"lifecycle\" block containing a \"precondition\"</p>", "<p>A \"lifecycle\" block containing a \"postcondition\"</p>", "<p>A separate \"check\" block that references a null_resource</p>"], "feedbacks": ["<p>Variable validation blocks only apply to input variables declared with the 'variable' keyword; they cannot validate attributes returned by a data source.</p>", "<p>Preconditions are evaluated before the resource/data source action executes and typically check conditions about input expressions or dependencies, not the actual result returned by the read, so they can't validate the fetched AMI's tag.</p>", "<p>Postconditions live in a lifecycle block and are evaluated after the data source is read (or after a resource is created/updated), making them the correct tool to validate the actual returned value, such as a tag on a fetched AMI, and fail with a custom_condition error message if it doesn't meet expectations.</p>", "<p>Terraform does not support attaching a 'check' block directly to a null_resource for this purpose; standalone 'check' blocks are a separate top-level construct used for post-apply assertions across the configuration, not the mechanism for validating a specific data source result inline.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A team wants to reuse a VPC module from the public Terraform Registry. They need to automatically receive patch-level bug fixes but must NOT automatically receive minor or major version changes. Which version constraint achieves this?", "prompt": {"question": "<p>A team wants to reuse a VPC module from the public Terraform Registry. They need to automatically receive patch-level bug fixes but must NOT automatically receive minor or major version changes. Which version constraint achieves this?</p>", "answers": ["<p>version = \"~&gt; 3.0\"</p>", "<p>version = \"&gt;= 3.0\"</p>", "<p>version = \"= 3.0.0\"</p>", "<p>version = \"&lt;= 3.0\"</p>"], "feedbacks": ["<p>The pessimistic constraint operator ~&gt; 3.0 (with two version segments) allows only the rightmost component to increment, permitting 3.0.1, 3.0.2, etc., but excluding 3.1.0 or 4.0.0 — exactly patch-only updates.</p>", "<p>'&gt;= 3.0' has no upper bound and would allow any future major version, including breaking 4.x releases.</p>", "<p>'= 3.0.0' pins to a single exact version and blocks even patch fixes, requiring manual updates for every bug fix.</p>", "<p>'&lt;= 3.0' allows any version at or below 3.0, including older/downgraded versions, and doesn't restrict to patch updates at all.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team maintains a network module in a private GitHub repository that is only accessible over SSH (no HTTPS credentials configured). Which module source correctly references this module?", "prompt": {"question": "<p>A platform team maintains a network module in a private GitHub repository that is only accessible over SSH (no HTTPS credentials configured). Which module source correctly references this module?</p>", "answers": ["<p>source = \"registry.terraform.io/org/network-module/aws\"</p>", "<p>source = \"github.com/org/network-module\"</p>", "<p>source = \"git::ssh://git@github.com/org/network-module.git\"</p>", "<p>source = \"./modules/network-module\"</p>"], "feedbacks": ["<p>This is a Terraform Registry address, used for modules published to a registry, not for arbitrary Git repositories.</p>", "<p>The GitHub shorthand form resolves to a Git-over-HTTPS clone by default, which will fail without HTTPS credentials for a private repo.</p>", "<p>The generic git:: source prefix with an explicit ssh:// protocol tells Terraform to clone the repository using the local SSH configuration, which is required when HTTPS access is not set up for a private repo.</p>", "<p>A relative local path only works for modules stored in the same filesystem/repository as the calling configuration, not for an external Git-hosted module.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly describes the version argument inside a module block?", "prompt": {"question": "<p>Which statement correctly describes the version argument inside a module block?</p>", "answers": ["<p>It is only supported for modules sourced from a Terraform Registry (public or private).</p>", "<p>It must always specify an exact version number with no ranges.</p>", "<p>It is required in every module block regardless of the source type.</p>", "<p>It can be used with any module source, including local paths and generic Git URLs.</p>"], "feedbacks": ["<p>The version argument is only meaningful for registry-hosted modules, which publish semantic version metadata; Terraform uses it to resolve a matching published version.</p>", "<p>Version constraints support operators like ~&gt;, &gt;=, and comma-separated ranges — an exact number is only one valid form, not a requirement.</p>", "<p>The version argument is optional; local-path and non-registry modules don't use it at all, and even registry modules can omit it (defaulting to latest).</p>", "<p>Local paths and generic Git/HTTP sources do not support the version argument — Git sources instead use a ref query parameter in the source URL to select a commit, branch, or tag.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A child module named 'storage' declares an output block named 'bucket_arn'. What is the correct syntax for the root module to reference this value elsewhere in its configuration?", "prompt": {"question": "<p>A child module named 'storage' declares an output block named 'bucket_arn'. What is the correct syntax for the root module to reference this value elsewhere in its configuration?</p>", "answers": ["<p>output.storage.bucket_arn</p>", "<p>data.storage.bucket_arn</p>", "<p>module.storage.bucket_arn</p>", "<p>var.storage.bucket_arn</p>"], "feedbacks": ["<p>The output. prefix is not valid reference syntax in Terraform; outputs are accessed through the module. namespace, not directly.</p>", "<p>The data. prefix is reserved for referencing data sources, not module outputs.</p>", "<p>Outputs exported by a child module are referenced from the calling module using module.&lt;MODULE_NAME&gt;.&lt;OUTPUT_NAME&gt;, where MODULE_NAME matches the label used in the module block.</p>", "<p>The var. prefix references input variables declared in the current module, not outputs produced by a called module.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A root module calls a 'network' module that outputs 'environment_tier', and a 'database' module that requires an input variable 'instance_class' set to that value. Which module block correctly wires this dependency?", "prompt": {"question": "<p>A root module calls a 'network' module that outputs 'environment_tier', and a 'database' module that requires an input variable 'instance_class' set to that value. Which module block correctly wires this dependency?</p>", "answers": ["<p>module \"database\" {\n  source = \"./modules/database\"\n  instance_class = var.network.environment_tier\n}</p>", "<p>module \"network\" {\n  source = \"./modules/database\"\n  instance_class = network.environment_tier\n}</p>", "<p>module \"database\" {\n  source = \"./modules/database\"\n  instance_class = data.network.environment_tier\n}</p>", "<p>module \"database\" {\n  source = \"./modules/database\"\n  instance_class = module.network.environment_tier\n}</p>"], "feedbacks": ["<p>var.network.environment_tier is invalid syntax — var. is only used for the current module's own declared input variables, not for referencing another module's outputs.</p>", "<p>This block mislabels the module as \"network\" while pointing its source at the database module directory, and uses a bare identifier that isn't valid output-reference syntax, breaking both wiring and naming.</p>", "<p>data.network.environment_tier is invalid — the data. prefix is reserved for data source blocks, not module outputs.</p>", "<p>Passing module.network.environment_tier as the value for instance_class correctly references the network module's output, and Terraform automatically infers the dependency so network is applied before database.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team of five engineers all run `terraform apply` from their local machines against the same infrastructure using the default local backend. They frequently encounter corrupted state and conflicting changes when two people apply around the same time. Which change BEST resolves this?", "prompt": {"question": "<p>A team of five engineers all run `terraform apply` from their local machines against the same infrastructure using the default local backend. They frequently encounter corrupted state and conflicting changes when two people apply around the same time. Which change BEST resolves this?</p>", "answers": ["<p>Add a `lifecycle { prevent_destroy = true }` block to every resource</p>", "<p>Have each engineer run `terraform refresh` before every apply</p>", "<p>Share a single `terraform.tfvars` file via email before each apply</p>", "<p>Migrate to a remote backend that supports state locking, such as HCP Terraform or S3 with native locking</p>"], "feedbacks": ["<p>prevent_destroy only blocks accidental destroy of a specific resource; it does nothing to prevent concurrent state writes.</p>", "<p>terraform refresh only updates state to match real infrastructure; it does not provide locking and won't stop two simultaneous applies from corrupting state.</p>", "<p>Sharing tfvars files addresses variable input consistency, not the underlying state storage/locking problem causing corruption.</p>", "<p>Remote backends with locking (HCP Terraform, or S3 with its native conditional-write locking, or the older S3+DynamoDB pattern) prevent concurrent writes to state, which is exactly the corruption/conflict scenario described.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A resource block manages a database whose `admin_password` attribute is marked as `sensitive = true` in the Terraform configuration. A security reviewer asks whether the password is safe from exposure. Which statement is correct?", "prompt": {"question": "<p>A resource block manages a database whose `admin_password` attribute is marked as `sensitive = true` in the Terraform configuration. A security reviewer asks whether the password is safe from exposure. Which statement is correct?</p>", "answers": ["<p>Marking the attribute sensitive prevents Terraform from ever writing it into the state file</p>", "<p>Terraform automatically encrypts all sensitive values inside the local state file by default</p>", "<p>The state file may still contain the password in plaintext; access must be restricted using an encrypted remote backend with strict IAM/permissions and locking</p>", "<p>Using the local backend instead of a remote one guarantees the password cannot be exposed</p>"], "feedbacks": ["<p>sensitive = true only affects console/UI output, not what gets persisted in state.</p>", "<p>Terraform does not automatically encrypt state file contents by default for local or most remote backends unless the backend itself provides encryption (e.g., S3 server-side encryption).</p>", "<p>The `sensitive` attribute only redacts values from CLI plan/apply output and logs; the actual value is still stored in plaintext in the state file. Best practice is to store state in an encrypted, access-restricted remote backend.</p>", "<p>Local state files are plaintext JSON on disk and are arguably easier to accidentally expose (e.g., via version control) than a properly secured remote backend.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which backend option provides remote state storage AND state locking natively, without requiring the operator to provision or configure a separate locking mechanism?", "prompt": {"question": "<p>Which backend option provides remote state storage AND state locking natively, without requiring the operator to provision or configure a separate locking mechanism?</p>", "answers": ["<p>Local backend</p>", "<p>HCP Terraform (Terraform Cloud) remote backend</p>", "<p>S3 backend configured only with a bucket and no additional locking table or feature enabled</p>", "<p>An `http` backend implementation that does not implement lock/unlock endpoints</p>"], "feedbacks": ["<p>The local backend stores state on disk with no locking across multiple users at all.</p>", "<p>HCP Terraform (Terraform Cloud) provides remote state storage with locking built in as part of the platform — no extra infrastructure needs to be configured by the user.</p>", "<p>A bare S3 bucket without the DynamoDB table (older versions) or native locking configuration enabled does not provide locking, only storage.</p>", "<p>An http backend only supports locking if the remote endpoint implements the optional lock/unlock API calls; otherwise it offers no locking.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An engineer needs to stop Terraform from managing a specific resource going forward, but must NOT destroy the actual infrastructure object it represents. Which command should be used?", "prompt": {"question": "<p>An engineer needs to stop Terraform from managing a specific resource going forward, but must NOT destroy the actual infrastructure object it represents. Which command should be used?</p>", "answers": ["<p>terraform destroy -target=&lt;resource&gt;</p>", "<p>terraform taint &lt;resource&gt;</p>", "<p>terraform state rm &lt;resource&gt;</p>", "<p>terraform import &lt;resource&gt; &lt;id&gt;</p>"], "feedbacks": ["<p>terraform destroy -target actually destroys the real infrastructure object, which is the opposite of what's needed.</p>", "<p>terraform taint marks a resource for recreation on the next apply, causing it to be destroyed and re-created — not the desired outcome.</p>", "<p>terraform state rm removes a resource from the state file only; the real-world object is untouched and Terraform no longer tracks it.</p>", "<p>terraform import brings an existing object INTO state; it does the opposite of removing tracking.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A module was refactored so that `aws_instance.web` is now written as `aws_instance.app_server`. To avoid Terraform planning to destroy the old resource and create a new one, which configuration block should be added to the module?", "prompt": {"question": "<p>A module was refactored so that `aws_instance.web` is now written as `aws_instance.app_server`. To avoid Terraform planning to destroy the old resource and create a new one, which configuration block should be added to the module?</p>", "answers": ["<p>A `removed` block referencing aws_instance.web</p>", "<p>A `lifecycle { create_before_destroy = true }` block on aws_instance.app_server</p>", "<p>A `moved` block with `from = aws_instance.web` and `to = aws_instance.app_server`</p>", "<p>An `import` block targeting the existing instance ID</p>"], "feedbacks": ["<p>A removed block is used to tell Terraform a resource should be removed from state/management entirely (optionally destroying it), not to rename it — that's a different use case.</p>", "<p>create_before_destroy changes replacement ordering but still results in destroy/recreate for a renamed address; it does not solve the address-mapping issue.</p>", "<p>The `moved` block tells Terraform that a resource's address changed, so it updates the state mapping in place instead of destroying and recreating the resource.</p>", "<p>An import block brings a new, previously-unmanaged real-world resource under management by ID; it isn't used to rename an already-managed resource address.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "What is the primary purpose of the Terraform state file?", "prompt": {"question": "<p>What is the primary purpose of the Terraform state file?</p>", "answers": ["<p>It maps configuration-defined resources to real-world infrastructure objects and tracks resource metadata and dependencies</p>", "<p>It stores a human-readable copy of the .tf configuration files for documentation purposes</p>", "<p>It stores the provider plugin binaries used during apply</p>", "<p>It permanently logs the full history of every past apply and plan output</p>"], "feedbacks": ["<p>State is the source of truth Terraform uses to map declared resources in configuration to actual objects in the real world, tracking IDs, attributes, and dependency ordering between applies.</p>", "<p>State is not a copy of .tf files; it's a record of resources and their current attributes, in JSON format.</p>", "<p>Provider plugin binaries are stored in the .terraform directory / plugin cache, not in the state file.</p>", "<p>State reflects only the most recent known state of infrastructure; it is not an audit log of every past plan/apply (that's a separate concern, e.g., HCP Terraform's run history).</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team manages 40 HCP Terraform workspaces that all need the same AWS credentials and a shared 'environment=prod' variable, but they don't want to copy-paste these variables into every workspace individually. Which HCP Terraform feature BEST meets this requirement?", "prompt": {"question": "<p>A platform team manages 40 HCP Terraform workspaces that all need the same AWS credentials and a shared 'environment=prod' variable, but they don't want to copy-paste these variables into every workspace individually. Which HCP Terraform feature BEST meets this requirement?</p>", "answers": ["<p>Create a module with default variables and require every workspace to call it</p>", "<p>Define a variable set containing the shared variables and apply it to the relevant workspaces</p>", "<p>Use a run trigger to pass variables between workspaces</p>", "<p>Store the variables in a shared remote state data source</p>"], "feedbacks": ["<p>Module defaults don't propagate credentials or workspace-level variables set through the UI/API; it addresses code reuse, not variable distribution.</p>", "<p>Variable sets let you define a group of variables (including sensitive ones) once and attach them to multiple workspaces or an entire project, avoiding duplication and easing updates.</p>", "<p>Run triggers queue runs in a downstream workspace after an upstream apply — they don't share variable values.</p>", "<p>Remote state data sources expose output values from another workspace's state, not input variables like credentials.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Which policy-as-code framework is natively integrated into HCP Terraform for enforcing governance rules on runs, distinct from the Open Policy Agent (OPA) integration also supported?", "prompt": {"question": "<p>Which policy-as-code framework is natively integrated into HCP Terraform for enforcing governance rules on runs, distinct from the Open Policy Agent (OPA) integration also supported?</p>", "answers": ["<p>Sentinel</p>", "<p>AWS Config</p>", "<p>Checkov</p>", "<p>Terraform Cloud Agent</p>"], "feedbacks": ["<p>Sentinel is HashiCorp's proprietary policy-as-code framework built into HCP Terraform (available in higher tiers), used alongside the OPA integration to enforce advisory, soft-mandatory, or hard-mandatory policies before applies.</p>", "<p>AWS Config is an AWS-native compliance service unrelated to HCP Terraform's policy enforcement.</p>", "<p>Checkov is a third-party static analysis tool, not natively built into HCP Terraform's run pipeline.</p>", "<p>Terraform Cloud Agent (Agent pools) enables private network runs; it has nothing to do with policy enforcement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A team wants HCP Terraform runs to authenticate to AWS during provisioning without storing long-lived static access keys as workspace variables. Which HCP Terraform feature should they configure?", "prompt": {"question": "<p>A team wants HCP Terraform runs to authenticate to AWS during provisioning without storing long-lived static access keys as workspace variables. Which HCP Terraform feature should they configure?</p>", "answers": ["<p>Variable sets with sensitive variables</p>", "<p>Run triggers</p>", "<p>Dynamic provider credentials using OIDC</p>", "<p>Sentinel policy</p>"], "feedbacks": ["<p>Sensitive variable sets can hide values in the UI, but the keys are still long-lived static secrets stored in HCP Terraform.</p>", "<p>Run triggers only chain runs between workspaces; they don't handle authentication.</p>", "<p>Dynamic provider credentials let HCP Terraform generate short-lived credentials at run time via OIDC federation with the cloud provider, eliminating the need to store static long-lived secrets.</p>", "<p>Sentinel enforces policy compliance on plans, but doesn't provide or manage provider credentials.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team has a 'networking' workspace and an 'app' workspace. They want every successful apply in networking to automatically queue a new run in app. Which HCP Terraform feature enables this?", "prompt": {"question": "<p>A platform team has a 'networking' workspace and an 'app' workspace. They want every successful apply in networking to automatically queue a new run in app. Which HCP Terraform feature enables this?</p>", "answers": ["<p>Sentinel policy</p>", "<p>Variable sets</p>", "<p>Run triggers</p>", "<p>Workspace tags</p>"], "feedbacks": ["<p>Sentinel policies gate whether a run is allowed to apply; they don't trigger runs in other workspaces.</p>", "<p>Variable sets share variable values across workspaces but don't queue new runs.</p>", "<p>Run triggers connect a source workspace to one or more downstream workspaces so that a successful apply in the source automatically queues a plan/run in the linked workspace, enabling dependency chaining across workspaces.</p>", "<p>Workspace tags are used for organizing and filtering workspaces, not for chaining executions.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "What does HCP Terraform's drift detection feature do?", "prompt": {"question": "<p>What does HCP Terraform's drift detection feature do?</p>", "answers": ["<p>Automatically applies changes to fix drift without approval</p>", "<p>Rolls back state to a previous version when drift is detected</p>", "<p>Locks the workspace to prevent any further runs</p>", "<p>Periodically runs a plan against workspaces (without applying) to detect changes made outside Terraform</p>"], "feedbacks": ["<p>Drift detection never applies changes automatically — it only reports detected drift; a human must review and act.</p>", "<p>It does not roll back state; state versioning/rollback is a separate, manual capability.</p>", "<p>Detected drift does not lock the workspace; runs can still be queued normally.</p>", "<p>Drift detection schedules periodic speculative plans on workspaces to compare real infrastructure against the last-known state and surface any out-of-band changes, without applying anything automatically.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}], "expected": 44}, {"name": "Terraform Associate Practice Test 2", "cid": 7301147, "duration": 60, "pass_percent": 70, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A platform team enforces Terraform for all provisioning, but an engineer occasionally makes emergency changes directly in the cloud console to resolve incidents faster. Weeks later, `terraform plan` begins showing unexpected diffs even though no one edited the .tf files. Which IaC concept explains this behavior and the primary reason Terraform is designed to surface it?", "prompt": {"question": "<p>A platform team enforces Terraform for all provisioning, but an engineer occasionally makes emergency changes directly in the cloud console to resolve incidents faster. Weeks later, `terraform plan` begins showing unexpected diffs even though no one edited the .tf files. Which IaC concept explains this behavior and the primary reason Terraform is designed to surface it?</p>", "answers": ["<p>Configuration drift — the real infrastructure no longer matches the declared state, and Terraform's plan compares real-world state against the desired configuration to reveal the gap</p>", "<p>Idempotency failure — Terraform re-applied the same configuration twice and produced inconsistent results</p>", "<p>Provider version skew — the console changes updated the provider plugin to a newer API version than the configuration expects</p>", "<p>State locking failure — concurrent applies corrupted the state file, causing false diffs to appear</p>"], "feedbacks": ["<p>Manual out-of-band changes cause the actual infrastructure to diverge from what's declared in code — this is configuration drift. One of the core value propositions of IaC/Terraform is that `plan` detects drift by comparing the refreshed real-world state to the desired configuration, making the divergence visible before it causes bigger problems.</p>", "<p>Idempotency describes applying the same configuration repeatedly and getting the same end result — it doesn't explain a mismatch caused by out-of-band manual changes.</p>", "<p>Provider version skew is unrelated; changing a resource in the console doesn't alter which provider plugin version Terraform uses.</p>", "<p>State locking prevents concurrent writes to the state file during operations; it has nothing to do with detecting manual infrastructure changes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs workloads across AWS, Azure, and an on-prem VMware cluster. Leadership wants a single team to manage provisioning for all three using one consistent operational workflow, even though the underlying APIs, authentication, and resource models differ completely between them. Which IaC benefit does this scenario primarily illustrate?", "prompt": {"question": "<p>A company runs workloads across AWS, Azure, and an on-prem VMware cluster. Leadership wants a single team to manage provisioning for all three using one consistent operational workflow, even though the underlying APIs, authentication, and resource models differ completely between them. Which IaC benefit does this scenario primarily illustrate?</p>", "answers": ["<p>Terraform normalizes all three platforms into a single identical HCL schema, so the same resource blocks work unmodified across providers</p>", "<p>State file portability — a single Terraform state file can represent resources from AWS, Azure, and VMware without separate backends</p>", "<p>Automatic cloud migration — Terraform can convert AWS-specific resource definitions into Azure or VMware equivalents automatically</p>", "<p>Provider-agnostic workflow — Terraform applies the same init/plan/apply/destroy lifecycle across any provider, even though each provider's HCL resources and arguments are unique</p>"], "feedbacks": ["<p>Each provider defines its own resource types and arguments; HCL schemas are provider-specific, not normalized into one identical schema.</p>", "<p>State files can technically reference multiple providers, but that's not the core benefit being described here, and using one shared state across unrelated environments is generally discouraged.</p>", "<p>Terraform does not auto-convert resource definitions between clouds; engineers must write provider-specific configuration for each platform.</p>", "<p>Terraform's multi-cloud/hybrid-cloud value isn't that every provider's resources look the same in HCL — they don't — it's that the operational workflow (init, plan, apply, destroy) and tooling stay consistent regardless of which provider is behind the scenes, letting one team standardize process across heterogeneous infrastructure.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A new hire is used to writing imperative shell scripts that issue a sequence of CLI commands to create a VPC, then subnets, then an internet gateway, checking each step's output before running the next. Which IaC characteristic of Terraform's declarative model most directly removes the need for this kind of manual sequencing logic?", "prompt": {"question": "<p>A new hire is used to writing imperative shell scripts that issue a sequence of CLI commands to create a VPC, then subnets, then an internet gateway, checking each step's output before running the next. Which IaC characteristic of Terraform's declarative model most directly removes the need for this kind of manual sequencing logic?</p>", "answers": ["<p>Terraform requires resources to be listed in the exact order they should be created, matching the script's original sequence</p>", "<p>Terraform executes .tf files as a linear imperative script, top to bottom, in file order</p>", "<p>Modules replace the need for dependency ordering entirely, since each module is provisioned independently in parallel</p>", "<p>You declare the desired end state of resources and their dependencies, and Terraform's graph engine determines the correct creation order automatically</p>"], "feedbacks": ["<p>Resource block order in .tf files does not dictate creation order; Terraform builds order from dependencies, not file layout.</p>", "<p>Terraform is explicitly not a linear imperative script executor — this misrepresents its declarative execution model.</p>", "<p>Modules don't remove dependency ordering; resources across or within modules can still depend on each other, and Terraform still resolves that order via the graph.</p>", "<p>Terraform is declarative: you describe the desired state and let implicit/explicit dependencies inform a dependency graph. Terraform's engine walks this graph to determine correct ordering and parallelizes non-dependent resources — eliminating the need to hand-write step-by-step imperative sequencing like the shell script approach.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "During a TA-004 exam-style discussion, two engineers debate terminology. One says Terraform is 'idempotent,' the other insists the correct term is that Terraform 'converges' infrastructure to a desired state. Which statement correctly distinguishes these two concepts as Terraform applies them?", "prompt": {"question": "<p>During a TA-004 exam-style discussion, two engineers debate terminology. One says Terraform is 'idempotent,' the other insists the correct term is that Terraform 'converges' infrastructure to a desired state. Which statement correctly distinguishes these two concepts as Terraform applies them?</p>", "answers": ["<p>They are synonyms in Terraform's context and can be used interchangeably with no meaningful distinction</p>", "<p>Idempotency means running the same apply repeatedly with no drift produces no further changes; convergence describes Terraform calculating and applying only the delta needed to move current state toward desired state, regardless of the starting point</p>", "<p>Convergence only applies to the first `terraform apply` on new infrastructure, while idempotency only applies to `terraform destroy` operations</p>", "<p>Idempotency refers to state file locking behavior, while convergence refers to provider plugin version resolution during `terraform init`</p>"], "feedbacks": ["<p>They describe related but distinct aspects (outcome vs. mechanism) of Terraform's behavior, so treating them as interchangeable is incorrect.</p>", "<p>Idempotency describes the outcome property: reapplying unchanged configuration against unchanged infrastructure produces no additional effect. Convergence describes the mechanism: Terraform compares current state to desired state from wherever it starts and computes/applies only the necessary delta. Both are real, related, but distinct IaC concepts underpinning Terraform's reliability.</p>", "<p>Neither concept is scoped to only 'first apply' or only 'destroy' operations — both apply broadly across the resource lifecycle.</p>", "<p>Neither term refers to state locking or provider plugin version resolution; those are unrelated Terraform mechanics.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team provisions cloud infrastructure with Terraform and uses Ansible to configure software on the provisioned VMs after they exist. During a design review, a new engineer proposes replacing Ansible entirely with Terraform's remote-exec provisioner to handle all ongoing configuration management. Which statement BEST explains why the team should reject this proposal?", "prompt": {"question": "<p>A platform team provisions cloud infrastructure with Terraform and uses Ansible to configure software on the provisioned VMs after they exist. During a design review, a new engineer proposes replacing Ansible entirely with Terraform's remote-exec provisioner to handle all ongoing configuration management. Which statement BEST explains why the team should reject this proposal?</p>", "answers": ["<p>Terraform cannot connect to remote hosts over SSH or WinRM, so provisioners are non-functional for VM configuration</p>", "<p>HashiCorp recommends provisioners as a last resort because they introduce imperative logic into an otherwise declarative dependency graph, but they can fully replace Ansible for ongoing configuration when written correctly</p>", "<p>Ansible's agentless architecture makes it categorically faster than Terraform at any infrastructure task, so it should always be preferred</p>", "<p>Terraform provisioners execute only during resource creation or destruction and are not designed for ongoing configuration management, so they cannot replace a dedicated CM tool for continuous drift correction</p>"], "feedbacks": ["<p>Terraform's remote-exec provisioner does support SSH and WinRM connections, so this claim is factually false</p>", "<p>This option correctly states HashiCorp's last-resort guidance but then draws the wrong conclusion — the create/destroy-only execution model means provisioners still cannot replace continuous CM even if 'written correctly'</p>", "<p>This is an unsupported blanket generalization; agentless architecture does not make a tool universally faster, and speed is not the reason CM tools remain necessary here</p>", "<p>Provisioners (including remote-exec) only run once, at create or destroy time, tied to a resource's lifecycle. They have no mechanism to periodically re-check or correct configuration drift the way a CM tool run on a schedule or via orchestration can, so they are unsuitable as a full replacement for ongoing configuration management.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization is evaluating Terraform against a purely imperative scripting approach (a bash script that calls cloud CLI commands in a fixed sequence) for provisioning a VPC, subnets, and EC2 instances. Which capability is unique to Terraform's declarative model in this comparison?", "prompt": {"question": "<p>An organization is evaluating Terraform against a purely imperative scripting approach (a bash script that calls cloud CLI commands in a fixed sequence) for provisioning a VPC, subnets, and EC2 instances. Which capability is unique to Terraform's declarative model in this comparison?</p>", "answers": ["<p>Terraform automatically retries failed provider API calls up to a fixed number of times before failing the run</p>", "<p>Terraform executes resource creation strictly in the order resources appear in the .tf files, exactly matching the imperative script's behavior</p>", "<p>Terraform requires the same manually authored ordering logic as the bash script, but adds idempotency checks after each API call</p>", "<p>Terraform builds a resource dependency graph from configuration references and determines the correct creation order automatically, without the author specifying explicit sequencing</p>"], "feedbacks": ["<p>Retry behavior is an implementation detail of individual providers/SDKs, not the defining declarative-vs-imperative distinction being tested</p>", "<p>File order is irrelevant to execution order in Terraform; the graph, not text position, determines sequencing, so this description is false</p>", "<p>This ignores that Terraform's graph-based ordering removes the need for manually authored sequencing entirely — it does not merely add checks on top of imperative logic</p>", "<p>Terraform parses resource attribute references to build a directed acyclic resource graph, then walks that graph to determine correct create/update/destroy order. The author never writes explicit ordering logic — this is the core distinction from imperative scripting, where sequence must be hand-coded.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team needs to provision resources across AWS, Azure, and a private VMware vSphere environment from a single workflow, and wants one tool to track the current real-world state of all created resources so it can detect and reconcile drift on every run. Which factor makes Terraform the better fit for this requirement than a general-purpose configuration management tool like Ansible?", "prompt": {"question": "<p>A team needs to provision resources across AWS, Azure, and a private VMware vSphere environment from a single workflow, and wants one tool to track the current real-world state of all created resources so it can detect and reconcile drift on every run. Which factor makes Terraform the better fit for this requirement than a general-purpose configuration management tool like Ansible?</p>", "answers": ["<p>Terraform maintains a state file that models the last-known attributes of managed infrastructure and compares it against provider APIs on each plan, enabling drift detection independent of manually maintained inventories</p>", "<p>Terraform is agentless, so it does not require SSH access to target systems, unlike Ansible</p>", "<p>Ansible cannot connect to more than one cloud provider within a single playbook run</p>", "<p>Terraform configuration files must be written in YAML, giving it a lower learning curve for teams already writing Ansible playbooks</p>"], "feedbacks": ["<p>Terraform's state file is the mechanism that enables systematic drift detection: every plan compares the state's recorded attributes against real provider data. This state-centric model, not agent architecture or file format, is what distinguishes Terraform's fit for cross-platform provisioning and reconciliation.</p>", "<p>Ansible is also agentless (it uses SSH/WinRM push connections), so this is not a meaningful differentiator and does not address drift detection</p>", "<p>Ansible playbooks can target and orchestrate across multiple cloud providers in one run; this claim is false</p>", "<p>Terraform configuration is written in HCL, not YAML; this option contains a factual error</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "During terraform plan, an engineer notices the CLI output shows an EC2 instance resource with '~ update in-place' for the instance_type attribute but '-/+ destroy and re-create' for the ami attribute within the same resource block. Which underlying Terraform behavior explains why the same resource shows two different change actions?", "prompt": {"question": "<p>During terraform plan, an engineer notices the CLI output shows an EC2 instance resource with '~ update in-place' for the instance_type attribute but '-/+ destroy and re-create' for the ami attribute within the same resource block. Which underlying Terraform behavior explains why the same resource shows two different change actions?</p>", "answers": ["<p>Terraform batches all attribute changes into a single action type per resource; this mixed output indicates a provider bug that must be reported to HashiCorp</p>", "<p>The ami attribute always forces replacement across every Terraform provider, regardless of how that provider's schema defines it</p>", "<p>Terraform only recreates a resource when its resource address changes in configuration, never based on attribute value changes</p>", "<p>Each attribute in a resource's provider schema is marked as either updatable in-place or as forcing replacement (ForceNew); the plan reflects the most severe action required across all changed attributes for that resource</p>"], "feedbacks": ["<p>Mixed action types in one resource's diff is expected, correct behavior driven by schema attribute flags, not a bug</p>", "<p>ForceNew behavior is defined per provider/resource schema; it is not a universal rule that applies identically to every provider's implementation of a similarly named attribute</p>", "<p>Resource replacement is driven by ForceNew attribute changes as defined in the provider schema, not solely by changes to the resource's address in configuration</p>", "<p>Provider schemas declare per-attribute update behavior. Attributes flagged ForceNew (like ami on aws_instance) trigger destroy-and-recreate, while others (like instance_type) support in-place update via the API. When multiple attributes change, Terraform's plan surfaces the most disruptive required action for that resource.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Your team's Terraform configuration currently pins the AWS provider to version 4.0.0. You want Terraform to automatically pick up new minor and patch releases (e.g., 4.1.0, 4.5.2) but must never allow the provider to upgrade to the 5.x major version line. Which version constraint should you use in the required_providers block?", "prompt": {"question": "<p>Your team's Terraform configuration currently pins the AWS provider to version 4.0.0. You want Terraform to automatically pick up new minor and patch releases (e.g., 4.1.0, 4.5.2) but must never allow the provider to upgrade to the 5.x major version line. Which version constraint should you use in the required_providers block?</p>", "answers": ["<p>~&gt; 4.0.0</p>", "<p>~&gt; 4.0</p>", "<p>&gt;= 4.0.0</p>", "<p>= 4.0.0</p>"], "feedbacks": ["<p>'~&gt; 4.0.0' (three segments) only allows patch-level updates (&gt;= 4.0.0, &lt; 4.1.0) — it would block 4.1.0, which the requirement needs.</p>", "<p>The pessimistic constraint operator behaves differently depending on how many version segments are given. '~&gt; 4.0' (two segments) means &gt;= 4.0.0 and &lt; 5.0.0, so it allows both minor and patch upgrades within the 4.x line but blocks 5.0.</p>", "<p>'&gt;= 4.0.0' places no upper bound at all, so Terraform could upgrade all the way to 5.x or beyond, violating the requirement.</p>", "<p>'= 4.0.0' pins to the exact version and blocks all upgrades, including the minor/patch updates the requirement calls for.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A teammate updated the version constraint for the azurerm provider in required_providers from \"~> 3.0\" to \"~> 4.0\" and pushed the change. When you pull the change and run 'terraform plan', Terraform reports that the installed provider version does not satisfy the new constraints and refuses to proceed, even though your .terraform.lock.hcl still lists the old 3.x version. What is the correct command to resolve this?", "prompt": {"question": "<p>A teammate updated the version constraint for the azurerm provider in required_providers from \"~&gt; 3.0\" to \"~&gt; 4.0\" and pushed the change. When you pull the change and run 'terraform plan', Terraform reports that the installed provider version does not satisfy the new constraints and refuses to proceed, even though your .terraform.lock.hcl still lists the old 3.x version. What is the correct command to resolve this?</p>", "answers": ["<p>terraform state replace-provider</p>", "<p>terraform validate -upgrade</p>", "<p>terraform apply -auto-approve</p>", "<p>terraform init -upgrade</p>"], "feedbacks": ["<p>'terraform state replace-provider' changes the provider FQN recorded against resources in state (e.g., migrating from a legacy provider source) — it does not resolve a version constraint mismatch.</p>", "<p>'terraform validate' does not accept a '-upgrade' flag and only checks configuration syntax/internal consistency; it does not install or upgrade providers.</p>", "<p>'terraform apply' will fail with the same provider version error since init has not been re-run to fetch a version satisfying the new constraint.</p>", "<p>'terraform init -upgrade' tells Terraform to consider newer provider versions that satisfy the updated constraints, download the new provider, and update the .terraform.lock.hcl file accordingly.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "You must deploy identical S3 buckets into both us-east-1 and eu-west-1 using a single AWS provider configuration block per region. You've defined a second aws provider block with alias = \"euwest\" pointing at eu-west-1. How do you tell the resource for the European bucket to use that specific provider configuration?", "prompt": {"question": "<p>You must deploy identical S3 buckets into both us-east-1 and eu-west-1 using a single AWS provider configuration block per region. You've defined a second aws provider block with alias = \"euwest\" pointing at eu-west-1. How do you tell the resource for the European bucket to use that specific provider configuration?</p>", "answers": ["<p>Add provider = aws.euwest inside the resource block</p>", "<p>Add region = \"eu-west-1\" directly inside the resource block</p>", "<p>Add alias = \"euwest\" inside the resource block</p>", "<p>Reference it as var.aws.euwest inside the resource block</p>"], "feedbacks": ["<p>To route a resource to a non-default (aliased) provider configuration, you set the meta-argument 'provider = &lt;PROVIDER TYPE&gt;.&lt;ALIAS&gt;' inside the resource block, e.g., provider = aws.euwest.</p>", "<p>Setting 'region' inside the resource block is not a valid meta-argument for provider selection; region configuration belongs in the provider block itself, not the resource.</p>", "<p>'alias' is only valid inside a provider block to define an alternate configuration — it cannot be set inside a resource block.</p>", "<p>Provider aliases are not variables and cannot be referenced with 'var.' syntax; they are referenced with the 'provider' meta-argument using dot notation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "Your configuration needs both the official HashiCorp AWS provider and the community-maintained GitHub provider published under the 'integrations' namespace on the Terraform Registry. Which required_providers block correctly declares both?", "prompt": {"question": "<p>Your configuration needs both the official HashiCorp AWS provider and the community-maintained GitHub provider published under the 'integrations' namespace on the Terraform Registry. Which required_providers block correctly declares both?</p>", "answers": ["<p>terraform { required_providers { aws = { source = \"hashicorp/aws\", version = \"~&gt; 5.0\" }, github = { source = \"hashicorp/github\", version = \"~&gt; 6.0\" } } }</p>", "<p>provider \"aws\" { source = \"hashicorp/aws\" } provider \"github\" { source = \"integrations/github\" }</p>", "<p>terraform { required_providers { aws = { source = \"hashicorp/aws\", version = \"~&gt; 5.0\" }, github = { source = \"integrations/github\", version = \"~&gt; 6.0\" } } }</p>", "<p>terraform { required_providers { aws = \"hashicorp/aws\", github = \"integrations/github\" } }</p>"], "feedbacks": ["<p>Using 'hashicorp/github' as the source is incorrect — HashiCorp does not publish an official GitHub provider under its own namespace; the real source address is 'integrations/github'.</p>", "<p>The 'source' argument is not valid inside a 'provider' configuration block — source/version constraints belong exclusively in the required_providers block inside the terraform block.</p>", "<p>The GitHub provider on the public registry is published under the 'integrations' namespace (source = \"integrations/github\"), not 'hashicorp'. This option correctly maps each local name to its true namespace/type using the required object syntax {source, version} inside the required_providers block.</p>", "<p>required_providers entries must be objects with 'source' and 'version' keys, not bare strings — this syntax is invalid HCL for this purpose.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A resource managed by Terraform was manually deleted from the cloud console outside of Terraform's workflow. Your configuration for that resource is unchanged. What will 'terraform plan' show the next time it is run?", "prompt": {"question": "<p>A resource managed by Terraform was manually deleted from the cloud console outside of Terraform's workflow. Your configuration for that resource is unchanged. What will 'terraform plan' show the next time it is run?</p>", "answers": ["<p>A plan to create the resource again, because state still records it as existing but a refresh shows it is now missing</p>", "<p>No changes, because the configuration hasn't changed since the last apply</p>", "<p>An error requiring you to manually run 'terraform state rm' before plan can proceed</p>", "<p>A prompt asking whether to run 'terraform import' before continuing</p>"], "feedbacks": ["<p>During plan, Terraform refreshes its view of real infrastructure. If the state file says the resource should exist but the provider reports it's gone, Terraform reconciles this by proposing to create it again to match the desired configuration — this is the core function of state as the source of truth for existing/expected resources.</p>", "<p>Terraform does not simply trust the old state blindly for 'no changes' — the refresh step during plan will detect the drift caused by the out-of-band deletion.</p>", "<p>Terraform does not error out or force a manual 'state rm' — it automatically handles the drift by planning a create action; state rm is a separate, optional workflow for a different purpose.</p>", "<p>Terraform does not prompt for 'terraform import' automatically — import is a manual command used to bring existing infrastructure under management, not something plan triggers on its own for missing resources.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly describes the relationship between the required_providers block and a provider configuration block in Terraform?", "prompt": {"question": "<p>Which statement correctly describes the relationship between the required_providers block and a provider configuration block in Terraform?</p>", "answers": ["<p>They serve the same purpose and are interchangeable; only one is needed per configuration</p>", "<p>required_providers defines which provider plugins and version constraints are needed, while a provider block supplies the runtime configuration (like credentials or region) for a specific provider</p>", "<p>required_providers configures credentials for the provider, while the provider block only pins the version</p>", "<p>A provider block is only needed when using provider aliases; required_providers alone is sufficient for a single default provider configuration</p>"], "feedbacks": ["<p>These two blocks serve distinct purposes and are not interchangeable — required_providers handles plugin sourcing/versioning, while provider blocks handle runtime configuration; most real-world configurations need both.</p>", "<p>required_providers (nested in the terraform block) declares which providers are needed by source address and version constraint, letting Terraform know what to download during init. Separately, one or more provider blocks configure how Terraform should actually talk to that provider's API (region, credentials, endpoints, aliases).</p>", "<p>This reverses their roles — required_providers never configures credentials; that is the provider block's job. required_providers only specifies source and version constraints.</p>", "<p>A default provider configuration is still needed even without aliases; Terraform requires a provider block to configure things like region/credentials even for a single, non-aliased provider.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A `terraform plan` shows: `-/+ aws_instance.web must be replaced` because the `ami` argument changed, and `ami` is a ForceNew attribute. Nothing else in the configuration changed. The team wants to apply only this replacement, without Terraform evaluating or touching any other resource in the state, and without editing any .tf files. Which command should they run?", "prompt": {"question": "<p>A `terraform plan` shows: `-/+ aws_instance.web must be replaced` because the `ami` argument changed, and `ami` is a ForceNew attribute. Nothing else in the configuration changed. The team wants to apply only this replacement, without Terraform evaluating or touching any other resource in the state, and without editing any .tf files. Which command should they run?</p>", "answers": ["<p>terraform taint aws_instance.web &amp;&amp; terraform apply</p>", "<p>terraform apply -target=\"aws_instance.web\"</p>", "<p>terraform apply -replace=\"aws_instance.web\"</p>", "<p>terraform destroy -target=\"aws_instance.web\" &amp;&amp; terraform apply</p>"], "feedbacks": ["<p>terraform taint marks a resource for replacement on the next plan but doesn't limit scope — apply would still evaluate the entire configuration, not just aws_instance.web (and taint is deprecated in favor of -replace).</p>", "<p>-target restricts the plan/apply operation's scope to the named resource (and its dependencies), so Terraform only evaluates and applies that resource, ignoring the rest of the configuration and state — exactly what's required here since the replacement is already detected from the config diff.</p>", "<p>-replace forces Terraform to treat a resource as needing replacement even if the config wouldn't otherwise trigger one, but it still generates a plan across the full configuration — it doesn't restrict evaluation scope, it forces an action.</p>", "<p>Running destroy then apply separately is destructive, doesn't guarantee a clean recreate in one pass, and unnecessarily removes the resource from state/infrastructure before recreating it — riskier than a scoped apply.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An engineer wants to preview exactly what resources and attributes would be removed if `terraform destroy` were run — without actually deleting any infrastructure. Which command produces this preview?", "prompt": {"question": "<p>An engineer wants to preview exactly what resources and attributes would be removed if `terraform destroy` were run — without actually deleting any infrastructure. Which command produces this preview?</p>", "answers": ["<p>terraform plan -destroy</p>", "<p>terraform destroy -dry-run</p>", "<p>terraform validate -destroy</p>", "<p>terraform show -destroy</p>"], "feedbacks": ["<p>terraform plan -destroy generates a speculative destroy plan, showing every resource that would be removed, without modifying real infrastructure or requiring confirmation.</p>", "<p>-dry-run is not a valid Terraform CLI flag; it doesn't exist on `terraform destroy`.</p>", "<p>terraform validate only checks configuration syntax and internal consistency; it has no -destroy flag and doesn't produce an execution plan.</p>", "<p>terraform show displays a previously saved plan or the current state file; it has no -destroy flag and cannot generate a new destroy plan on its own.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "When you run `terraform apply` directly (without passing a previously saved plan file), what does Terraform do immediately before generating and displaying the plan for your approval?", "prompt": {"question": "<p>When you run `terraform apply` directly (without passing a previously saved plan file), what does Terraform do immediately before generating and displaying the plan for your approval?</p>", "answers": ["<p>It automatically runs terraform init to update provider plugins to their latest versions</p>", "<p>It permanently locks the state file until a human manually releases the lock</p>", "<p>It performs a refresh of the managed resources to reconcile the in-memory state with real infrastructure before computing the diff</p>", "<p>It skips any state reconciliation and compares only the last-applied state to the configuration</p>"], "feedbacks": ["<p>Terraform never auto-runs init during apply; if providers/modules aren't initialized, apply fails and instructs you to run init manually.</p>", "<p>State locking during apply is temporary and automatically released when the operation completes or fails — it is not a manual, permanent lock.</p>", "<p>By default, terraform apply (like terraform plan) refreshes the state of managed resources against real infrastructure first (unless -refresh=false is passed), ensuring the plan is computed against current real-world values.</p>", "<p>Skipping refresh is not the default behavior; refresh happens automatically unless explicitly disabled with -refresh=false.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A CI/CD pipeline needs a full, machine-readable JSON representation of a Terraform plan (for feeding into a policy-as-code tool like OPA) rather than just log output. Which command sequence is the correct, documented way to produce this?", "prompt": {"question": "<p>A CI/CD pipeline needs a full, machine-readable JSON representation of a Terraform plan (for feeding into a policy-as-code tool like OPA) rather than just log output. Which command sequence is the correct, documented way to produce this?</p>", "answers": ["<p>terraform plan -json &gt; plan.json</p>", "<p>terraform plan --format=json &gt; plan.json</p>", "<p>terraform plan -out=tfplan &amp;&amp; terraform show -json tfplan &gt; plan.json</p>", "<p>terraform state show -json &gt; plan.json</p>"], "feedbacks": ["<p>terraform plan -json outputs line-delimited JSON log messages of the plan operation, not a structured, complete plan representation suitable for policy evaluation.</p>", "<p>--format=json is not a valid flag for terraform plan; the CLI doesn't support this syntax.</p>", "<p>The documented pattern for policy-as-code integration is to save a binary plan file with -out, then convert it to a full JSON plan representation using terraform show -json &lt;planfile&gt;, which HashiCorp's policy tooling (like Sentinel/OPA integrations) is built to consume.</p>", "<p>terraform state show displays a single resource's attributes from the current state file — it has no relationship to plan output or a -json plan format.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An engineer wants to generate a visual representation (consumable by Graphviz) of the dependency order in which Terraform will create, update, or destroy resources, without applying any changes. Which command should they use?", "prompt": {"question": "<p>An engineer wants to generate a visual representation (consumable by Graphviz) of the dependency order in which Terraform will create, update, or destroy resources, without applying any changes. Which command should they use?</p>", "answers": ["<p>terraform graph</p>", "<p>terraform state graph</p>", "<p>terraform plan -graph</p>", "<p>terraform validate -graph</p>"], "feedbacks": ["<p>terraform graph outputs the resource dependency graph in DOT format, which can be piped into Graphviz (e.g., `terraform graph | dot -Tsvg &gt; graph.svg`) to visualize the order of operations Terraform will follow.</p>", "<p>terraform state has no 'graph' subcommand; state subcommands (list, show, mv, rm, pull, push) manage state entries, not visualize dependencies.</p>", "<p>-graph is not a valid flag on terraform plan; plan only produces textual diff output for review.</p>", "<p>terraform validate only checks configuration correctness; it has no -graph flag and produces no dependency visualization.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An engineer runs `terraform plan -out=tfplan`. Before they run `terraform apply tfplan`, a teammate applies an unrelated change directly through the cloud console, altering the real-world state of a resource referenced in that saved plan. What happens when the engineer then runs `terraform apply tfplan`?", "prompt": {"question": "<p>An engineer runs `terraform plan -out=tfplan`. Before they run `terraform apply tfplan`, a teammate applies an unrelated change directly through the cloud console, altering the real-world state of a resource referenced in that saved plan. What happens when the engineer then runs `terraform apply tfplan`?</p>", "answers": ["<p>Terraform applies the saved plan unconditionally, since a saved plan file bypasses all state checks</p>", "<p>Terraform apply fails with an error indicating the saved plan is stale, and a new plan must be generated</p>", "<p>Terraform silently merges the console change into the plan and applies both sets of changes together</p>", "<p>Terraform prompts interactively, asking whether to proceed with the outdated plan or regenerate it</p>"], "feedbacks": ["<p>Saved plans are not applied blindly — Terraform explicitly checks that the state hasn't diverged since the plan was created, precisely to prevent unsafe, unconditional application.</p>", "<p>A saved plan file is tied to the specific state snapshot it was generated against. If the real state changes before the plan is applied, Terraform detects the mismatch and errors out (commonly surfaced as a stale-plan error), forcing the user to regenerate the plan against current state rather than risk applying an outdated diff.</p>", "<p>Terraform never silently merges out-of-band changes into a saved plan; it has no mechanism to reconcile drift mid-apply — it only detects staleness and refuses to proceed.</p>", "<p>Applying a saved plan file is non-interactive by design (no approval prompt is shown, since approval already happened at plan time) — Terraform either applies it or errors out; it does not pause for interactive confirmation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A Terraform configuration manages an EC2 instance. After changing the `ami` argument, `terraform plan` shows:\n\n  # aws_instance.web must be replaced\n  -/+ resource \"aws_instance\" \"web\" {\n      ~ ami = \"ami-0123\" -> \"ami-0456\" # forces replacement\n  }\n\nThe team needs the new instance to be created and pass health checks BEFORE the old instance is destroyed, to avoid downtime. Which approach BEST achieves this using the standard Terraform workflow?", "prompt": {"question": "<p>A Terraform configuration manages an EC2 instance. After changing the `ami` argument, `terraform plan` shows:\n\n  # aws_instance.web must be replaced\n  -/+ resource \"aws_instance\" \"web\" {\n      ~ ami = \"ami-0123\" -&gt; \"ami-0456\" # forces replacement\n  }\n\nThe team needs the new instance to be created and pass health checks BEFORE the old instance is destroyed, to avoid downtime. Which approach BEST achieves this using the standard Terraform workflow?</p>", "answers": ["<p>Run `terraform apply -auto-approve` immediately so the replacement happens as fast as possible</p>", "<p>Run `terraform taint aws_instance.web` before running plan, then apply as usual</p>", "<p>Add a `lifecycle { create_before_destroy = true }` block to the resource, then run `terraform plan` and `terraform apply`</p>", "<p>Run `terraform destroy -target=aws_instance.web` followed by `terraform apply` to recreate it</p>"], "feedbacks": ["<p>Auto-approving skips plan review but does not change the destroy-then-create order; the exam tests that -auto-approve only removes the interactive confirmation, not resource ordering.</p>", "<p>`terraform taint` forces a resource to be destroyed and recreated on the next apply, but it still follows the default destroy-before-create order unless create_before_destroy is set — it does not solve the downtime problem.</p>", "<p>The `create_before_destroy` lifecycle meta-argument changes the default replacement order: Terraform will provision the new resource first and only destroy the old one after the new one successfully exists, which the updated plan output will reflect. This is the correct workflow-level mechanism for controlling replacement order without downtime.</p>", "<p>Manually destroying the target first guarantees downtime since the old resource is removed before the new one is created — the opposite of the desired outcome, and `-target` usage like this is also discouraged outside of exceptional cases.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A module declares:\n\nvariable \"instances\" {\n  type = list(object({\n    name = string\n    size = string\n  }))\n}\n\nThe team wants exactly one aws_instance resource created per list entry, addressable in state by the instance's `name` value (so reordering the list doesn't force replacements). Which for_each expression on the resource block satisfies this?", "prompt": {"question": "<p>A module declares:\n\nvariable \"instances\" {\n  type = list(object({\n    name = string\n    size = string\n  }))\n}\n\nThe team wants exactly one aws_instance resource created per list entry, addressable in state by the instance's `name` value (so reordering the list doesn't force replacements). Which for_each expression on the resource block satisfies this?</p>", "answers": ["<p>for_each = var.instances</p>", "<p>for_each = { for i in var.instances : i.name =&gt; i }</p>", "<p>for_each = toset(var.instances)</p>", "<p>for_each = var.instances[*].name</p>"], "feedbacks": ["<p>A raw list(object) is not a valid for_each argument type — Terraform requires a map or set, so this fails validation.</p>", "<p>for_each requires a map or a set of strings. Converting the list of objects into a map keyed by `name` gives Terraform a stable key so reordering the source list doesn't cause resources to be destroyed/recreated, and each.value still exposes the full object for other attributes.</p>", "<p>toset() cannot be applied to a list of complex objects the way it can to a list of strings for this purpose, and even if it were accepted, each.key would be the whole object rather than a stable name, defeating the goal.</p>", "<p>This produces a list of strings (names only), losing the `size` attribute and still not satisfying for_each's map/set requirement without further conversion.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An aws_security_group resource must generate a variable number of ingress rules from a list variable `var.ingress_rules`, each containing `port` and `cidr` fields. Which construct correctly generates these nested blocks?", "prompt": {"question": "<p>An aws_security_group resource must generate a variable number of ingress rules from a list variable `var.ingress_rules`, each containing `port` and `cidr` fields. Which construct correctly generates these nested blocks?</p>", "answers": ["<p>ingress = [for r in var.ingress_rules : { from_port = r.port, to_port = r.port, cidr_blocks = [r.cidr] }]</p>", "<p>dynamic \"ingress\" {\n  for_each = var.ingress_rules\n  content {\n    from_port   = ingress.value.port\n    to_port     = ingress.value.port\n    cidr_blocks = [ingress.value.cidr]\n  }\n}</p>", "<p>count = length(var.ingress_rules)</p>", "<p>dynamic \"ingress\" {\n  for_each = var.ingress_rules\n  content {\n    from_port   = each.value.port\n    to_port     = each.value.port\n    cidr_blocks = [each.value.cidr]\n  }\n}</p>"], "feedbacks": ["<p>Nested blocks like ingress cannot be produced with a plain 'for' expression assigned to an argument — ingress is a block, not an argument, so this syntax is invalid.</p>", "<p>count only controls how many times the entire resource is created, not how many nested ingress blocks appear inside a single resource instance.</p>", "<p>This option incorrectly references `each.value` — the default iterator name inside a dynamic block matches the block's label (`ingress`), not `each`, unless overridden with an `iterator` argument.</p>", "<p>A dynamic block is required to generate a variable number of nested configuration blocks (like ingress) from a collection. Inside the content block, the iterator variable defaults to the block's label name — here 'ingress' — so `each.value` is wrong; the correct reference should be `ingress.value`. Wait — actually the correct answer generates the block using `dynamic` with the proper iterator; among the given choices, only the dynamic block options are structurally valid, and this one correctly matches Terraform's default iterator naming convention semantics tested on the exam (the block label is the default iterator name).</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Which Terraform block type does NOT support a `postcondition` (while supporting `precondition`)?", "prompt": {"question": "<p>Which Terraform block type does NOT support a `postcondition` (while supporting `precondition`)?</p>", "answers": ["<p>resource lifecycle block</p>", "<p>data source lifecycle block</p>", "<p>output value block</p>", "<p>check block</p>"], "feedbacks": ["<p>Resource lifecycle blocks support both precondition (checked before apply) and postcondition (checked after the resource is created/updated).</p>", "<p>Data source lifecycle blocks also support both precondition and postcondition, commonly used to validate that a queried data source returned expected results.</p>", "<p>Output value blocks support only `precondition` blocks, which validate the output's value before it is emitted. Output blocks cannot contain `postcondition` blocks; that capability is reserved for resource and data source lifecycle blocks and check blocks.</p>", "<p>Check blocks are specifically designed to run arbitrary assertions and support both precondition and postcondition-style logic inside their assert blocks.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A variable must only accept strings matching the pattern of a valid AWS instance type family, such as 't2.micro' or 'm5.large', without Terraform crashing on a malformed value during validation. Which validation condition is correct?", "prompt": {"question": "<p>A variable must only accept strings matching the pattern of a valid AWS instance type family, such as 't2.micro' or 'm5.large', without Terraform crashing on a malformed value during validation. Which validation condition is correct?</p>", "answers": ["<p>condition = can(regex(\"^[a-z][0-9]+\\\\.[a-z]+$\", var.instance_type))</p>", "<p>condition = regex(\"^[a-z][0-9]+\\\\.[a-z]+$\", var.instance_type) == var.instance_type</p>", "<p>condition = var.instance_type == regex(\"^[a-z][0-9]+\\\\.[a-z]+$\")</p>", "<p>condition = contains(regex(\"^[a-z][0-9]+\\\\.[a-z]+$\", var.instance_type), var.instance_type)</p>"], "feedbacks": ["<p>regex() raises an error if the pattern doesn't match, which would crash validation entirely rather than producing a clean false result. Wrapping it in can() catches that error and converts it into a boolean, making it safe to use as a validation condition that returns false on non-matching input instead of erroring out.</p>", "<p>Comparing the raw regex() result to the input string is invalid because regex() would throw an error on non-matching input before any comparison happens, causing plan/apply to fail ungracefully rather than surfacing the custom validation error message.</p>", "<p>This has the same flaw — regex() errors out on non-match rather than returning a comparable value, so the condition itself would crash instead of evaluating to false.</p>", "<p>contains() expects a collection as its first argument, but regex() returns a string (or errors), so this is a type mismatch and also inherits the same crash-on-non-match problem.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A module output must return a value derived from a resource attribute marked sensitive by the provider, but the consuming root module needs to use that value as a map key elsewhere, which Terraform disallows for sensitive values. What should be done in the module to make this usable, while acknowledging the security tradeoff?", "prompt": {"question": "<p>A module output must return a value derived from a resource attribute marked sensitive by the provider, but the consuming root module needs to use that value as a map key elsewhere, which Terraform disallows for sensitive values. What should be done in the module to make this usable, while acknowledging the security tradeoff?</p>", "answers": ["<p>Add sensitive = true to the output block</p>", "<p>Use jsonencode() on the value before returning it</p>", "<p>Reference the value through a local instead of directly in the output</p>", "<p>Wrap the value using nonsensitive() in the output's expression</p>"], "feedbacks": ["<p>Setting sensitive = true on the output would mark the output itself as sensitive but does nothing to remove the underlying sensitivity that's blocking its use as a map key — the restriction persists.</p>", "<p>jsonencode() does not remove sensitivity; a sensitive value passed through jsonencode() still propagates its sensitive marking to the result, so the map-key restriction remains.</p>", "<p>Assigning the value to a local does not strip sensitivity — locals derived from sensitive values are automatically treated as sensitive too, so the underlying problem is unchanged.</p>", "<p>nonsensitive() explicitly strips the sensitive marking from a value, which is the only built-in mechanism for deliberately downgrading a value so it can be used in contexts (like map keys) that reject sensitive values. This should be done with care since it removes Terraform's redaction protections for that value going forward.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A resource block references an output of a module only inside a `provisioner \"local-exec\"` command string that Terraform cannot statically parse for dependency purposes (e.g., embedded in a script argument built via templatefile()). The resource must still be created only after that module's resources are fully provisioned. What should be added?", "prompt": {"question": "<p>A resource block references an output of a module only inside a `provisioner \"local-exec\"` command string that Terraform cannot statically parse for dependency purposes (e.g., embedded in a script argument built via templatefile()). The resource must still be created only after that module's resources are fully provisioned. What should be added?</p>", "answers": ["<p>Nothing — Terraform automatically infers the dependency from any string interpolation</p>", "<p>A local value that maps the module output 1:1, replacing the need for depends_on</p>", "<p>depends_on = [module.network] added to the resource block</p>", "<p>lifecycle { create_before_destroy = true } on the resource</p>"], "feedbacks": ["<p>Terraform's automatic dependency inference relies on direct attribute references appearing in the resource's arguments; when a reference is deeply embedded in a way that obscures it from the graph builder, implicit detection can be unreliable, so this can't be assumed safe.</p>", "<p>Introducing a local value doesn't guarantee correct ordering by itself unless that local is directly referenced in the resource's arguments in a way Terraform can trace — the scenario states the reference is only inside a provisioner string, so this doesn't solve the ordering problem.</p>", "<p>When a reference is buried inside constructs Terraform can't reliably parse for its dependency graph (such as inside a rendered script string via templatefile), implicit dependency detection may not be sufficient. Adding depends_on = [module.network] explicitly forces the ordering, ensuring the module's resources are fully provisioned first regardless of how the reference is used internally.</p>", "<p>create_before_destroy only affects replacement behavior during updates (creating a new resource before destroying the old one) — it has no effect on ordering relative to a separate module's resources.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A module declares `variable \"db_password\" { type = string sensitive = true }` and includes `output \"password_out\" { value = var.db_password }` without a `sensitive` argument on the output. What happens when a caller runs `terraform plan` against the root module that consumes this module?", "prompt": {"question": "<p>A module declares `variable \"db_password\" { type = string sensitive = true }` and includes `output \"password_out\" { value = var.db_password }` without a `sensitive` argument on the output. What happens when a caller runs `terraform plan` against the root module that consumes this module?</p>", "answers": ["<p>Terraform throws an error at plan time stating the output value is derived from a sensitive value and requires the output block to set `sensitive = true`</p>", "<p>Terraform automatically infers the output is sensitive and redacts it in the CLI output with no configuration change needed</p>", "<p>Terraform plan succeeds and prints the plaintext password to the console because outputs do not inherit sensitivity from variables</p>", "<p>Terraform stores the value in plaintext in state but hides it from the CLI, requiring no changes to the output block</p>"], "feedbacks": ["<p>Terraform propagates sensitivity: if a value used in an output is derived from a variable, resource attribute, or other value marked sensitive, Terraform requires the output block itself to declare `sensitive = true`. Without it, `terraform plan`/`apply` fails with an error like 'Output refers to sensitive values' until the output is explicitly marked sensitive.</p>", "<p>Terraform does not silently infer and add sensitivity to output blocks on your behalf — you must explicitly add `sensitive = true` to the output definition</p>", "<p>This is false; Terraform enforces sensitivity propagation and will error rather than print the plaintext value in this case</p>", "<p>State storage of sensitive values is unaffected by console redaction rules, but more importantly this ignores that Terraform errors out during plan rather than silently succeeding</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team must source a reusable module from a private Git repository over SSH. The module is stored in the subdirectory 'modules/network' of that repository, and the team must pin their configuration to the tag v2.3.1. Which source configuration correctly achieves this?", "prompt": {"question": "<p>A platform team must source a reusable module from a private Git repository over SSH. The module is stored in the subdirectory 'modules/network' of that repository, and the team must pin their configuration to the tag v2.3.1. Which source configuration correctly achieves this?</p>", "answers": ["<p>source = \"git::ssh://git@github.com/org/repo.git/modules/network?ref=v2.3.1\"</p>", "<p>source = \"git::ssh://git@github.com/org/repo.git//modules/network\"\nversion = \"v2.3.1\"</p>", "<p>source = \"github.com/org/repo//modules/network?ref=v2.3.1\"</p>", "<p>source = \"git::ssh://git@github.com/org/repo.git//modules/network?ref=v2.3.1\"</p>"], "feedbacks": ["<p>A single slash before 'modules/network' is interpreted as part of the repository path itself (e.g., 'repo.git/modules/network'), not as a subdirectory selector, so Terraform will fail to locate the repo.</p>", "<p>The 'version' argument is only valid for modules sourced from a Terraform module registry; it is silently ignored (or causes an error) for Git-based sources — version pinning for Git must use the 'ref' query parameter instead.</p>", "<p>Omitting the git:: prefix and ssh:// protocol causes go-getter to treat this as a generic GitHub HTTPS shorthand, which cannot authenticate over SSH and will fail against a private repository.</p>", "<p>Go-getter's Git subdirectory syntax requires a double slash ('//') to separate the repository URL from the in-repo path, and the ref query parameter selects the tag/branch/commit. Using ssh:// with the git:: prefix ensures the private repo is cloned over SSH.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A module named 'vpc' is published to the public Terraform Registry under the namespace 'acme' for the 'aws' provider. Which module source string correctly references this module using registry shorthand?", "prompt": {"question": "<p>A module named 'vpc' is published to the public Terraform Registry under the namespace 'acme' for the 'aws' provider. Which module source string correctly references this module using registry shorthand?</p>", "answers": ["<p>\"aws/vpc/acme\"</p>", "<p>\"terraform-aws-modules/acme-vpc\"</p>", "<p>\"acme/vpc/aws\"</p>", "<p>\"hashicorp/acme/vpc\"</p>"], "feedbacks": ["<p>This reverses the required order — the registry parses this as namespace=aws, name=vpc, provider=acme, which does not match the actual published module.</p>", "<p>This combines the namespace and module name into a single segment and omits the provider entirely; it is not a valid three-part registry address and will fail to resolve.</p>", "<p>The public registry shorthand format is &lt;NAMESPACE&gt;/&lt;NAME&gt;/&lt;PROVIDER&gt;, so 'acme/vpc/aws' correctly maps namespace=acme, name=vpc, provider=aws, resolving to registry.terraform.io/modules/acme/vpc/aws.</p>", "<p>This looks like a registry address but places 'hashicorp' where the namespace belongs and omits the provider segment — it does not match the &lt;NAMESPACE&gt;/&lt;NAME&gt;/&lt;PROVIDER&gt; pattern needed to resolve the acme/vpc/aws module.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A configuration consumes a registry module and must automatically pick up bug-fix (patch) releases within the 3.4.x line, but must NOT upgrade to 3.5.0 or any later minor/major release. Which version constraint enforces this?", "prompt": {"question": "<p>A configuration consumes a registry module and must automatically pick up bug-fix (patch) releases within the 3.4.x line, but must NOT upgrade to 3.5.0 or any later minor/major release. Which version constraint enforces this?</p>", "answers": ["<p>version = \"~&gt; 3.4\"</p>", "<p>version = \"&gt;= 3.4.0, &lt; 3.4.9\"</p>", "<p>version = \"= 3.4.0\"</p>", "<p>version = \"~&gt; 3.4.0\"</p>"], "feedbacks": ["<p>With '~&gt; 3.4', the rightmost specified segment is the minor version, so this constraint allows 3.5.x, 3.6.x, and any 3.x release, which violates the requirement to stay within 3.4.x only.</p>", "<p>This arbitrarily caps patch versions at 3.4.9, which is not idiomatic version pinning and would block legitimate 3.4.9+ patch releases that the requirement wants to allow.</p>", "<p>An exact match constraint locks the module to precisely 3.4.0 and blocks all patch updates, failing the requirement to automatically pick up bug-fix releases.</p>", "<p>The pessimistic constraint operator '~&gt;' allows increments only in the rightmost specified version segment. With '~&gt; 3.4.0', the rightmost segment is the patch number, so Terraform allows 3.4.1, 3.4.2, etc., but rejects 3.5.0 and above.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "In the root module, 'module \"network\"' produces an output named 'subnet_ids'. The 'module \"compute\"' block requires an input variable called 'subnet_id_list' populated with that value. Which line correctly wires this inside the compute module block?", "prompt": {"question": "<p>In the root module, 'module \"network\"' produces an output named 'subnet_ids'. The 'module \"compute\"' block requires an input variable called 'subnet_id_list' populated with that value. Which line correctly wires this inside the compute module block?</p>", "answers": ["<p>subnet_id_list = network.output.subnet_ids</p>", "<p>subnet_id_list = var.network.subnet_ids</p>", "<p>subnet_id_list = module.network.subnet_ids</p>", "<p>subnet_id_list = data.network.subnet_ids</p>"], "feedbacks": ["<p>There is no 'network.output.x' expression syntax in Terraform's HCL — module outputs must always be referenced through the 'module.' prefix, not through a bare module name or an 'output' object.</p>", "<p>The 'var.' prefix refers to input variables declared in the current module's own variables.tf, not to outputs of a sibling module; this would fail because no variable named 'network' is defined.</p>", "<p>Module outputs are referenced from a calling module using the syntax module.&lt;MODULE_NAME&gt;.&lt;OUTPUT_NAME&gt;, so module.network.subnet_ids correctly retrieves the subnet_ids output from the network module instance.</p>", "<p>The 'data.' prefix is reserved for referencing data source blocks (e.g., data.aws_ami.example), not module outputs; using it here to access another module's output is invalid syntax.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A root module declares:\n\nmodule \"app\" {\n  for_each = toset([\"dev\", \"staging\", \"prod\"])\n  source   = \"./modules/app\"\n  env_name = each.key\n}\n\nWhich expression correctly references the 'url' output of the 'prod' instance elsewhere in the same root module?", "prompt": {"question": "<p>A root module declares:\n\nmodule \"app\" {\n  for_each = toset([\"dev\", \"staging\", \"prod\"])\n  source   = \"./modules/app\"\n  env_name = each.key\n}\n\nWhich expression correctly references the 'url' output of the 'prod' instance elsewhere in the same root module?</p>", "answers": ["<p>module.app[\"prod\"].url</p>", "<p>module.app.prod.url</p>", "<p>module.app[2].url</p>", "<p>module.app.url[\"prod\"]</p>"], "feedbacks": ["<p>When a module block uses for_each, Terraform creates a map of module instances keyed by each.key, and each instance's outputs must be accessed with bracket-index syntax: module.&lt;NAME&gt;[\"&lt;KEY&gt;\"].&lt;OUTPUT&gt;. Here that resolves to module.app[\"prod\"].url.</p>", "<p>Dot-notation for the instance key (module.app.prod) is not valid Terraform syntax for indexing a for_each-created module map — only bracket-index syntax with the key is supported.</p>", "<p>For_each with a set produces a map keyed by string values (dev, staging, prod), not sequential numeric indices, so numeric indexing like module.app[2] is invalid; numeric indexing only applies to modules using 'count'.</p>", "<p>This places the index in the wrong position — the instance key must index the module name itself (module.app[\"prod\"]), not the output attribute, so this expression is syntactically invalid.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A team enables state locking for an S3 backend but wants to avoid provisioning a separate DynamoDB table. They are running Terraform 1.10. Which backend configuration argument enables native S3-based locking using conditional writes instead of DynamoDB?", "prompt": {"question": "<p>A team enables state locking for an S3 backend but wants to avoid provisioning a separate DynamoDB table. They are running Terraform 1.10. Which backend configuration argument enables native S3-based locking using conditional writes instead of DynamoDB?</p>", "answers": ["<p>dynamodb_table = \"terraform-locks\"</p>", "<p>lock_table = \"terraform-locks\"</p>", "<p>enable_native_lock = true</p>", "<p>use_lockfile = true</p>"], "feedbacks": ["<p>dynamodb_table is the legacy locking mechanism requiring a separate DynamoDB table with a LockID key — the opposite of what the scenario asks for.</p>", "<p>lock_table is not a valid s3 backend argument; it does not exist in the schema.</p>", "<p>enable_native_lock is a fabricated argument name; the real argument is use_lockfile.</p>", "<p>Terraform 1.10 introduced native S3 state locking via S3's conditional write (If-None-Match) support. Setting use_lockfile = true in the s3 backend block enables this without requiring a DynamoDB table.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A resource attribute containing a database password is marked sensitive = true in an output block, but a teammate later opens the raw state file and finds the plaintext value. What is the correct explanation and remediation?", "prompt": {"question": "<p>A resource attribute containing a database password is marked sensitive = true in an output block, but a teammate later opens the raw state file and finds the plaintext value. What is the correct explanation and remediation?</p>", "answers": ["<p>Marking a value sensitive encrypts it inside the state file; the teammate must have used an outdated Terraform version</p>", "<p>Run terraform state rm on the resource immediately after apply to purge the value from state</p>", "<p>The sensitive flag only suppresses the value from CLI output and the UI — it does not encrypt state; store state in a backend with encryption at rest and restrict access via IAM policy</p>", "<p>Replace the resource with a null_resource wrapper so the attribute is never written to state</p>"], "feedbacks": ["<p>sensitive = true has no effect on how the value is stored in state; there is no version where it triggers encryption of the state file contents.</p>", "<p>Removing the resource from state with state rm stops Terraform from tracking it but does not delete or protect the sensitive value already persisted in the backend's state history/versions.</p>", "<p>The sensitive attribute only redacts values from plan/apply CLI output and the HCP Terraform UI. The state file itself always stores the real value in plaintext (in the JSON structure), so protecting it requires backend-level encryption at rest plus strict IAM/access control on who can read the state.</p>", "<p>Wrapping in a null_resource does not prevent Terraform from recording resource attribute values in state; it doesn't address the core exposure.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A team is renaming a resource across a module used by 12 CI-driven environments (workspaces). They need the change to apply consistently and automatically the next time each environment's pipeline runs terraform plan, without any engineer needing to run a manual command against every workspace. Which approach BEST satisfies this requirement?", "prompt": {"question": "<p>A team is renaming a resource across a module used by 12 CI-driven environments (workspaces). They need the change to apply consistently and automatically the next time each environment's pipeline runs terraform plan, without any engineer needing to run a manual command against every workspace. Which approach BEST satisfies this requirement?</p>", "answers": ["<p>Have each environment's engineer run terraform state mv manually before the next apply</p>", "<p>Add a moved block to the configuration mapping the old address to the new one</p>", "<p>Run terraform import against each workspace with the new resource address</p>", "<p>Delete the resource from state with terraform state rm and let Terraform recreate it under the new name</p>"], "feedbacks": ["<p>terraform state mv is a one-time, manual, per-workspace command; it must be re-run individually against all 12 workspaces and produces no artifact tracked in version control.</p>", "<p>The moved block is committed directly to the configuration, so it is version-controlled and automatically applied by Terraform's plan/apply logic in every workspace and CI run — no manual per-environment command is required.</p>", "<p>terraform import is used to bring existing infrastructure into state that isn't tracked yet, not to rename an already-tracked resource address.</p>", "<p>Removing and letting Terraform recreate the resource would destroy and rebuild real infrastructure, causing downtime instead of a safe in-place rename.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A resource block is deleted from configuration, but the team wants Terraform to stop managing the corresponding real-world infrastructure WITHOUT destroying it, and wants this decision version-controlled so every teammate and CI pipeline applies it consistently. Which approach BEST meets these requirements?", "prompt": {"question": "<p>A resource block is deleted from configuration, but the team wants Terraform to stop managing the corresponding real-world infrastructure WITHOUT destroying it, and wants this decision version-controlled so every teammate and CI pipeline applies it consistently. Which approach BEST meets these requirements?</p>", "answers": ["<p>Have each engineer run terraform state rm on their own machine before applying</p>", "<p>Add a moved block pointing the old address to a new address that doesn't exist</p>", "<p>Add a removed block referencing the resource with a lifecycle { destroy = false } setting</p>", "<p>Run terraform apply with the -refresh-only flag to detach the resource</p>"], "feedbacks": ["<p>terraform state rm is a manual, local, one-off command that is not tracked in version control and must be repeated by every teammate and pipeline separately, risking inconsistency.</p>", "<p>A moved block is for renaming/relocating an existing tracked resource address, not for dropping management of a resource entirely; pointing it to a nonexistent address is not valid usage.</p>", "<p>The removed block (introduced in Terraform 1.7) is written directly in configuration and version-controlled. Setting lifecycle { destroy = false } tells Terraform to stop managing the resource and drop it from state without issuing a destroy call against the real infrastructure — and it's consistently applied by every plan/apply, including CI.</p>", "<p>-refresh-only only updates state to match real infrastructure and reports drift; it does not remove resources from state or stop management.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "What does running terraform plan -refresh-only actually produce?", "prompt": {"question": "<p>What does running terraform plan -refresh-only actually produce?</p>", "answers": ["<p>A proposed set of configuration changes to bring real infrastructure into alignment with the current .tf files</p>", "<p>A report showing differences between the current state file and the real infrastructure, without proposing any configuration-driven changes</p>", "<p>An automatic update of the state file to match real infrastructure, applied immediately without confirmation</p>", "<p>A refreshed list of available provider plugin versions compatible with the configuration</p>"], "feedbacks": ["<p>That describes a normal terraform plan, which compares desired configuration to state and proposes resource changes — the opposite of refresh-only's state-vs-reality comparison.</p>", "<p>-refresh-only mode queries real infrastructure and compares it to the state file, surfacing drift (out-of-band changes) as a plan of proposed STATE updates only — it never proposes changes derived from the .tf configuration.</p>", "<p>terraform plan never applies changes on its own regardless of mode; applying the refreshed state requires a separate terraform apply -refresh-only step with explicit approval.</p>", "<p>Refresh-only has nothing to do with provider plugin version resolution; that concerns terraform init and the provider lock file.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A team runs terraform import aws_instance.web i-0abc123456 against a configuration that has no aws_instance.web resource block defined anywhere in the .tf files. What is the result?", "prompt": {"question": "<p>A team runs terraform import aws_instance.web i-0abc123456 against a configuration that has no aws_instance.web resource block defined anywhere in the .tf files. What is the result?</p>", "answers": ["<p>Terraform automatically generates a matching HCL resource block for aws_instance.web based on the imported attributes</p>", "<p>Terraform errors out, stating the resource address does not exist in the configuration, because the classic import command requires a pre-existing resource block</p>", "<p>The import succeeds, and the next terraform plan will show the resource must be destroyed since no config matches it</p>", "<p>The import silently fails and the state file remains completely unchanged with no error message</p>"], "feedbacks": ["<p>Automatic config generation is a feature of the import block (with -generate-config-out), introduced separately from and later than the classic terraform import CLI command being described here.</p>", "<p>The classic terraform import CLI command only writes to the state file — it requires a resource block with that exact address to already exist in configuration, and errors immediately if it does not find one. Automatic HCL generation is only available via the newer `import` configuration block with the -generate-config-out flag, not the legacy import command.</p>", "<p>Import never even reaches the state file in this scenario because it fails validation before writing anything, so no plan-to-destroy situation occurs.</p>", "<p>The command does not fail silently — it returns an explicit, descriptive error about the missing configuration and no state modification occurs.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team manages 40 HCP Terraform workspaces provisioning AWS resources for different application teams. Security requires that no long-lived AWS access keys be stored in HCP Terraform, and that each workspace can only assume the IAM role scoped to its own environment. Which HCP Terraform feature should they configure to meet this requirement?", "prompt": {"question": "<p>A platform team manages 40 HCP Terraform workspaces provisioning AWS resources for different application teams. Security requires that no long-lived AWS access keys be stored in HCP Terraform, and that each workspace can only assume the IAM role scoped to its own environment. Which HCP Terraform feature should they configure to meet this requirement?</p>", "answers": ["<p>Dynamic provider credentials using OIDC federation with per-workspace assigned IAM roles</p>", "<p>Variable sets applied at the organization level containing a shared AWS access key</p>", "<p>A Sentinel policy that blocks 'terraform apply' if any variable name contains the word 'secret'</p>", "<p>Run triggers that pass credentials from a central 'vault' workspace's state outputs</p>"], "feedbacks": ["<p>Dynamic provider credentials use OIDC federation so HCP Terraform requests short-lived, workspace-scoped cloud credentials at run time from the cloud provider's identity federation service, with no long-lived keys stored anywhere and each workspace mapped to its own IAM role via trust policy conditions.</p>", "<p>A shared org-level variable set with a static access key is still a long-lived credential and grants the same key to every workspace, violating both requirements.</p>", "<p>A Sentinel policy checking variable names doesn't detect or prevent actual key material and is a governance control, not a credentialing mechanism.</p>", "<p>Run triggers chain plan/apply runs between workspaces; they don't manage or scope cloud credentials, and exposing keys via state outputs is a security anti-pattern.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company wants a Sentinel enforcement level where a failing policy check permanently blocks 'terraform apply' for every run, with no way for any user, including organization owners, to override the failure at run time (the only way to allow the run is to edit or remove the policy itself). Which enforcement level satisfies this?", "prompt": {"question": "<p>A company wants a Sentinel enforcement level where a failing policy check permanently blocks 'terraform apply' for every run, with no way for any user, including organization owners, to override the failure at run time (the only way to allow the run is to edit or remove the policy itself). Which enforcement level satisfies this?</p>", "answers": ["<p>advisory</p>", "<p>hard-mandatory</p>", "<p>soft-mandatory</p>", "<p>admin-override</p>"], "feedbacks": ["<p>advisory policies only log failures and never block the run at all.</p>", "<p>hard-mandatory policies cannot be overridden by anyone during a run; a failing hard-mandatory check always halts the run, and the policy set itself must be changed to allow the apply.</p>", "<p>soft-mandatory policies block by default but can be overridden at run time by users who hold the 'manage policy overrides' permission, which violates the 'no one can override' requirement.</p>", "<p>'admin-override' is not a real Sentinel enforcement level in HCP Terraform; the only levels are advisory, soft-mandatory, and hard-mandatory.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization has 15 workspaces that all deploy into the same AWS account and need identical AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and a shared 'cost-center' Terraform variable. The platform team wants to manage these values in a single place and have updates automatically propagate to all 15 workspaces without editing each workspace individually. Which HCP Terraform feature should they use?", "prompt": {"question": "<p>An organization has 15 workspaces that all deploy into the same AWS account and need identical AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and a shared 'cost-center' Terraform variable. The platform team wants to manage these values in a single place and have updates automatically propagate to all 15 workspaces without editing each workspace individually. Which HCP Terraform feature should they use?</p>", "answers": ["<p>A shared Terraform module that hardcodes the variable values</p>", "<p>A variable set scoped to the relevant workspaces (or the entire organization)</p>", "<p>Workspace-level variables manually copied into each of the 15 workspaces</p>", "<p>A run trigger chaining all 15 workspaces together sequentially</p>"], "feedbacks": ["<p>Hardcoding credentials into a module bakes secrets into version-controlled code and requires re-publishing the module for any change, which is both insecure and unmaintainable.</p>", "<p>A variable set is defined once and attached to multiple workspaces (or the whole organization); updating the variable set propagates the change to every attached workspace automatically, which is exactly what's needed here.</p>", "<p>Copying workspace-level variables into each workspace requires 15 manual edits every time a value changes, defeating the goal of centralized management.</p>", "<p>Run triggers propagate run events (start a run when another workspace applies), not variable values, so they wouldn't distribute the shared credentials or variable at all.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Workspace 'network' provisions a shared VPC. Workspace 'app' deploys application infrastructure into that VPC and must automatically queue a new run whenever 'network' successfully applies changes. Which configuration should be added to workspace 'app' in HCP Terraform?", "prompt": {"question": "<p>Workspace 'network' provisions a shared VPC. Workspace 'app' deploys application infrastructure into that VPC and must automatically queue a new run whenever 'network' successfully applies changes. Which configuration should be added to workspace 'app' in HCP Terraform?</p>", "answers": ["<p>A run trigger in 'app' with 'network' set as the source workspace</p>", "<p>A Sentinel policy in 'app' that reads the remote state of 'network'</p>", "<p>A VCS webhook configured on the 'network' repository pointing to 'app'</p>", "<p>A matching workspace tag applied to both 'network' and 'app'</p>"], "feedbacks": ["<p>Run triggers are configured on the downstream (dependent) workspace and specify one or more upstream 'source workspaces'; whenever a source workspace applies successfully, HCP Terraform automatically queues a new run in the workspace with the trigger.</p>", "<p>Sentinel policies enforce governance rules on a plan/apply; they don't queue new runs in other workspaces based on remote state.</p>", "<p>VCS webhooks trigger runs based on repository commits, not based on another workspace's apply completing.</p>", "<p>Workspace tags are used for organizing/filtering workspaces in the UI and API and have no effect on triggering runs between workspaces.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An engineer enables health assessments (drift detection) on an HCP Terraform workspace, scheduled to run every 24 hours. What happens when a scheduled health assessment discovers that real infrastructure has drifted from the Terraform state?", "prompt": {"question": "<p>An engineer enables health assessments (drift detection) on an HCP Terraform workspace, scheduled to run every 24 hours. What happens when a scheduled health assessment discovers that real infrastructure has drifted from the Terraform state?</p>", "answers": ["<p>HCP Terraform automatically runs 'terraform apply' to reconcile the drift without requiring approval</p>", "<p>HCP Terraform removes the drifted resources from the state file to force recreation on the next apply</p>", "<p>HCP Terraform performs a refresh-only plan and reports the drifted resources in the workspace UI without applying any changes</p>", "<p>HCP Terraform locks the workspace and blocks all new runs until the drift is manually resolved</p>"], "feedbacks": ["<p>Drift detection is strictly read-only reporting; it never triggers an automatic apply, which would be dangerous without human review.</p>", "<p>Health assessments do not modify the state file at all; they only compare real infrastructure to the existing state and report differences.</p>", "<p>Health assessments run a refresh-only plan against the workspace on the configured schedule, surface any detected drift (and, for Terraform Enterprise/HCP Terraform, deferred/missing resources) in the workspace's health dashboard, and never apply changes automatically.</p>", "<p>Detected drift does not lock the workspace or prevent new runs; it's informational, and normal plan/apply runs can proceed as usual.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}], "expected": 44}, {"name": "Google PCA Practice Test 1", "cid": 7301139, "duration": 120, "pass_percent": 70, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A financial services company runs a critical PostgreSQL database and must meet an RPO of 15 minutes and an RTO of 1 hour in case of a regional outage. The operations team wants a fully managed solution with minimal operational overhead to configure and maintain. Which approach BEST meets these requirements?", "prompt": {"question": "<p>A financial services company runs a critical PostgreSQL database and must meet an RPO of 15 minutes and an RTO of 1 hour in case of a regional outage. The operations team wants a fully managed solution with minimal operational overhead to configure and maintain. Which approach BEST meets these requirements?</p>", "answers": ["<p>Run self-managed PostgreSQL on Compute Engine and take persistent disk snapshots every 4 hours for cross-region recovery</p>", "<p>Configure Cloud SQL automated backups only and restore from the latest backup in the event of a regional outage</p>", "<p>Export the database to Cloud Storage nightly and re-import it into a new Cloud SQL instance in another region during failover</p>", "<p>Use Cloud SQL for PostgreSQL with a cross-region read replica that can be promoted to a standalone primary during failover</p>"], "feedbacks": ["<p>4-hour snapshot intervals mean up to 4 hours of data loss, violating the 15-minute RPO, and also require self-managed failover, increasing operational overhead</p>", "<p>Automated backups alone typically restore to the last daily backup point, giving an RPO measured in hours or a full day, far exceeding the 15-minute requirement</p>", "<p>Nightly exports give an RPO of up to 24 hours and manual re-import adds significant time to RTO, failing both requirements</p>", "<p>Cloud SQL cross-region read replicas replicate continuously with very low lag, easily meeting a 15-minute RPO, and can be promoted to a standalone primary quickly to meet a 1-hour RTO, all while being fully managed by Google.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to connect its on-premises data center to its Google Cloud VPC with a dedicated 10 Gbps link, low and predictable latency, and a requirement that traffic never traverse the public internet. The company has the ability to co-locate equipment at a facility with direct access to Google's network. Which connectivity option should be selected?", "prompt": {"question": "<p>A company needs to connect its on-premises data center to its Google Cloud VPC with a dedicated 10 Gbps link, low and predictable latency, and a requirement that traffic never traverse the public internet. The company has the ability to co-locate equipment at a facility with direct access to Google's network. Which connectivity option should be selected?</p>", "answers": ["<p>HA VPN over the public internet</p>", "<p>Cloud NAT with static outbound IP addresses</p>", "<p>Dedicated Interconnect</p>", "<p>Partner Interconnect through a service provider</p>"], "feedbacks": ["<p>HA VPN encrypts traffic but the traffic still traverses the public internet, and per-tunnel throughput does not reliably match a dedicated 10 Gbps requirement</p>", "<p>Cloud NAT is used to allow instances without external IPs to make outbound connections to the internet; it has no role in on-premises hybrid connectivity</p>", "<p>Dedicated Interconnect provides a direct physical connection between the on-premises network and Google's network at a colocation facility, supporting 10 Gbps or 100 Gbps circuits with private, predictable-latency connectivity that never touches the public internet.</p>", "<p>Partner Interconnect is used when a direct physical presence at a Google colocation facility isn't available; since the company can co-locate directly, Dedicated Interconnect avoids an unnecessary intermediary provider</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a legacy Java monolith on VMware on-premises and must move it to Google Cloud within 3 months due to a data center contract expiration. Leadership wants to eventually modernize the application into microservices, but the immediate priority is meeting the deadline with minimal risk. Which migration approach should be used first?", "prompt": {"question": "<p>A company runs a legacy Java monolith on VMware on-premises and must move it to Google Cloud within 3 months due to a data center contract expiration. Leadership wants to eventually modernize the application into microservices, but the immediate priority is meeting the deadline with minimal risk. Which migration approach should be used first?</p>", "answers": ["<p>Rewrite the application from scratch using App Engine Standard before migrating</p>", "<p>Immediately re-architect the monolith into containerized microservices deployed on GKE</p>", "<p>Manually export VM disk images and recreate the instances using custom Deployment Manager templates</p>", "<p>Use Migrate to Virtual Machines to lift-and-shift the VMs to Compute Engine, then modernize incrementally afterward</p>"], "feedbacks": ["<p>Rewriting the application is a re-architecture effort that typically takes far longer than 3 months and introduces high risk of missing the deadline</p>", "<p>Re-architecting to GKE microservices immediately is the eventual goal but is too slow and risky to complete within the 3-month window</p>", "<p>Manually exporting and recreating VMs is time-consuming, error-prone, and does not leverage Google's purpose-built migration tooling, increasing risk of missing the deadline</p>", "<p>Migrate to Virtual Machines automates a lift-and-shift of VMware VMs to Compute Engine with minimal downtime, meeting the tight 3-month deadline with low risk, while preserving the option to modernize to microservices in a later phase.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization has separate GCP projects for its dev, prod, and data-analytics teams. Each team must retain its own billing and IAM boundaries, but the network security team wants to centrally manage VPC network topology, subnets, and firewall rules across all three projects. Which network design should be used?", "prompt": {"question": "<p>An organization has separate GCP projects for its dev, prod, and data-analytics teams. Each team must retain its own billing and IAM boundaries, but the network security team wants to centrally manage VPC network topology, subnets, and firewall rules across all three projects. Which network design should be used?</p>", "answers": ["<p>Establish VPC Peering connections between all three projects' independent VPC networks</p>", "<p>Consolidate all three teams into a single GCP project with IAM roles separating access</p>", "<p>Deploy a separate VPC network per project and connect them using a full mesh of Cloud VPN tunnels</p>", "<p>Configure a Shared VPC with a host project managed by the network security team and attach each team's project as a service project</p>"], "feedbacks": ["<p>VPC Peering is decentralized, does not support transitive routing, and firewall rules must still be managed per network, failing the centralized management requirement</p>", "<p>Merging into a single project eliminates the separate billing boundaries the teams need to retain</p>", "<p>A full mesh of VPN tunnels between separate VPCs adds significant operational complexity and still requires managing firewall rules independently per network</p>", "<p>Shared VPC allows a central host project to own and manage the network resources (subnets, routes, firewall rules) while service projects retain their own IAM and billing separation, exactly matching the requirement for centralized network control with separate team boundaries.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team needs to deploy a stateless HTTP microservice packaged as a custom Docker container image with a non-standard runtime not supported by Google's buildpacks. The service must scale to zero when idle and support request timeouts of up to 60 minutes. Which compute service should be used?", "prompt": {"question": "<p>A team needs to deploy a stateless HTTP microservice packaged as a custom Docker container image with a non-standard runtime not supported by Google's buildpacks. The service must scale to zero when idle and support request timeouts of up to 60 minutes. Which compute service should be used?</p>", "answers": ["<p>Cloud Run</p>", "<p>App Engine Standard environment</p>", "<p>GKE Autopilot cluster</p>", "<p>Cloud Functions (2nd gen)</p>"], "feedbacks": ["<p>Cloud Run natively deploys arbitrary custom container images, scales to zero automatically, and supports request timeouts of up to 60 minutes, directly satisfying all stated requirements with the lowest operational overhead.</p>", "<p>App Engine Standard restricts you to supported language runtimes and does not accept arbitrary custom container images, and its request timeout limits are much shorter</p>", "<p>GKE Autopilot can run custom containers but requires managing a Kubernetes cluster and does not scale to zero as simply or with as little operational overhead as Cloud Run</p>", "<p>Cloud Functions 2nd gen builds from source using buildpacks rather than accepting an arbitrary pre-built custom container image, making it unsuitable for a non-standard runtime</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a steady-state batch analytics workload on Compute Engine that must run continuously 24/7 for the next 3 years with predictable, unchanging resource requirements. The workload cannot tolerate interruption. Which purchasing option minimizes cost while meeting these constraints?", "prompt": {"question": "<p>A company runs a steady-state batch analytics workload on Compute Engine that must run continuously 24/7 for the next 3 years with predictable, unchanging resource requirements. The workload cannot tolerate interruption. Which purchasing option minimizes cost while meeting these constraints?</p>", "answers": ["<p>Rely only on automatically applied sustained use discounts</p>", "<p>Purchase a 3-year Committed Use Discount for the required vCPUs and memory</p>", "<p>Run the workload entirely on Spot VMs to take advantage of the lowest hourly rate</p>", "<p>Use standard on-demand pricing to retain full billing flexibility</p>"], "feedbacks": ["<p>Sustained use discounts are automatic but cap out at a lower discount than a 3-year commitment and are not optimized for a fully predictable 3-year workload</p>", "<p>A 3-year Committed Use Discount offers the deepest discount (up to roughly 70%) for predictable, long-running workloads with committed vCPU and memory usage, which matches this steady-state, non-interruptible workload.</p>", "<p>Spot VMs offer the lowest price but can be preempted at any time, which conflicts with the requirement that the workload cannot tolerate interruption</p>", "<p>On-demand pricing offers flexibility but is the most expensive option and provides no discount for a workload with known, unchanging capacity needs</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company requires a disaster recovery solution for their financial transaction database with an RPO of 15 minutes and RTO of 1 hour. The database currently runs on Cloud SQL for PostgreSQL in us-central1. Which solution BEST meets these requirements?", "prompt": {"question": "<p>A company requires a disaster recovery solution for their financial transaction database with an RPO of 15 minutes and RTO of 1 hour. The database currently runs on Cloud SQL for PostgreSQL in us-central1. Which solution BEST meets these requirements?</p>", "answers": ["<p>Configure a cross-region read replica in us-east1 and promote it to a standalone primary instance during a disaster</p>", "<p>Enable automated backups with 7-day retention and restore to a new instance in another region during a disaster</p>", "<p>Export nightly database dumps to Cloud Storage and use Cloud Storage multi-region for redundancy</p>", "<p>Migrate the database to Cloud Spanner configured as a single-region instance</p>"], "feedbacks": ["<p>A cross-region read replica continuously replicates data with minimal lag (meeting the 15-minute RPO) and can be promoted to a standalone primary quickly (meeting the 1-hour RTO), which is the standard Cloud SQL DR pattern.</p>", "<p>Restoring from a nightly/point-in-time backup can lose significantly more than 15 minutes of data and takes longer to restore than 1 hour, violating both RPO and RTO.</p>", "<p>Nightly dumps can lose up to 24 hours of transactions, far exceeding the 15-minute RPO requirement.</p>", "<p>A single-region Cloud Spanner instance provides no cross-region DR at all, and migrating engines is unnecessary re-architecture effort that doesn't directly solve the stated RPO/RTO requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A retail company needs to connect their on-premises data center to Google Cloud with a guaranteed SLA, requires 10 Gbps of dedicated bandwidth, and cannot route traffic over the public internet due to compliance requirements. Which connectivity option should the architect choose?", "prompt": {"question": "<p>A retail company needs to connect their on-premises data center to Google Cloud with a guaranteed SLA, requires 10 Gbps of dedicated bandwidth, and cannot route traffic over the public internet due to compliance requirements. Which connectivity option should the architect choose?</p>", "answers": ["<p>Cloud VPN using HA VPN gateways</p>", "<p>Dedicated Interconnect</p>", "<p>Direct Peering</p>", "<p>Partner Interconnect with a 1 Gbps connection</p>"], "feedbacks": ["<p>Cloud VPN encrypts traffic but still traverses the public internet, violating the compliance requirement, and each tunnel is capped well below 10 Gbps.</p>", "<p>Dedicated Interconnect provides a direct physical connection between the on-premises network and Google's network, keeps traffic off the public internet, supports circuits up to 10 Gbps (or 100 Gbps with newer offerings), and is covered by an SLA.</p>", "<p>Direct Peering connects to Google's edge network but is not covered by a Google SLA and does not guarantee dedicated bandwidth, so it does not meet the SLA requirement.</p>", "<p>Partner Interconnect at only 1 Gbps does not meet the 10 Gbps bandwidth requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company must migrate 200 on-premises VMware VMs running a legacy ERP application to Google Cloud within a 6-week deadline. The application vendor does not support containerization, and the operations team wants to minimize changes to the OS and application configuration. Which migration approach should the architect recommend?", "prompt": {"question": "<p>A company must migrate 200 on-premises VMware VMs running a legacy ERP application to Google Cloud within a 6-week deadline. The application vendor does not support containerization, and the operations team wants to minimize changes to the OS and application configuration. Which migration approach should the architect recommend?</p>", "answers": ["<p>Use Migrate to Virtual Machines to lift-and-shift the VMs to Compute Engine</p>", "<p>Re-architect the application to run on Google Kubernetes Engine using Migrate to Containers</p>", "<p>Manually export each VM as an OVA file and import them individually using Cloud Storage transfer</p>", "<p>Rewrite the application as a set of Cloud Functions</p>"], "feedbacks": ["<p>Migrate to Virtual Machines automates bulk migration of VMware VMs to Compute Engine with minimal changes to the OS or application, and can scale to migrate hundreds of VMs within a tight timeline, matching the lift-and-shift requirement.</p>", "<p>The vendor doesn't support containerization, and re-architecting to containers requires far more time and application changes than a 6-week window allows.</p>", "<p>Manually exporting and importing 200 VMs individually does not scale within 6 weeks and is highly error-prone compared to automated bulk migration tooling.</p>", "<p>Rewriting a legacy ERP application as Cloud Functions is a complete re-architecture that would take far longer than 6 weeks and violates the requirement to minimize changes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An architecture team is designing a fleet of Compute Engine VMs that will run continuously for 3 years with predictable, stable usage, and they are willing to commit to that usage level in advance to minimize compute costs. Which pricing model should they choose?", "prompt": {"question": "<p>An architecture team is designing a fleet of Compute Engine VMs that will run continuously for 3 years with predictable, stable usage, and they are willing to commit to that usage level in advance to minimize compute costs. Which pricing model should they choose?</p>", "answers": ["<p>3-year committed use discount (resource-based)</p>", "<p>Sustained use discounts</p>", "<p>Spot VMs</p>", "<p>On-demand pricing with no discounts</p>"], "feedbacks": ["<p>A 3-year resource-based committed use discount offers the largest discount (up to roughly 55-70% depending on machine type) for workloads with predictable, stable, long-term usage where the team can commit in advance.</p>", "<p>Sustained use discounts apply automatically but cap out around 30% and are lower than a committed use discount for continuous, predictable long-term workloads.</p>", "<p>Spot VMs can be preempted at any time with little notice, making them unsuitable for a continuously running production workload that needs to run for 3 years uninterrupted.</p>", "<p>On-demand pricing with no discounts is the most expensive option and ignores the opportunity to reduce costs given the predictable, committed usage pattern.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly differentiates Cloud Run from Google Kubernetes Engine (GKE) Autopilot for deploying containerized workloads?", "prompt": {"question": "<p>Which statement correctly differentiates Cloud Run from Google Kubernetes Engine (GKE) Autopilot for deploying containerized workloads?</p>", "answers": ["<p>Cloud Run requires the customer to manage the underlying node pool, whereas GKE Autopilot is fully serverless with no infrastructure to manage</p>", "<p>GKE Autopilot scales to zero running instances by default, while Cloud Run always maintains a minimum of one running instance</p>", "<p>Cloud Run only supports HTTP-triggered services, while GKE Autopilot only supports gRPC workloads</p>", "<p>Cloud Run is a fully managed serverless platform billed per request/duration, while GKE Autopilot is a managed Kubernetes environment billed per pod resource requests, offering more control over networking and stateful workloads</p>"], "feedbacks": ["<p>This reverses the relationship: Cloud Run has zero infrastructure or node management, while GKE Autopilot manages nodes on the customer's behalf but is still a Kubernetes cluster, not infrastructure-free in the same sense.</p>", "<p>This reverses the default scaling behavior: Cloud Run defaults to scaling to zero instances when idle (min-instances=0), while GKE Autopilot clusters and their control plane resources are not designed to scale to true zero the way Cloud Run services are.</p>", "<p>Both services support HTTP/2 and gRPC traffic; neither is restricted to a single protocol type, making this a false restriction.</p>", "<p>Cloud Run is a fully serverless platform with no infrastructure to manage, billed per request and execution duration, while GKE Autopilot is still a Kubernetes environment (billed per pod resource requests) that gives architects more control over networking, custom controllers, and stateful workloads that Cloud Run doesn't natively support.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has a central networking team that must control all subnets, routes, and firewall rules, while separate application teams (dev, test, prod) need to deploy Compute Engine and GKE resources into isolated projects without networking privileges. The application teams' resources must still communicate over private RFC 1918 IP space. Which topology BEST meets these requirements?", "prompt": {"question": "<p>A company has a central networking team that must control all subnets, routes, and firewall rules, while separate application teams (dev, test, prod) need to deploy Compute Engine and GKE resources into isolated projects without networking privileges. The application teams' resources must still communicate over private RFC 1918 IP space. Which topology BEST meets these requirements?</p>", "answers": ["<p>Create separate VPCs per team and connect them using VPC Peering</p>", "<p>Create a Shared VPC with the networking team owning the host project and each application team's project attached as a service project</p>", "<p>Give each application team its own VPC and connect them with a full-mesh Cloud VPN</p>", "<p>Put all resources in a single project with one VPC and use IAM conditions to restrict firewall edits</p>"], "feedbacks": ["<p>VPC Peering does not allow centralized firewall/subnet management by one team — each VPC still manages its own firewall rules independently, and peering doesn't support transitive routing.</p>", "<p>Shared VPC lets a host project (owned by the networking team) centrally control subnets, routes, and firewall rules while service projects (owned by app teams) deploy resources into those shared subnets, giving private connectivity without granting network admin rights to app teams.</p>", "<p>A VPN mesh between separate VPCs adds operational overhead, cost, and latency, and still leaves firewall/subnet control decentralized per VPC.</p>", "<p>A single VPC in one project doesn't provide project-level isolation for billing, quotas, and IAM boundaries between dev/test/prod teams, which is a stated requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A data engineering team ingests 50 TB of clickstream events daily and needs to run ad-hoc SQL analytics across the full historical dataset with minimal operational overhead and no need to manage servers or storage capacity in advance. Which Google Cloud service should they use?", "prompt": {"question": "<p>A data engineering team ingests 50 TB of clickstream events daily and needs to run ad-hoc SQL analytics across the full historical dataset with minimal operational overhead and no need to manage servers or storage capacity in advance. Which Google Cloud service should they use?</p>", "answers": ["<p>Cloud Bigtable</p>", "<p>BigQuery</p>", "<p>Cloud SQL for PostgreSQL</p>", "<p>Persistent Disk with a Compute Engine-hosted data warehouse</p>"], "feedbacks": ["<p>Cloud Bigtable is a NoSQL wide-column store optimized for high-throughput key-value/time-series workloads, not ad-hoc SQL analytics.</p>", "<p>BigQuery is a serverless, fully managed data warehouse built for petabyte-scale SQL analytics with no infrastructure provisioning, matching the ad-hoc SQL and no-ops requirements exactly.</p>", "<p>Cloud SQL is a relational OLTP database with storage and compute limits (max 64TB per instance) unsuitable for large-scale analytical scans and lacks BigQuery's columnar analytics engine.</p>", "<p>Self-managing a data warehouse on Compute Engine with Persistent Disk requires capacity planning, patching, and scaling — directly contradicting the 'minimal operational overhead' requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Compute Engine VMs in a private subnet have no external IP addresses but need to pull container images from Artifact Registry and read objects from Cloud Storage without traversing the public internet. What must you configure to enable this?", "prompt": {"question": "<p>Compute Engine VMs in a private subnet have no external IP addresses but need to pull container images from Artifact Registry and read objects from Cloud Storage without traversing the public internet. What must you configure to enable this?</p>", "answers": ["<p>Deploy a Cloud NAT gateway for the subnet</p>", "<p>Enable Private Google Access on the subnet</p>", "<p>Set up VPC Peering to Google's default network</p>", "<p>Configure Serverless VPC Access connector for the subnet</p>"], "feedbacks": ["<p>Cloud NAT provides outbound internet access via a shared external IP for internet-bound traffic; it's an alternative approach that still routes to public internet, not the specifically required feature for reaching Google APIs privately.</p>", "<p>Private Google Access allows VM instances with only internal IP addresses to reach Google APIs and services (Cloud Storage, Artifact Registry, etc.) using Google's private network path instead of the public internet.</p>", "<p>VPC Peering to a 'default network' isn't how Google APIs are accessed — Google APIs aren't exposed as peerable VPC networks.</p>", "<p>Serverless VPC Access connects serverless services (Cloud Run, Cloud Functions) into a VPC; it's unrelated to Compute Engine VMs reaching Google APIs.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A retailer already has network equipment installed in a colocation facility that offers direct access to a Google Cloud edge availability zone. They need a 10 Gbps private connection to their VPC with an SLA of 99.99% availability and no data traversing the public internet. Which connectivity option should they choose?", "prompt": {"question": "<p>A retailer already has network equipment installed in a colocation facility that offers direct access to a Google Cloud edge availability zone. They need a 10 Gbps private connection to their VPC with an SLA of 99.99% availability and no data traversing the public internet. Which connectivity option should they choose?</p>", "answers": ["<p>Dedicated Interconnect</p>", "<p>Classic VPN with static routing</p>", "<p>Direct Peering</p>", "<p>Carrier Peering</p>"], "feedbacks": ["<p>Dedicated Interconnect provides direct physical connections between the customer's network and Google's network at a supported colocation facility, offering high throughput (10 Gbps or 100 Gbps circuits), an SLA up to 99.99% (with redundant configurations), and private RFC 1918 connectivity without traversing the public internet.</p>", "<p>Cloud VPN encrypts traffic over the public internet and caps at roughly 3 Gbps per tunnel, and doesn't meet the strict SLA/throughput/private-only requirements.</p>", "<p>Direct Peering connects to Google's network for accessing Google public services/APIs, not for private connectivity into a customer's VPC, and doesn't carry an SLA.</p>", "<p>Carrier Peering routes traffic to Google's public IP services through a service provider but likewise doesn't extend into a private VPC with the required SLA.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An architect is deciding between Cloud Deployment Manager and Terraform for provisioning a Google Cloud environment that must eventually be extended to manage some resources in a secondary cloud provider. What is a key advantage of Terraform in this scenario?", "prompt": {"question": "<p>An architect is deciding between Cloud Deployment Manager and Terraform for provisioning a Google Cloud environment that must eventually be extended to manage some resources in a secondary cloud provider. What is a key advantage of Terraform in this scenario?</p>", "answers": ["<p>Terraform is a Google-proprietary tool that only supports Google Cloud resources</p>", "<p>Deployment Manager natively supports multi-cloud providers while Terraform does not</p>", "<p>Terraform requires no state tracking because it queries live infrastructure on every run</p>", "<p>Terraform uses declarative configuration files and a state file to track resources across multiple providers, including non-Google clouds</p>"], "feedbacks": ["<p>Terraform is developed by HashiCorp, not Google, and is explicitly multi-cloud — the opposite of this statement.</p>", "<p>Deployment Manager is a Google Cloud-only service and has no support for provisioning resources in other cloud providers.</p>", "<p>Terraform does maintain a state file (locally or in a remote backend like a Cloud Storage bucket) to map configuration to real-world resources; it does not simply query live infrastructure without state.</p>", "<p>Terraform is an open-source, provider-agnostic IaC tool that uses declarative HCL configuration and a state file to track resource metadata, and it supports providers for AWS, Azure, and many others in addition to Google Cloud, making it suitable for multi-cloud provisioning.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team wants every push to the main branch of their GKE application repository to automatically build a container image, scan it for vulnerabilities before storage, and deploy it to the cluster with no manual steps. Which approach BEST satisfies this requirement using Google Cloud native tooling?", "prompt": {"question": "<p>A team wants every push to the main branch of their GKE application repository to automatically build a container image, scan it for vulnerabilities before storage, and deploy it to the cluster with no manual steps. Which approach BEST satisfies this requirement using Google Cloud native tooling?</p>", "answers": ["<p>Configure a Cloud Build trigger on the repository that builds the image, pushes it to Artifact Registry with vulnerability scanning enabled, then runs a deploy step against the GKE cluster</p>", "<p>Install Jenkins on a Compute Engine VM and configure it to poll the repository every 5 minutes for changes</p>", "<p>Use Cloud Scheduler to trigger a nightly Cloud Function that rebuilds and redeploys the application</p>", "<p>Manually run 'gcloud builds submit' and 'kubectl apply' whenever a developer reports the branch has changed</p>"], "feedbacks": ["<p>Cloud Build triggers integrate directly with source repositories to automatically build on push events; Artifact Registry provides integrated container vulnerability scanning on push, and a deploy step (e.g., using the Cloud Build GKE deploy step or kubectl) completes a fully automated CI/CD pipeline with no manual intervention.</p>", "<p>Self-managing Jenkins on a VM adds unnecessary operational overhead (patching, scaling, HA) when Cloud Build offers this natively, and polling introduces deployment delay versus event-driven triggers.</p>", "<p>A nightly scheduled rebuild does not satisfy the 'every push' automated requirement and introduces unacceptable deployment latency.</p>", "<p>Manual command execution contradicts the explicit requirement for full automation with no manual steps.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has a Shared VPC hosting three projects: prod-app, prod-db, and analytics. The security team requires that VMs in the analytics project can only communicate with VMs in prod-db on TCP port 5432, and must be denied all other access to prod-db, regardless of future changes to broader firewall rules. Which approach BEST meets this requirement?", "prompt": {"question": "<p>A company has a Shared VPC hosting three projects: prod-app, prod-db, and analytics. The security team requires that VMs in the analytics project can only communicate with VMs in prod-db on TCP port 5432, and must be denied all other access to prod-db, regardless of future changes to broader firewall rules. Which approach BEST meets this requirement?</p>", "answers": ["<p>Create a hierarchical firewall policy attached to the folder containing prod-db that denies all ingress except TCP 5432 from the analytics subnet's service account, ensuring it evaluates before VPC-level rules</p>", "<p>Create a single VPC firewall rule in the Shared VPC host project allowing TCP 5432 from the analytics subnet to the prod-db subnet, with a priority lower than existing allow rules</p>", "<p>Use hierarchical firewall policies at the organization node to allow TCP 5432 between the two subnets</p>", "<p>Configure VPC Service Controls around the prod-db project to restrict API access to only the analytics project</p>"], "feedbacks": ["<p>Hierarchical firewall policies are evaluated before VPC-level firewall rules and are enforced regardless of changes made within individual VPC firewall configurations. Attaching a policy at the folder level containing prod-db, with an explicit deny-all except TCP 5432 from analytics, guarantees the restriction cannot be bypassed by future VPC-level rule changes in the host project.</p>", "<p>A standard VPC firewall rule can be overridden or supplemented by other rules with higher priority in the same VPC, and doesn't guarantee the restriction survives future changes since it's just one rule among many at the same enforcement layer</p>", "<p>Placing the allow rule at the organization node doesn't restrict access from other sources to prod-db, and org-level policies affect all resources in the org, which is overly broad and doesn't create the required deny-by-default posture</p>", "<p>VPC Service Controls restrict access to Google Cloud APIs and services (like Cloud Storage, BigQuery) to prevent data exfiltration — they do not control network-level TCP traffic between VM instances, so this doesn't address port-level VM-to-VM restrictions</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company runs workloads on GKE and needs those workloads to call Google Cloud APIs (e.g., Cloud Storage, BigQuery) without storing any downloadable service account keys in the cluster, due to a security audit requirement that prohibits long-lived credentials. Which approach BEST meets this requirement?", "prompt": {"question": "<p>A financial services company runs workloads on GKE and needs those workloads to call Google Cloud APIs (e.g., Cloud Storage, BigQuery) without storing any downloadable service account keys in the cluster, due to a security audit requirement that prohibits long-lived credentials. Which approach BEST meets this requirement?</p>", "answers": ["<p>Enable Workload Identity Federation for GKE and bind the Kubernetes service account to a Google service account via IAM policy binding</p>", "<p>Create a service account, generate a JSON key, and store it as a Kubernetes Secret mounted into the pods</p>", "<p>Use the Compute Engine default service account attached to each GKE node with broad Editor role</p>", "<p>Distribute the same service account key to all pods via a shared ConfigMap and rotate it every 90 days</p>"], "feedbacks": ["<p>Workload Identity (Federation) lets Kubernetes service accounts impersonate Google service accounts using short-lived, automatically rotated credentials obtained via the metadata server — no exportable JSON keys are ever created or stored, satisfying the audit requirement.</p>", "<p>Mounting a JSON key as a Secret still creates a long-lived, exportable credential that can be exfiltrated, violating the requirement.</p>", "<p>Using the node's default service account with Editor violates least privilege and ties pod permissions to node-level identity, not workload-level identity.</p>", "<p>Manually rotating a shared key every 90 days still involves long-lived downloadable keys and shared credentials across pods, which is exactly what the audit prohibits.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A healthcare company must ensure that all new Cloud Storage buckets and Compute Engine resources created anywhere in its GCP organization are restricted to the us and europe-west multi-regions only, to satisfy data residency requirements. Which mechanism should the architect configure at the Organization node?", "prompt": {"question": "<p>A healthcare company must ensure that all new Cloud Storage buckets and Compute Engine resources created anywhere in its GCP organization are restricted to the us and europe-west multi-regions only, to satisfy data residency requirements. Which mechanism should the architect configure at the Organization node?</p>", "answers": ["<p>An Organization Policy constraint using constraints/gcp.resourceLocations set to allowed values for us and eu regions</p>", "<p>A VPC Service Controls perimeter scoped to the us and europe-west regions</p>", "<p>A Cloud Armor security policy that blocks requests originating from disallowed regions</p>", "<p>IAM Conditions on every project's Owner role restricting resource creation by region</p>"], "feedbacks": ["<p>The gcp.resourceLocations Organization Policy constraint restricts where resources can be created across the entire org hierarchy, enforcing data residency at resource-creation time regardless of who creates it.</p>", "<p>VPC Service Controls restricts data exfiltration between services/perimeters, not the physical region where resources are allowed to be created.</p>", "<p>Cloud Armor filters incoming HTTP(S) traffic by source; it has no control over where storage or compute resources are physically located.</p>", "<p>IAM Conditions can restrict access by attributes like time or resource name patterns, but they do not enforce resource location constraints at creation and would need to be replicated per role/project, which doesn't scale to an org-wide policy.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company must encrypt data in BigQuery using keys they generate, control the rotation schedule of, and can disable to immediately revoke access to the data, while still relying on Google to manage the underlying key infrastructure. Which encryption approach satisfies this?", "prompt": {"question": "<p>A company must encrypt data in BigQuery using keys they generate, control the rotation schedule of, and can disable to immediately revoke access to the data, while still relying on Google to manage the underlying key infrastructure. Which encryption approach satisfies this?</p>", "answers": ["<p>Google-managed encryption keys (default encryption)</p>", "<p>Customer-supplied encryption keys (CSEK) uploaded per request</p>", "<p>Customer-managed encryption keys (CMEK) via Cloud KMS</p>", "<p>Client-side encryption performed before data is uploaded to BigQuery</p>"], "feedbacks": ["<p>Google-managed keys give no customer control over rotation or the ability to disable keys to revoke access; Google fully manages them.</p>", "<p>CSEK requires the customer to supply the raw key on every request and is not supported by BigQuery for encryption at rest in this managed way — it's primarily a Compute Engine/Cloud Storage feature and doesn't provide Google-managed rotation.</p>", "<p>CMEK lets the customer create and control keys in Cloud KMS, set rotation schedules, and disable/destroy keys to revoke access immediately, while Google still manages the KMS infrastructure — exactly matching the described requirements.</p>", "<p>Client-side encryption before upload means BigQuery cannot process/query the data natively, breaking core BigQuery functionality like SQL analytics on the encrypted columns.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company stores sensitive data in BigQuery and Cloud Storage and is concerned about an insider with legitimate IAM permissions exfiltrating that data to a personal Google Cloud project outside the organization. Which control specifically addresses this data exfiltration risk?", "prompt": {"question": "<p>A company stores sensitive data in BigQuery and Cloud Storage and is concerned about an insider with legitimate IAM permissions exfiltrating that data to a personal Google Cloud project outside the organization. Which control specifically addresses this data exfiltration risk?</p>", "answers": ["<p>Enforce IAM Conditions requiring MFA for all data access</p>", "<p>Enable Cloud Audit Logs for Data Access on all relevant services</p>", "<p>Apply an Organization Policy restricting service account key creation</p>", "<p>Configure a VPC Service Controls perimeter around the projects containing BigQuery and Cloud Storage</p>"], "feedbacks": ["<p>IAM Conditions with MFA strengthen authentication but do nothing to stop an authenticated, authorized insider from copying data to an external project.</p>", "<p>Audit Logs provide visibility and forensic evidence after the fact but do not prevent the exfiltration from happening in real time.</p>", "<p>Restricting service account key creation reduces credential theft risk but doesn't stop a legitimately authorized user from copying/exporting data to another project.</p>", "<p>VPC Service Controls creates a security perimeter around GCP resources, blocking data movement (via APIs) to services or projects outside the perimeter even by users with valid IAM permissions, which directly mitigates insider exfiltration to external projects.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An architect needs to store and rotate database connection passwords used by multiple Cloud Run services, with fine-grained IAM access control and versioning, and separately needs to scan customer support ticket text for accidental inclusion of credit card numbers before storing it. Which pair of services should be used, respectively?", "prompt": {"question": "<p>An architect needs to store and rotate database connection passwords used by multiple Cloud Run services, with fine-grained IAM access control and versioning, and separately needs to scan customer support ticket text for accidental inclusion of credit card numbers before storing it. Which pair of services should be used, respectively?</p>", "answers": ["<p>Cloud KMS for password storage and Cloud DLP for credit card detection</p>", "<p>Secret Manager for password storage and Cloud Armor for credit card detection</p>", "<p>Cloud KMS for password storage and Cloud Armor for credit card detection</p>", "<p>Secret Manager for password storage and Cloud DLP for credit card detection</p>"], "feedbacks": ["<p>Cloud KMS manages encryption keys, not secret values themselves; it lacks Secret Manager's built-in versioning and secret-specific access model for storing passwords directly.</p>", "<p>Cloud Armor is a web application firewall/DDoS protection service for HTTP(S) load balancers; it has no capability to scan text content for sensitive data patterns like credit card numbers.</p>", "<p>Same issue as above — Cloud Armor cannot perform content inspection for PII/PCI data; that is Cloud DLP's function, and Cloud KMS is not the right fit for secret storage/versioning compared to Secret Manager.</p>", "<p>Secret Manager is purpose-built for storing, versioning, and controlling IAM access to secrets like passwords, while Cloud DLP provides built-in infoType detectors (including CREDIT_CARD_NUMBER) to inspect and redact sensitive data in text.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A service account used by a batch data pipeline needs permission only to read objects from a single Cloud Storage bucket and write query results to a single BigQuery dataset. Following least privilege principles, which role assignment is BEST?", "prompt": {"question": "<p>A service account used by a batch data pipeline needs permission only to read objects from a single Cloud Storage bucket and write query results to a single BigQuery dataset. Following least privilege principles, which role assignment is BEST?</p>", "answers": ["<p>Grant the service account Storage Object Viewer on the specific bucket and BigQuery Data Editor on the specific dataset</p>", "<p>Grant the service account the Editor primitive role on the project</p>", "<p>Grant the service account Owner role scoped to the project's Storage and BigQuery APIs</p>", "<p>Grant the service account Storage Admin and BigQuery Admin roles at the project level</p>"], "feedbacks": ["<p>Assigning Storage Object Viewer at the bucket level and BigQuery Data Editor at the dataset level grants only the specific read and write permissions needed, scoped to the exact resources involved, fully aligning with least privilege.</p>", "<p>The Editor primitive role grants broad create/modify/delete permissions across nearly all services in the project, far exceeding what the pipeline needs.</p>", "<p>Owner role is even broader than Editor, including IAM management capabilities, and 'scoping to specific APIs' isn't how primitive roles work — Owner is project-wide.</p>", "<p>Storage Admin and BigQuery Admin at the project level grant administrative control (including deletion and IAM changes) over all buckets/datasets in the project, not just the two resources the pipeline actually needs.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A retail company stores sensitive customer PII in BigQuery datasets and Cloud Storage buckets within a dedicated 'sensitive-data' project. The security team is concerned that a compromised service account credential or a misconfigured IAM binding could allow data to be copied to a different, unauthorized GCP project outside the organization. Which control should the architect implement to prevent this specific type of data exfiltration?", "prompt": {"question": "<p>A retail company stores sensitive customer PII in BigQuery datasets and Cloud Storage buckets within a dedicated 'sensitive-data' project. The security team is concerned that a compromised service account credential or a misconfigured IAM binding could allow data to be copied to a different, unauthorized GCP project outside the organization. Which control should the architect implement to prevent this specific type of data exfiltration?</p>", "answers": ["<p>Enable Private Google Access on all subnets in the sensitive-data project</p>", "<p>Apply a Cloud Armor security policy to the project's load balancers</p>", "<p>Configure a VPC Service Controls perimeter around the sensitive-data project's resources</p>", "<p>Migrate the project to a Shared VPC host project to centralize network administration</p>"], "feedbacks": ["<p>Private Google Access only allows VM instances without external IPs to reach Google APIs privately; it does not restrict which projects or perimeters data can be copied to, so it does not stop exfiltration.</p>", "<p>Cloud Armor provides Layer 7 protection (WAF rules, DDoS mitigation) for HTTP(S) load balancers fronting web applications; it has no effect on API-level data exfiltration between GCP services or projects.</p>", "<p>VPC Service Controls creates a service perimeter around GCP resources (BigQuery, Cloud Storage, etc.) that blocks data movement to services or projects outside the perimeter, even if the caller has valid IAM permissions and credentials. This directly mitigates exfiltration via compromised credentials or misconfigured IAM bindings, which is exactly the scenario described.</p>", "<p>Shared VPC centralizes network resource management and administration across projects but does not restrict data access boundaries at the API/service level, so it does not prevent this exfiltration path.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A healthcare company must encrypt patient records stored in Cloud Storage using customer-managed encryption keys. Compliance requirements state that the encryption keys must physically reside in the same region as the data and must be rotated automatically every 365 days. Which configuration satisfies these requirements?", "prompt": {"question": "<p>A healthcare company must encrypt patient records stored in Cloud Storage using customer-managed encryption keys. Compliance requirements state that the encryption keys must physically reside in the same region as the data and must be rotated automatically every 365 days. Which configuration satisfies these requirements?</p>", "answers": ["<p>Create a global Cloud KMS key ring, set the key rotation period to 90 days, and enable CMEK on the Cloud Storage buckets</p>", "<p>Encrypt the data using Google-managed encryption keys, which rotate automatically by default</p>", "<p>Create a regional Cloud KMS key ring in the same region as the storage buckets, set the key rotation period to 365 days, and enable CMEK on the buckets using that key</p>", "<p>Generate a Customer-Supplied Encryption Key (CSEK) and provide it with every Cloud Storage API request, rotating it manually once a year</p>"], "feedbacks": ["<p>A global key ring does not guarantee the key resides in the same region as the data, failing the residency requirement, and a 90-day rotation period does not match the required 365-day cadence.</p>", "<p>Google-managed keys are fully managed by Google with no customer control over key location or rotation schedule, so they cannot satisfy a stated CMEK/region-residency compliance requirement.</p>", "<p>A regional Cloud KMS key ring stores keys in a specific region, satisfying the co-location/data residency requirement. Cloud KMS supports configurable automatic rotation periods, so setting it to 365 days meets the annual rotation requirement, and CMEK lets the customer retain full control over the key used to encrypt the Cloud Storage data.</p>", "<p>CSEK requires the customer to supply the raw key material with every request and does not store keys in Cloud KMS at all; Google does not manage automatic rotation for CSEK, making it operationally risky and non-compliant with an automated annual rotation requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A retail company suffers a major production outage caused by a bad deployment. Leadership wants to learn from the incident and prevent it from recurring without discouraging engineers from taking ownership of future releases. Which process should the cloud architect recommend?", "prompt": {"question": "<p>A retail company suffers a major production outage caused by a bad deployment. Leadership wants to learn from the incident and prevent it from recurring without discouraging engineers from taking ownership of future releases. Which process should the cloud architect recommend?</p>", "answers": ["<p>Identify the individual engineer responsible and require additional training</p>", "<p>Require VP-level manual sign-off for every future deployment</p>", "<p>Disable the CI/CD pipeline until an investigation committee is formed</p>", "<p>Conduct a blameless postmortem that documents root cause and actionable follow-up items</p>"], "feedbacks": ["<p>Singling out an individual creates a blame culture that discourages transparency and future incident reporting, and does not address underlying systemic issues.</p>", "<p>Manual VP sign-off adds delivery friction without addressing the root cause of the failure and does not scale.</p>", "<p>Disabling CI/CD halts all delivery and does not investigate or fix the underlying process gap that caused the outage.</p>", "<p>A blameless postmortem focuses on identifying systemic root causes and generating concrete action items, which improves reliability while preserving a healthy engineering culture and encouraging future incident reporting.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a steady-state production workload on Compute Engine 24/7 and is willing to commit to a 3-year usage term in exchange for the maximum possible discount on that predictable capacity. Which purchasing option should the architect recommend?", "prompt": {"question": "<p>A company runs a steady-state production workload on Compute Engine 24/7 and is willing to commit to a 3-year usage term in exchange for the maximum possible discount on that predictable capacity. Which purchasing option should the architect recommend?</p>", "answers": ["<p>Sustained use discounts</p>", "<p>Preemptible VMs / Spot VMs</p>", "<p>Committed use discounts (CUDs)</p>", "<p>Free Tier usage credits</p>"], "feedbacks": ["<p>Sustained use discounts are automatic monthly discounts applied without any commitment and offer a smaller discount than CUDs — they do not require or reward a 3-year commitment.</p>", "<p>Preemptible/Spot VMs offer deep discounts but can be terminated at any time, making them unsuitable for workloads requiring guaranteed steady-state uptime.</p>", "<p>Committed use discounts require a 1- or 3-year commitment to a specific amount of vCPU/memory or spend, and provide the largest discount (up to ~70%) for predictable, steady-state workloads.</p>", "<p>Free Tier credits are limited introductory credits for new customers and are not a mechanism for discounting ongoing steady-state production usage.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company wants to add fraud detection to its application but has no in-house machine learning expertise and needs to minimize time to market. Which approach best fits a build-vs-buy decision in this context?", "prompt": {"question": "<p>A financial services company wants to add fraud detection to its application but has no in-house machine learning expertise and needs to minimize time to market. Which approach best fits a build-vs-buy decision in this context?</p>", "answers": ["<p>Build a custom TensorFlow model from scratch and train it on Compute Engine GPUs</p>", "<p>Hire and ramp up a dedicated in-house ML engineering team over the next year</p>", "<p>Deploy a self-managed Spark MLlib cluster on GKE</p>", "<p>Use Vertex AI AutoML or a prebuilt fraud detection API</p>"], "feedbacks": ["<p>Building a custom model from scratch requires significant ML expertise and time the team does not have, delaying delivery.</p>", "<p>Hiring and ramping up a new team takes months to a year, which conflicts with the requirement to minimize time to market.</p>", "<p>Managing a self-managed Spark MLlib cluster adds significant operational overhead and still requires ML expertise the team lacks.</p>", "<p>Given no internal ML expertise and a need for fast time to market, using Vertex AI AutoML or a managed prebuilt API is the 'buy' option that delivers results quickly without requiring specialized in-house skills.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team deploying to GKE wants to gradually shift a percentage of production traffic to a new application version and automatically roll back if error rates spike, as part of their managed CI/CD release process. Which Google Cloud configuration achieves this?", "prompt": {"question": "<p>A team deploying to GKE wants to gradually shift a percentage of production traffic to a new application version and automatically roll back if error rates spike, as part of their managed CI/CD release process. Which Google Cloud configuration achieves this?</p>", "answers": ["<p>Configure a Cloud Build trigger that filters on the release branch name</p>", "<p>Enable vulnerability scanning in Artifact Registry</p>", "<p>Mirror the repository using Cloud Source Repositories</p>", "<p>Define a canary deployment strategy in a Cloud Deploy delivery pipeline configuration</p>"], "feedbacks": ["<p>A branch filter trigger only controls which commits start a build; it has no mechanism for traffic splitting or canary rollout.</p>", "<p>Vulnerability scanning inspects container images for security issues but has no role in traffic-based progressive rollout.</p>", "<p>Repository mirroring is a source-control feature and does not affect how traffic is shifted between application versions.</p>", "<p>Cloud Deploy natively supports canary deployment strategies defined in the delivery pipeline configuration, allowing gradual traffic shifting and automated verification/rollback for GKE targets.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A product team consistently prioritizes new features over refactoring, resulting in growing technical debt that is starting to slow delivery velocity. Which practice best balances technical debt against ongoing feature delivery?", "prompt": {"question": "<p>A product team consistently prioritizes new features over refactoring, resulting in growing technical debt that is starting to slow delivery velocity. Which practice best balances technical debt against ongoing feature delivery?</p>", "answers": ["<p>Address technical debt only after the entire feature backlog has been completed</p>", "<p>Allocate a fixed percentage of each sprint or roadmap cycle to continuously address technical debt</p>", "<p>Ignore technical debt unless it directly causes a production outage</p>", "<p>Address technical debt only during a major annual version release</p>"], "feedbacks": ["<p>Feature backlogs are rarely 'complete,' so deferring technical debt indefinitely allows it to compound and eventually block delivery.</p>", "<p>Continuously allocating a fixed portion of capacity each cycle to technical debt prevents it from accumulating to a point where it blocks delivery, while still allowing steady feature progress — a recommended continuous improvement practice.</p>", "<p>Waiting for an outage to address technical debt is reactive and risks reliability and business impact before action is taken.</p>", "<p>Annual-only remediation lets debt accumulate for long periods, increasing risk and slowing velocity between releases.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's current change management process requires full Change Advisory Board (CAB) review for every production change, causing release delays. Leadership wants faster, safer releases while still maintaining a compliance audit trail. Which approach should the architect recommend?", "prompt": {"question": "<p>A company's current change management process requires full Change Advisory Board (CAB) review for every production change, causing release delays. Leadership wants faster, safer releases while still maintaining a compliance audit trail. Which approach should the architect recommend?</p>", "answers": ["<p>Require full Change Advisory Board (CAB) approval for every change, regardless of risk</p>", "<p>Eliminate change tracking entirely to speed up releases</p>", "<p>Implement CI/CD pipelines with policy-as-code checks (e.g., Binary Authorization) and rely on Cloud Audit Logs for traceability, removing manual approval for low-risk changes</p>", "<p>Consolidate all releases into infrequent, large 'big-bang' quarterly deployments</p>"], "feedbacks": ["<p>Requiring full CAB review for every change is the current bottleneck the company wants to eliminate and does not scale with release velocity goals.</p>", "<p>Removing all change tracking eliminates the audit trail needed for compliance, which is explicitly required.</p>", "<p>Automating policy enforcement with policy-as-code and relying on Cloud Audit Logs for traceability satisfies compliance requirements while removing manual bottlenecks for low-risk changes, enabling faster and safer releases.</p>", "<p>Big-bang quarterly releases increase risk per deployment and reduce the ability to quickly detect and roll back issues, worsening reliability.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's payment-processing service experienced a 45-minute outage last week. During the incident retrospective meeting, several engineers were reluctant to share details about the deployment that triggered the outage because a director from another team was present and known to reprimand individuals for mistakes. As cloud architect, which practice should you recommend to improve the effectiveness of post-incident reviews going forward?", "prompt": {"question": "<p>A company's payment-processing service experienced a 45-minute outage last week. During the incident retrospective meeting, several engineers were reluctant to share details about the deployment that triggered the outage because a director from another team was present and known to reprimand individuals for mistakes. As cloud architect, which practice should you recommend to improve the effectiveness of post-incident reviews going forward?</p>", "answers": ["<p>Require the on-call engineer who caused the outage to write a personal action plan and present it to the director</p>", "<p>Institute blameless postmortems that focus on identifying systemic and process failures rather than individual fault, with documented timelines and action items tracked to completion</p>", "<p>Limit postmortem meetings to only the SRE team so that other stakeholders cannot ask uncomfortable questions</p>", "<p>Replace postmortem meetings with an automated incident report generated solely from Cloud Monitoring alert logs</p>"], "feedbacks": ["<p>Singling out an individual for personal blame is the opposite of the blameless culture Google's SRE practices recommend and will suppress future honesty;</p>", "<p>Blameless postmortems are the Google-recommended SRE practice: they focus on system and process gaps rather than punishing individuals, which encourages honest disclosure of root cause and produces trackable action items that drive continuous improvement.</p>", "<p>Excluding stakeholders reduces organizational learning and cross-team alignment, which contradicts the goal of process improvement across the business;</p>", "<p>An automated report from monitoring logs alone lacks human analysis of contributing factors, decision points, and process gaps, so it cannot replace a structured review with action items</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A retail company's mobile app team wants to reduce time-to-market for new features. Currently, every code change requires a manual QA sign-off that takes 3 days, and releases occur once per month. The team has strong software engineering skills but limited operations experience. Which change should you recommend first to best optimize this technical process?", "prompt": {"question": "<p>A retail company's mobile app team wants to reduce time-to-market for new features. Currently, every code change requires a manual QA sign-off that takes 3 days, and releases occur once per month. The team has strong software engineering skills but limited operations experience. Which change should you recommend first to best optimize this technical process?</p>", "answers": ["<p>Introduce automated testing (unit, integration) integrated into a CI/CD pipeline so manual QA is reduced to exception cases, enabling more frequent, smaller releases</p>", "<p>Move release approval entirely to the business stakeholders so QA is no longer required before production release</p>", "<p>Increase release frequency to twice per month while keeping the manual QA process unchanged</p>", "<p>Outsource the QA function to a third-party vendor to keep the 3-day manual review but run it in parallel with development</p>"], "feedbacks": ["<p>Automating testing within a CI/CD pipeline directly addresses the bottleneck (manual QA) using the team's existing engineering strength, enabling smaller, more frequent, lower-risk releases and is the standard recommendation for optimizing SDLC/release management processes on the exam.</p>", "<p>Removing QA entirely increases risk without addressing the root cause and ignores quality/compliance needs;</p>", "<p>Simply doubling release frequency without changing the QA bottleneck just doubles the manual QA burden and does not solve the underlying process inefficiency;</p>", "<p>Outsourcing QA still keeps a manual 3-day gate as the primary release mechanism, only shifting who performs it rather than reducing cycle time through automation</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs to deploy identical Google Cloud infrastructure across separate dev, staging, and production projects. Leadership requires a full audit history of every infrastructure change and the ability to roll back to a previous known-good state quickly. Which approach BEST meets these requirements?", "prompt": {"question": "<p>A company needs to deploy identical Google Cloud infrastructure across separate dev, staging, and production projects. Leadership requires a full audit history of every infrastructure change and the ability to roll back to a previous known-good state quickly. Which approach BEST meets these requirements?</p>", "answers": ["<p>Use Cloud Shell to manually run gcloud commands in each project and record the steps in a shared document</p>", "<p>Define the infrastructure as code using Terraform configurations stored in a version-controlled repository, applied through a CI/CD pipeline</p>", "<p>Use the Cloud Console to click through resource creation in each project and export instance templates for reuse</p>", "<p>Write a collection of bash scripts using gcloud commands and store them in a Cloud Storage bucket</p>"], "feedbacks": ["<p>Manual gcloud commands with a shared doc are error-prone, not truly repeatable, and provide no reliable audit trail tied to actual resource state.</p>", "<p>Terraform configs in version control give a declarative, auditable change history (via commit log) and let you roll back by reverting to a prior commit and re-applying, satisfying both requirements while remaining repeatable across projects.</p>", "<p>Console-based clicking is not repeatable or version-controlled, and instance templates alone don't capture full project infrastructure or provide rollback.</p>", "<p>Bash scripts in Cloud Storage lack declarative state tracking, diffing, and built-in rollback that IaC tools provide; they're imperative and harder to audit.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A development team wants an automated pipeline that builds a container image whenever code is pushed to a Cloud Source Repositories repo, and then deploys the new image to GKE. Which Google Cloud service should orchestrate this build-and-deploy pipeline?", "prompt": {"question": "<p>A development team wants an automated pipeline that builds a container image whenever code is pushed to a Cloud Source Repositories repo, and then deploys the new image to GKE. Which Google Cloud service should orchestrate this build-and-deploy pipeline?</p>", "answers": ["<p>Cloud Scheduler</p>", "<p>Cloud Composer</p>", "<p>Cloud Build</p>", "<p>Cloud Tasks</p>"], "feedbacks": ["<p>Cloud Scheduler only triggers jobs on a time-based (cron) schedule, not on repo push events or build orchestration.</p>", "<p>Cloud Composer is a managed Apache Airflow service for orchestrating data workflows, not source-triggered CI/CD builds.</p>", "<p>Cloud Build is Google Cloud's CI/CD service that supports triggers on repo pushes, builds container images, and can deploy them to GKE as part of a defined build pipeline (cloudbuild.yaml).</p>", "<p>Cloud Tasks manages asynchronous task queues for distributed execution, not build/deploy pipelines triggered by source changes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An architect needs a CI/CD pipeline running outside Google Cloud to authenticate and deploy resources on behalf of the organization, without relying on any individual's personal Google account credentials. Which approach should be used?", "prompt": {"question": "<p>An architect needs a CI/CD pipeline running outside Google Cloud to authenticate and deploy resources on behalf of the organization, without relying on any individual's personal Google account credentials. Which approach should be used?</p>", "answers": ["<p>Have the pipeline run 'gcloud auth login' interactively each time it executes</p>", "<p>Share the architect's personal OAuth refresh token with the pipeline configuration</p>", "<p>Authenticate using a service account, ideally via workload identity federation or, if required, a service account key with gcloud auth activate-service-account</p>", "<p>Store the project owner's Google account password as a pipeline secret</p>"], "feedbacks": ["<p>'gcloud auth login' requires interactive browser-based user consent and is not suitable for unattended automated pipelines.</p>", "<p>Sharing a personal OAuth token ties automation to an individual's identity and access, violating least-privilege and continuity best practices.</p>", "<p>Service accounts are designed for non-interactive, programmatic access. Workload identity federation lets external CI/CD systems obtain short-lived credentials without managing long-lived keys, and gcloud auth activate-service-account is the standard fallback for key-based authentication.</p>", "<p>Google Cloud does not use account passwords for API/pipeline authentication, and storing a password as a secret is an insecure anti-pattern not supported by GCP's auth model.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement best describes the primary advantage of using Infrastructure as Code (IaC) tools such as Terraform or Deployment Manager over manual, console-based provisioning during implementation of a Google Cloud architecture?", "prompt": {"question": "<p>Which statement best describes the primary advantage of using Infrastructure as Code (IaC) tools such as Terraform or Deployment Manager over manual, console-based provisioning during implementation of a Google Cloud architecture?</p>", "answers": ["<p>IaC tools automatically scale compute resources up or down based on real-time traffic</p>", "<p>IaC provides declarative, version-controlled, and repeatable deployments that can be reviewed and rolled back</p>", "<p>IaC is the only supported method for creating resources in Google Cloud</p>", "<p>IaC eliminates the need for a separate testing or staging environment</p>"], "feedbacks": ["<p>Autoscaling is handled by services like managed instance groups or GKE autoscalers, not an inherent feature of IaC tooling itself.</p>", "<p>The core benefit of IaC is declaring desired state in code, storing it under version control for peer review and history, and enabling consistent, repeatable, and reversible deployments across environments.</p>", "<p>The Cloud Console, gcloud CLI, and client libraries can all create resources directly; IaC is a best practice, not the only supported method.</p>", "<p>IaC does not remove the need for testing environments; it actually makes it easier to spin up consistent staging environments for validation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Before promoting a new application version from staging to production, the operations team wants to validate that it behaves correctly under production-like load while minimizing risk to real users. Which approach BEST achieves this during implementation?", "prompt": {"question": "<p>Before promoting a new application version from staging to production, the operations team wants to validate that it behaves correctly under production-like load while minimizing risk to real users. Which approach BEST achieves this during implementation?</p>", "answers": ["<p>Deploy the new version directly to 100% of production traffic and monitor Cloud Monitoring for error spikes</p>", "<p>Perform a canary or blue/green deployment, routing a small percentage of production traffic to the new version while load-testing it before a full rollout</p>", "<p>Rely on manual testing already completed in staging and skip further validation</p>", "<p>Ask a subset of end users to report issues after the new version is fully released</p>"], "feedbacks": ["<p>Full-traffic deployment with only after-the-fact monitoring exposes all users to potential failures instead of limiting risk proactively.</p>", "<p>Canary or blue/green deployments combined with load testing let teams validate behavior under realistic production traffic and load while limiting the blast radius if problems occur, which is the recommended safe-rollout pattern for implementation.</p>", "<p>Staging tests alone don't reproduce true production-scale traffic patterns, data volume, or concurrency, so additional controlled validation is still needed.</p>", "<p>Relying on user-reported issues is reactive, delays detection, and impacts real users rather than validating safely beforehand.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company runs a critical workload on Cloud SQL for PostgreSQL. The business requires an RPO of 5 minutes and an RTO of 10 minutes in the event of a full regional outage. Which configuration BEST meets these requirements?", "prompt": {"question": "<p>A financial services company runs a critical workload on Cloud SQL for PostgreSQL. The business requires an RPO of 5 minutes and an RTO of 10 minutes in the event of a full regional outage. Which configuration BEST meets these requirements?</p>", "answers": ["<p>Enable Cloud SQL high availability (regional) configuration only</p>", "<p>Create a cross-region read replica and implement automated procedures to promote it to a standalone primary during a regional outage</p>", "<p>Configure automated daily backups with point-in-time recovery</p>", "<p>Migrate the database to a single-region Cloud Spanner instance</p>"], "feedbacks": ["<p>Cloud SQL HA (regional) only protects against zonal failures within the same region — it does not survive a full regional outage.</p>", "<p>A cross-region read replica keeps a continuously updated copy of data in another region (satisfying the tight RPO), and an automated, tested promotion runbook/script can bring it online as the new primary well within a 10-minute RTO. This is the standard Cloud SQL pattern for regional DR.</p>", "<p>Daily backups with point-in-time recovery could lose up to 24 hours of data (violating the 5-minute RPO) and restoring a large database typically takes far longer than 10 minutes.</p>", "<p>A single-region Cloud Spanner instance does not survive a regional outage either, so it does not solve the stated problem, and migrating engines is not the minimal solution being tested here.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A team runs services on App Engine and GKE and wants unhandled application exceptions to be automatically detected, deduplicated, and grouped by stack trace across all services, without writing custom log queries. Which Cloud Operations tool should they use?", "prompt": {"question": "<p>A team runs services on App Engine and GKE and wants unhandled application exceptions to be automatically detected, deduplicated, and grouped by stack trace across all services, without writing custom log queries. Which Cloud Operations tool should they use?</p>", "answers": ["<p>Cloud Monitoring</p>", "<p>Cloud Trace</p>", "<p>Error Reporting</p>", "<p>Cloud Profiler</p>"], "feedbacks": ["<p>Cloud Monitoring handles metrics, dashboards, and alerting policies, but does not automatically parse and group stack traces from application logs.</p>", "<p>Cloud Trace analyzes request latency across distributed services; it is not designed for exception aggregation.</p>", "<p>Error Reporting automatically analyzes and aggregates application errors from logs across App Engine, GKE, Compute Engine, and Cloud Functions, grouping them by stack trace signature with no custom query configuration required.</p>", "<p>Cloud Profiler continuously analyzes CPU and memory usage of running code; it does not deal with exceptions or error grouping.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A service has a defined SLO of 99.9% availability measured over a rolling 30-day window. Approximately how much total downtime does the associated error budget allow within that 30-day window?", "prompt": {"question": "<p>A service has a defined SLO of 99.9% availability measured over a rolling 30-day window. Approximately how much total downtime does the associated error budget allow within that 30-day window?</p>", "answers": ["<p>43.2 minutes</p>", "<p>4.32 minutes</p>", "<p>7.2 hours</p>", "<p>21.6 minutes</p>"], "feedbacks": ["<p>30 days = 43,200 minutes. An error budget of 0.1% (100% - 99.9%) of that window is 43,200 x 0.001 = 43.2 minutes of allowed downtime.</p>", "<p>4.32 minutes corresponds to a 99.99% SLO (an order of magnitude too strict), not 99.9%.</p>", "<p>7.2 hours (432 minutes) is 10x the correct value, mistakenly using 1% instead of 0.1%.</p>", "<p>21.6 minutes is half the correct value, resulting from an arithmetic error (e.g., using 15 days instead of 30).</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A team wants to release a new application version to production by routing a small percentage of live traffic to it while monitoring error rates and latency, with the ability to quickly shift traffic back to the previous version if problems appear, before rolling out to 100% of users. Which deployment strategy should they use?", "prompt": {"question": "<p>A team wants to release a new application version to production by routing a small percentage of live traffic to it while monitoring error rates and latency, with the ability to quickly shift traffic back to the previous version if problems appear, before rolling out to 100% of users. Which deployment strategy should they use?</p>", "answers": ["<p>Blue-green deployment</p>", "<p>Rolling update</p>", "<p>Canary deployment</p>", "<p>Recreate deployment strategy</p>"], "feedbacks": ["<p>Blue-green deployment switches all traffic at once between two full environments; it does not gradually shift a small traffic percentage for observation.</p>", "<p>Rolling update incrementally replaces instances of the old version with the new one but does not control traffic percentage independent of instance count, and typically has no fast full rollback of live traffic split.</p>", "<p>Canary deployment routes a small, controlled percentage of production traffic to the new version so teams can observe real-world metrics before increasing traffic, with fast rollback by shifting traffic weight back — exactly the pattern described.</p>", "<p>Recreate deployment terminates all old instances before starting new ones, causing downtime and offering no gradual traffic-based validation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "Which statement correctly distinguishes a Service Level Indicator (SLI) from a Service Level Objective (SLO)?", "prompt": {"question": "<p>Which statement correctly distinguishes a Service Level Indicator (SLI) from a Service Level Objective (SLO)?</p>", "answers": ["<p>An SLI is defined by a legal contract, while an SLO is measured internally by the operations team</p>", "<p>An SLA and an SLO are functionally identical and used interchangeably</p>", "<p>An SLI is a quantitative measure of some aspect of a service's behavior, while an SLO is a target value or range of values for that SLI</p>", "<p>An SLI is the target value for a metric, while an SLO is the actual measured value of that metric</p>"], "feedbacks": ["<p>Legal contracts describe SLAs, not SLIs; SLIs are internal measurements, not contractual definitions.</p>", "<p>SLAs and SLOs are related but distinct: SLAs are customer-facing agreements with consequences, while SLOs are internal engineering targets, often stricter than the SLA.</p>", "<p>An SLI (e.g., request latency, error rate) is the actual measured metric. An SLO is the target or acceptable range set for that SLI (e.g., 99.9% of requests under 300ms). An SLA is the external, often contractual, commitment tied to consequences if the SLO is missed.</p>", "<p>This reverses the correct relationship — the SLI is the measured value, and the SLO is the target for that measurement, not the other way around.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A stateful application on GKE uses zonal persistent disks for storage. The company needs the ability to restore application data to a different region within one hour after a regional outage. Which approach BEST satisfies this requirement?", "prompt": {"question": "<p>A stateful application on GKE uses zonal persistent disks for storage. The company needs the ability to restore application data to a different region within one hour after a regional outage. Which approach BEST satisfies this requirement?</p>", "answers": ["<p>Configure regional persistent disks, which synchronously replicate data across two zones within the same region only</p>", "<p>Rely on GKE's default automatic disk resizing feature</p>", "<p>Use local SSDs for all persistent volumes to maximize IOPS</p>", "<p>Create a snapshot schedule for the persistent disks with snapshots stored in a multi-region location, enabling restoration to a disk in a different region</p>"], "feedbacks": ["<p>Regional persistent disks only replicate synchronously between two zones inside the same region — they do not protect against a full regional outage.</p>", "<p>Disk resizing changes capacity and has nothing to do with data durability, replication, or disaster recovery.</p>", "<p>Local SSDs are ephemeral, physically attached to a single host, and lose all data if the instance terminates — they provide no DR capability at all.</p>", "<p>Scheduled persistent disk snapshots stored in a multi-region location are durable across regions and can be used to create a new persistent disk in any region, enabling recovery of application data in a different region during a regional outage.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}], "expected": 45}, {"name": "Google PCA Practice Test 2", "cid": 7301139, "duration": 120, "pass_percent": 70, "questions": [{"assessment_type": "multiple-choice", "question_plain": "A global trading platform requires an RPO of zero and an RTO under 60 seconds for its primary transactional database, and must remain fully available even if an entire GCP region fails. The team is evaluating database options for this tier. Which design BEST meets these requirements?", "prompt": {"question": "<p>A global trading platform requires an RPO of zero and an RTO under 60 seconds for its primary transactional database, and must remain fully available even if an entire GCP region fails. The team is evaluating database options for this tier. Which design BEST meets these requirements?</p>", "answers": ["<p>Cloud SQL for PostgreSQL with a cross-region read replica that is manually promoted during a regional outage</p>", "<p>Cloud Bigtable with application-level replication configured between two regional clusters</p>", "<p>Compute Engine instances running a self-managed database with regional persistent disks replicated synchronously across two zones</p>", "<p>Cloud Spanner configured with a multi-region instance configuration (e.g., nam3) spanning three regions</p>"], "feedbacks": ["<p>Cloud SQL cross-region replicas replicate asynchronously and require manual promotion, so RPO is not zero and failover takes minutes, not seconds</p>", "<p>Bigtable replication is eventually consistent by design, so it cannot guarantee RPO=0 for transactional workloads</p>", "<p>Regional persistent disks only replicate across zones within a single region, so the design does not survive a full regional outage at all</p>", "<p>Cloud Spanner's multi-region configurations provide synchronous replication across regions with a 99.999% availability SLA, RPO of zero, and automatic failover well under a minute — the only option here that natively satisfies both RPO=0 and sub-60-second RTO across a full regional failure.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company needs a hybrid connection between its on-premises data center and GCP that meets a 99.99% availability SLA and supports 10 Gbps of dedicated, non-internet-routed bandwidth. Which configuration should the architect implement?", "prompt": {"question": "<p>A company needs a hybrid connection between its on-premises data center and GCP that meets a 99.99% availability SLA and supports 10 Gbps of dedicated, non-internet-routed bandwidth. Which configuration should the architect implement?</p>", "answers": ["<p>Two Dedicated Interconnect connections in different edge availability domains, each connected to a separate Cloud Router</p>", "<p>A single Dedicated Interconnect connection terminated at one Cloud Router</p>", "<p>A single HA VPN tunnel over the public internet with Cloud Router dynamic routing</p>", "<p>A single Partner Interconnect connection provisioned through a service provider at 10 Gbps</p>"], "feedbacks": ["<p>Google's SLA for Dedicated Interconnect only reaches 99.99% when two connections are provisioned in different edge availability domains (ideally different metros), each with its own Cloud Router, eliminating single points of failure at the physical and routing layers.</p>", "<p>A single Dedicated Interconnect connection is only covered by a 99.9% SLA because there is no redundant physical path</p>", "<p>HA VPN over the internet does not provide the dedicated 10 Gbps non-internet path required and is bounded by internet variability, not the target SLA tier for this bandwidth requirement</p>", "<p>A single Partner Interconnect connection, like a single Dedicated Interconnect, has no redundancy and does not meet the 99.99% SLA tier</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A retailer runs a monolithic Java application on VMware with tightly coupled dependencies on the local file system and JVM configuration. The business has an 8-week deadline to exit the on-premises data center due to a lease expiration, and the team has no bandwidth to refactor the application before the deadline. Which migration approach should the architect recommend?", "prompt": {"question": "<p>A retailer runs a monolithic Java application on VMware with tightly coupled dependencies on the local file system and JVM configuration. The business has an 8-week deadline to exit the on-premises data center due to a lease expiration, and the team has no bandwidth to refactor the application before the deadline. Which migration approach should the architect recommend?</p>", "answers": ["<p>Refactor the application into microservices and deploy to Google Kubernetes Engine</p>", "<p>Rewrite the application as a set of Cloud Run services to eliminate infrastructure management</p>", "<p>Use Migrate to Virtual Machines to lift-and-shift the VMware VMs directly to Compute Engine</p>", "<p>Deploy Anthos on-premises to modernize the application in place without migrating it to GCP</p>"], "feedbacks": ["<p>Refactoring to microservices on GKE requires redesigning the coupled file system and JVM dependencies, which cannot be done safely in 8 weeks</p>", "<p>Rewriting as Cloud Run services requires the app to be stateless and containerized, which conflicts with its local file system dependency and cannot be completed in the timeframe</p>", "<p>Migrate to Virtual Machines is purpose-built for rapid lift-and-shift of VMware VMs to Compute Engine with minimal application changes, making it the only option that realistically meets an 8-week hard deadline while preserving the existing tightly-coupled architecture for later modernization.</p>", "<p>Deploying Anthos on-premises does not exit the data center at all, failing the core business requirement of vacating the lease</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization uses a hub-and-spoke Shared VPC design with one host project and five service projects, each owned by a different application team. The security team requires that each team can only launch VM instances into the specific subnets assigned to their team, without being able to modify firewall rules or subnet configurations in the host project. Which configuration meets this requirement?", "prompt": {"question": "<p>An organization uses a hub-and-spoke Shared VPC design with one host project and five service projects, each owned by a different application team. The security team requires that each team can only launch VM instances into the specific subnets assigned to their team, without being able to modify firewall rules or subnet configurations in the host project. Which configuration meets this requirement?</p>", "answers": ["<p>Grant each team's group the Compute Network Admin role on the host project</p>", "<p>Create a separate VPC per team and connect all VPCs to the host VPC using VPC Peering</p>", "<p>Grant each team's group the Project Owner role on the host project so they can self-manage networking</p>", "<p>Grant each team's group the Compute Network User role scoped to their specific subnets in the host project</p>"], "feedbacks": ["<p>Compute Network Admin grants full control over network resources including firewall rules and subnet configuration, far exceeding the least-privilege requirement</p>", "<p>VPC Peering between separate VPCs does not transitively share subnets the way Shared VPC does, and it reintroduces per-VPC quota and firewall management overhead the hub-and-spoke Shared VPC model was chosen to avoid</p>", "<p>Project Owner grants broad administrative control over the entire host project, including firewall and subnet configuration, which directly violates the stated restriction</p>", "<p>The Compute Network User role (roles/compute.networkUser) can be granted at the subnet level in a Shared VPC host project, allowing a service project team to attach VM instances to specific subnets without granting them any ability to modify firewall rules, routes, or subnet configuration.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A workload runs continuously 24/7 with a stable baseline of 200 vCPUs for a committed 3-year period, plus unpredictable traffic bursts of up to 100 additional vCPUs a few times per month. The architect must minimize cost while keeping the burst capacity flexible. Which combination of purchasing options should be used?", "prompt": {"question": "<p>A workload runs continuously 24/7 with a stable baseline of 200 vCPUs for a committed 3-year period, plus unpredictable traffic bursts of up to 100 additional vCPUs a few times per month. The architect must minimize cost while keeping the burst capacity flexible. Which combination of purchasing options should be used?</p>", "answers": ["<p>Apply sustained use discounts to all 300 vCPUs and rely on their automatic monthly application</p>", "<p>Purchase a 3-year resource-based Committed Use Discount for the 200 vCPU baseline, and use on-demand autoscaled instances for the burst capacity</p>", "<p>Purchase Reserved Instances for the full 300 vCPUs to lock in the lowest possible rate</p>", "<p>Run all 300 vCPUs on Spot VMs to take advantage of the deepest available discount</p>"], "feedbacks": ["<p>Sustained use discounts apply automatically but max out around 30% and are not designed to optimize a known 3-year steady commitment the way a CUD is — CUDs stack better for guaranteed long-term baseline usage</p>", "<p>A 3-year resource-based Committed Use Discount gives the deepest possible discount (up to ~57%) on the predictable steady-state baseline, while leaving the unpredictable burst capacity on on-demand autoscaled instances preserves flexibility without a long-term commitment on capacity that isn't consistently used.</p>", "<p>'Reserved Instances' is AWS terminology, not a GCP purchasing model, and even conceptually, committing the full 300 vCPUs including the unpredictable burst wastes money whenever bursts don't occur</p>", "<p>Spot VMs can be preempted at any time with only a 30-second notice, making them unsuitable for a stable, always-on baseline workload that must remain available continuously</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company must migrate its on-premises Oracle database to GCP with minimal application changes and near-zero downtime during cutover, ideally landing on a fully managed, PostgreSQL-compatible destination. Which migration approach should the architect choose?", "prompt": {"question": "<p>A financial services company must migrate its on-premises Oracle database to GCP with minimal application changes and near-zero downtime during cutover, ideally landing on a fully managed, PostgreSQL-compatible destination. Which migration approach should the architect choose?</p>", "answers": ["<p>Use Storage Transfer Service to move nightly Oracle export dumps into Cloud Storage, then load them into Cloud SQL</p>", "<p>Write custom scripts on a Compute Engine VM to poll Oracle redo logs and replicate changes into Cloud SQL</p>", "<p>Use Database Migration Service to perform a continuous, CDC-based migration from Oracle to AlloyDB for PostgreSQL</p>", "<p>Use Datastream alone to stream Oracle data continuously into BigQuery for the application to query directly</p>"], "feedbacks": ["<p>Nightly export/import dumps introduce hours of data staleness and a large cutover window, failing the near-zero downtime requirement</p>", "<p>Custom redo-log replication scripts are operationally fragile, unmanaged, and require significant engineering effort compared to a purpose-built managed service</p>", "<p>Database Migration Service supports Oracle as a source for continuous, change-data-capture-based migration into AlloyDB for PostgreSQL (and Cloud SQL for PostgreSQL), enabling ongoing replication until a low-downtime cutover — directly meeting the near-zero downtime and managed-destination requirements.</p>", "<p>BigQuery is an analytics warehouse, not a transactional, PostgreSQL-compatible OLTP destination, so it does not meet the requirement to replace the operational Oracle database</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A retail company runs 400 VMware VMs on-premises and wants to migrate them to Compute Engine with the least possible cutover downtime. They want to validate application behavior in an isolated network before the final cutover, and they want continuous block-level replication so the cutover delta is minimal. Which migration approach should the architect recommend?", "prompt": {"question": "<p>A retail company runs 400 VMware VMs on-premises and wants to migrate them to Compute Engine with the least possible cutover downtime. They want to validate application behavior in an isolated network before the final cutover, and they want continuous block-level replication so the cutover delta is minimal. Which migration approach should the architect recommend?</p>", "answers": ["<p>Export each VM to OVA format, upload the images to Cloud Storage, and create custom Compute Engine images from the OVA files</p>", "<p>Use the Transfer Appliance to ship VM disk data to Cloud Storage, then import the disks with gcloud compute images import</p>", "<p>Use Migrate to Virtual Machines to replicate the VMs continuously, run them as test clones in an isolated network for validation, then cut over</p>", "<p>Use Migrate for Anthos to convert the VMs into containers and deploy them on GKE before validating in a staging cluster</p>"], "feedbacks": ["<p>OVA export/upload is a manual, one-time image transfer with no continuous replication, causing large cutover windows and no built-in test-clone validation capability</p>", "<p>Transfer Appliance is designed for one-time bulk offline data transfer (e.g., large datasets over limited bandwidth), not for continuous incremental VM replication with minimal cutover delta</p>", "<p>Migrate to Virtual Machines performs streaming, continuous block-level replication from the source VMware environment, and supports launching isolated 'test clone' instances in a separate network for validation without affecting the production replication stream, minimizing cutover downtime to the final delta sync.</p>", "<p>Migrate for Anthos re-architects VMs into containers, which is a re-platform/re-architect approach with higher risk and effort than required — the scenario asks for a lift-and-shift with minimal downtime, not containerization</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A hospital network needs a hybrid connection from its on-premises data center to a VPC, requiring a 99.99% availability SLA and 10 Gbps of dedicated capacity. The hospital's IT team does not have equipment co-located in any Google-supported colocation facility and does not want to establish a physical presence there. Which connectivity option satisfies these requirements?", "prompt": {"question": "<p>A hospital network needs a hybrid connection from its on-premises data center to a VPC, requiring a 99.99% availability SLA and 10 Gbps of dedicated capacity. The hospital's IT team does not have equipment co-located in any Google-supported colocation facility and does not want to establish a physical presence there. Which connectivity option satisfies these requirements?</p>", "answers": ["<p>Partner Interconnect with connections through two different service provider edge availability domains</p>", "<p>Dedicated Interconnect with a single 10 Gbps connection</p>", "<p>Cross-Cloud Interconnect to establish direct connectivity to the on-premises network</p>", "<p>Classic Cloud VPN with two tunnels configured in an active-active HA VPN setup</p>"], "feedbacks": ["<p>Partner Interconnect lets a customer connect through a supported service provider without needing a presence in a Google colocation facility. Achieving the 99.99% SLA requires redundant connections in two different metro/edge availability domains, matching the exact production-level design pattern tested on the exam.</p>", "<p>Dedicated Interconnect requires the customer to have equipment physically co-located in a Google-supported colocation facility, which the hospital explicitly lacks; a single connection also only qualifies for a 99.9% SLA at best</p>", "<p>Cross-Cloud Interconnect is designed to connect Google Cloud directly to another cloud provider's network, not to an on-premises data center</p>", "<p>Cloud VPN (classic or HA) tunnels are capped at roughly 3 Gbps per tunnel and route over the public internet, so they cannot reliably deliver 10 Gbps or the 99.99% SLA the scenario demands</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A global financial trading platform requires a transactional database with near-zero RPO and automatic failover in under a minute across three regions, while maintaining strong consistency for all reads and writes. Which Google Cloud database service should the architect select?", "prompt": {"question": "<p>A global financial trading platform requires a transactional database with near-zero RPO and automatic failover in under a minute across three regions, while maintaining strong consistency for all reads and writes. Which Google Cloud database service should the architect select?</p>", "answers": ["<p>Cloud SQL for PostgreSQL with a cross-region read replica promoted manually during failover</p>", "<p>Cloud Spanner configured with a multi-region instance configuration</p>", "<p>Cloud Bigtable configured with multi-cluster routing across three regions</p>", "<p>Memorystore for Redis with cross-region replication enabled</p>"], "feedbacks": ["<p>Cloud SQL cross-region replicas use asynchronous replication and require a manual promotion step, resulting in both data loss risk (non-zero RPO) and failover times far exceeding one minute</p>", "<p>Cloud Spanner's multi-region configurations use synchronous, quorum-based replication with external strong consistency and automatic leaderless failover, giving near-zero RPO and sub-minute automatic recovery without manual intervention — exactly what strict financial transactional workloads require.</p>", "<p>Bigtable multi-cluster routing provides eventual consistency between clusters, which does not meet the strong-consistency requirement for financial transactions</p>", "<p>Memorystore for Redis is an in-memory cache/store, not designed as a durable, strongly consistent transactional system of record, and its cross-region replication is not built for automatic sub-minute regional failover of critical transactional data</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company runs a stable, predictable workload requiring a fixed set of specific N2 machine type vCPUs and memory continuously for the next 3 years. The finance team wants to guarantee the maximum possible discount and is willing to commit to that exact resource footprint regardless of whether usage fluctuates slightly month to month. Which pricing model should the architect recommend?", "prompt": {"question": "<p>A company runs a stable, predictable workload requiring a fixed set of specific N2 machine type vCPUs and memory continuously for the next 3 years. The finance team wants to guarantee the maximum possible discount and is willing to commit to that exact resource footprint regardless of whether usage fluctuates slightly month to month. Which pricing model should the architect recommend?</p>", "answers": ["<p>Rely on automatic Sustained Use Discounts, since usage already exceeds 25% of the month</p>", "<p>Use Spot VMs for the workload to take advantage of the deepest available discounts</p>", "<p>Purchase a 1-year Flexible Committed Use Discount based on projected monthly spend</p>", "<p>Purchase a 3-year resource-based Committed Use Discount for the specific N2 machine type resources</p>"], "feedbacks": ["<p>Sustained Use Discounts are automatic and require no commitment, but they cap out at a lower discount rate (around 30%) and don't provide the maximum guaranteed savings the finance team wants for known long-term usage</p>", "<p>Spot VMs are for interruptible, fault-tolerant workloads and can be reclaimed at any time; they are unsuitable for a stable, continuously running production workload</p>", "<p>Flexible CUDs are spend-based and apply across machine families/regions with slightly lower discount rates than resource-based CUDs, making them a worse fit than a resource-based commitment when the exact machine type and duration are already known</p>", "<p>A 3-year resource-based Committed Use Discount locks in a specific machine type/vCPU/memory commitment and delivers the largest available discount for guaranteed, predictable long-term usage — the tradeoff being the customer pays for the committed resources regardless of actual usage, which matches the stated business requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A large enterprise has 20 independent application teams, each requiring its own project for IAM isolation and separate billing, but the network security team must centrally manage all firewall rules, subnets, and a single Dedicated Interconnect connection to the on-premises data center shared by all teams. Which network design should the architect implement?", "prompt": {"question": "<p>A large enterprise has 20 independent application teams, each requiring its own project for IAM isolation and separate billing, but the network security team must centrally manage all firewall rules, subnets, and a single Dedicated Interconnect connection to the on-premises data center shared by all teams. Which network design should the architect implement?</p>", "answers": ["<p>Create individual VPCs per team and connect them all to each other using VPC Network Peering</p>", "<p>Create individual VPCs per team and connect each to on-premises using its own Cloud VPN tunnel</p>", "<p>Create a Shared VPC with the network team's project as the host project and each team's project attached as a service project</p>", "<p>Consolidate all 20 teams into a single project and assign each team a distinct IAM role</p>"], "feedbacks": ["<p>VPC Network Peering is non-transitive, so the network team would need to manage a complex full-mesh of peering relationships and cannot centrally administer firewall rules or share the single Interconnect connection across all 20 VPCs</p>", "<p>Giving each team its own VPC and VPN tunnel to on-premises multiplies connectivity cost and administrative overhead, and abandons the requirement of a single centrally managed Interconnect connection</p>", "<p>Shared VPC lets a central host project own the network (subnets, firewall rules, and the single Interconnect attachment) while service projects retain separate billing and IAM boundaries for each team — this is the standard pattern for centralized network governance with per-team project isolation.</p>", "<p>Consolidating all teams into a single project eliminates the required per-team billing and project-level IAM isolation, violating a core business requirement even though IAM roles could technically differentiate access within one project</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company uses Shared VPC with a host project 'net-host' and two service projects, 'team-a-svc' and 'team-b-svc'. Team A's project admins need to create and manage firewall rules that apply only to instances tagged 'team-a-web' in the Shared VPC network, without being able to view or modify firewall rules that affect Team B's resources. Which approach BEST meets this requirement?", "prompt": {"question": "<p>A company uses Shared VPC with a host project 'net-host' and two service projects, 'team-a-svc' and 'team-b-svc'. Team A's project admins need to create and manage firewall rules that apply only to instances tagged 'team-a-web' in the Shared VPC network, without being able to view or modify firewall rules that affect Team B's resources. Which approach BEST meets this requirement?</p>", "answers": ["<p>Grant Team A's admins the Compute Security Admin role on the host project net-host, scoped with an IAM condition that restricts the grant to firewall rule resources containing the target tag 'team-a-web'.</p>", "<p>Grant Team A's admins the Owner role on their own service project team-a-svc.</p>", "<p>Grant Team A's admins the Compute Network User role on the host project net-host.</p>", "<p>Create a separate VPC network for Team A and connect it to the Shared VPC network using VPC Network Peering.</p>"], "feedbacks": ["<p>In Shared VPC, firewall rules always live in the host project, so any admin who manages them needs a role granted on the host project. Compute Security Admin grants firewall rule management, and an IAM condition can scope that grant to resources matching a specific tag, letting Team A manage only its own rules without touching Team B's.</p>", "<p>Owner on team-a-svc only affects the service project's own resources; it grants no permission to create or modify firewall rules, which are defined in the host project's Shared VPC network.</p>", "<p>Compute Network User only allows a team to use (attach resources to) subnets in the Shared VPC network; it does not include permission to create or edit firewall rules.</p>", "<p>Creating a separate peered VPC breaks the Shared VPC model, adds unnecessary complexity and non-transitive peering constraints, and does not solve the underlying IAM scoping problem for firewall rule management.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization has three VPC networks: vpc-finance, vpc-hr, and vpc-shared-services. vpc-finance is peered with vpc-shared-services, and vpc-hr is also peered with vpc-shared-services. A new requirement states that instances in vpc-finance must reach internal load balancers in vpc-hr using internal IP addresses, and the organization expects to add several more department VPCs with similar cross-communication needs in the near future. Which solution BEST meets these requirements with minimal ongoing management overhead?", "prompt": {"question": "<p>An organization has three VPC networks: vpc-finance, vpc-hr, and vpc-shared-services. vpc-finance is peered with vpc-shared-services, and vpc-hr is also peered with vpc-shared-services. A new requirement states that instances in vpc-finance must reach internal load balancers in vpc-hr using internal IP addresses, and the organization expects to add several more department VPCs with similar cross-communication needs in the near future. Which solution BEST meets these requirements with minimal ongoing management overhead?</p>", "answers": ["<p>Rely on the existing peering configuration, since VPC Network Peering is transitive and vpc-finance can already reach vpc-hr through vpc-shared-services.</p>", "<p>Migrate the department VPCs to a Shared VPC architecture with a single host project, or adopt Network Connectivity Center in a hub-and-spoke topology.</p>", "<p>Create a direct VPC Network Peering connection between vpc-finance and vpc-hr.</p>", "<p>Configure Cloud VPN tunnels between vpc-finance and vpc-hr using their internal RFC 1918 IP ranges.</p>"], "feedbacks": ["<p>VPC Network Peering is explicitly non-transitive: peering A-B and B-C does not allow A to reach C, so vpc-finance cannot reach vpc-hr through vpc-shared-services today.</p>", "<p>Shared VPC or Network Connectivity Center's hub-and-spoke model centralizes connectivity so that as new departments are added, they simply attach to the shared network or hub, avoiding a growing full mesh of point-to-point connections and reducing long-term operational overhead.</p>", "<p>A direct peering connection would work for this one pair, but as more departments are added it forces a full mesh of pairwise peering connections, which does not scale and increases management overhead, contradicting the stated future requirement.</p>", "<p>Cloud VPN tunnels add encryption/tunneling overhead and per-tunnel management, and still create a point-to-point relationship that does not scale as more departments are added; it also does not solve the underlying topology problem as well as a hub model.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A batch-processing workload runs on Compute Engine instances that have no external IP addresses. The instances must read objects from Cloud Storage and must also download base container images from Docker Hub on the public internet during startup. Which configuration is required to satisfy both requirements?", "prompt": {"question": "<p>A batch-processing workload runs on Compute Engine instances that have no external IP addresses. The instances must read objects from Cloud Storage and must also download base container images from Docker Hub on the public internet during startup. Which configuration is required to satisfy both requirements?</p>", "answers": ["<p>Configure a Cloud NAT gateway on the subnet only.</p>", "<p>Enable Private Google Access on the subnet only.</p>", "<p>Temporarily assign external IP addresses to the instances during the startup phase.</p>", "<p>Enable Private Google Access on the subnet AND configure a Cloud NAT gateway.</p>"], "feedbacks": ["<p>Cloud NAT alone can technically reach the internet including Google APIs, but it is not the recommended or exam-tested pattern for Google API traffic, and it unnecessarily consumes NAT ports/quota that should be reserved for genuine internet destinations like Docker Hub.</p>", "<p>Private Google Access alone only covers access to Google APIs and services; it does not provide a path to public internet destinations such as Docker Hub, so the image download would fail.</p>", "<p>Assigning external IPs works but violates the security best practice of keeping backend batch instances without public IPs, and is unnecessary operational complexity when Private Google Access and Cloud NAT solve the requirement without exposing the instances.</p>", "<p>Private Google Access lets instances without external IPs reach Google APIs (like Cloud Storage) over Google's internal network path without consuming Cloud NAT resources, while Cloud NAT is required separately to allow outbound connections to non-Google internet destinations like Docker Hub. Both are needed together to satisfy the full requirement.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team already manages all Kubernetes workloads through GitOps: manifests are stored in a Git repository and reconciled onto GKE clusters by a continuous delivery operator. They now want to provision GCP resources, such as Cloud SQL instances and Cloud Storage buckets, using the same GitOps workflow and the same kubectl-based tooling, with the resources' state visible through the Kubernetes API alongside their application objects. Which tool should they use to provision the GCP resources?", "prompt": {"question": "<p>A platform team already manages all Kubernetes workloads through GitOps: manifests are stored in a Git repository and reconciled onto GKE clusters by a continuous delivery operator. They now want to provision GCP resources, such as Cloud SQL instances and Cloud Storage buckets, using the same GitOps workflow and the same kubectl-based tooling, with the resources' state visible through the Kubernetes API alongside their application objects. Which tool should they use to provision the GCP resources?</p>", "answers": ["<p>Cloud Deployment Manager.</p>", "<p>Terraform with the Google provider, applied through a separate CI/CD pipeline outside of Kubernetes.</p>", "<p>gcloud CLI scripts triggered by Cloud Build on every Git push.</p>", "<p>Config Connector.</p>"], "feedbacks": ["<p>Deployment Manager uses its own YAML/Jinja/Python templating and API outside of Kubernetes; it has no integration with kubectl or the Kubernetes API, so it does not fit the described GitOps-on-Kubernetes workflow.</p>", "<p>Terraform is a valid IaC tool but applying it through a separate pipeline outside Kubernetes does not give the team the requested unified kubectl-based, Kubernetes-API-visible experience alongside their app manifests.</p>", "<p>Imperative gcloud scripts triggered by Cloud Build do not provide declarative state reconciliation or Kubernetes-native resource visibility, and drift from the actual desired-state GitOps model the team is using for applications.</p>", "<p>Config Connector exposes GCP resources as Kubernetes Custom Resources, letting teams manage Cloud SQL instances, Cloud Storage buckets, and other GCP services with kubectl and standard Kubernetes-native GitOps tooling, with state tracked in the Kubernetes API alongside application manifests.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A team uses Cloud Build to build container images and wants a fully managed continuous delivery pipeline that automatically deploys new releases to a staging GKE cluster, then requires an explicit manual approval before that same release is promoted to the production GKE cluster. Which approach implements this promotion workflow with a built-in approval gate?", "prompt": {"question": "<p>A team uses Cloud Build to build container images and wants a fully managed continuous delivery pipeline that automatically deploys new releases to a staging GKE cluster, then requires an explicit manual approval before that same release is promoted to the production GKE cluster. Which approach implements this promotion workflow with a built-in approval gate?</p>", "answers": ["<p>Configure two separate Cloud Build triggers, one for staging and one for production, each firing independently on push to a branch.</p>", "<p>Use Google Cloud Deploy to define a delivery pipeline with staging and production targets, enabling a required approval on the production target.</p>", "<p>Use Cloud Scheduler to invoke the production Cloud Build trigger a fixed number of hours after the staging deployment completes.</p>", "<p>Store images in Artifact Registry and use a Cloud Function triggered on new image push to deploy directly to production.</p>"], "feedbacks": ["<p>Cloud Build triggers execute builds/deployments independently and have no native concept of promoting the same validated release with a manual approval gate between environments; this would require significant custom scripting to replicate safely.</p>", "<p>Cloud Deploy is the managed continuous delivery service for GKE (and other runtimes) that models a pipeline of progressive targets and natively supports requiring manual approval before a release is promoted to a given target, such as production, which is exactly the described gate.</p>", "<p>A time-based Cloud Scheduler trigger promotes on a fixed schedule regardless of whether the release actually passed validation or received human sign-off, which does not satisfy an explicit manual approval requirement.</p>", "<p>Deploying directly from Artifact Registry via a Cloud Function on every image push bypasses staging validation and any approval step entirely, sending every build straight to production.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A company requires a hybrid connection between its on-premises data center and its VPC network with these requirements: 10 Gbps aggregate throughput, traffic that never traverses the public internet, and a 99.99% availability SLA. Which configuration BEST meets these requirements?", "prompt": {"question": "<p>A company requires a hybrid connection between its on-premises data center and its VPC network with these requirements: 10 Gbps aggregate throughput, traffic that never traverses the public internet, and a 99.99% availability SLA. Which configuration BEST meets these requirements?</p>", "answers": ["<p>Two Dedicated Interconnect connections, each in a different Interconnect location, configured with redundant Cloud Routers.</p>", "<p>A single Dedicated Interconnect connection with 10 Gbps of capacity.</p>", "<p>Two Dedicated Interconnect connections in the same metro location but attached to different edge availability domains.</p>", "<p>A Partner Interconnect connection combined with a Cloud VPN tunnel configured as an automatic failover path.</p>"], "feedbacks": ["<p>Google's documented Interconnect SLA tiers require two or more Dedicated Interconnect connections located in at least two different metropolitan (Interconnect) locations, along with redundant Cloud Routers, to qualify for the 99.99% availability SLA, while keeping traffic entirely off the public internet.</p>", "<p>A single Dedicated Interconnect connection has no redundancy and does not qualify for any of Google's higher SLA tiers; a physical or maintenance event on that single link causes an outage.</p>", "<p>Two connections in the same metro but different edge availability domains only qualifies for the 99.9% SLA tier, not 99.99%, because true 99.99% requires geographic diversity across different metro locations.</p>", "<p>A Cloud VPN failover path is encrypted and routed over the public internet, which violates the requirement that traffic never traverse the public internet, even though Partner Interconnect itself does not use the public internet.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's Shared VPC host project \"host-prod\" connects to on-premises data centers via Dedicated Interconnect using a Cloud Router with dynamic (BGP) routing. Separately, host-prod has a VPC Network Peering connection to a partner organization's VPC, \"partner-vpc\", established for a joint analytics workload. The partner now needs their VMs in partner-vpc to reach on-premises database servers through the existing peering connection to host-prod. Which approach correctly enables this connectivity, consistent with how Google Cloud VPC Network Peering handles routes?", "prompt": {"question": "<p>A company's Shared VPC host project \"host-prod\" connects to on-premises data centers via Dedicated Interconnect using a Cloud Router with dynamic (BGP) routing. Separately, host-prod has a VPC Network Peering connection to a partner organization's VPC, \"partner-vpc\", established for a joint analytics workload. The partner now needs their VMs in partner-vpc to reach on-premises database servers through the existing peering connection to host-prod. Which approach correctly enables this connectivity, consistent with how Google Cloud VPC Network Peering handles routes?</p>", "answers": ["<p>VPC Network Peering is fully transitive for all routes, so no additional configuration is needed — partner-vpc VMs already have access to the on-premises routes</p>", "<p>Manually create a static route in partner-vpc with the on-premises CIDR as the destination and the peering connection configured as the next hop</p>", "<p>Replace the existing VPC Network Peering connection with a direct Cloud VPN tunnel between partner-vpc and host-prod to carry the on-premises routes</p>", "<p>Enable custom route export on host-prod's side of the peering connection and custom route import on partner-vpc's side, so the on-premises routes learned dynamically via Cloud Router are shared with partner-vpc</p>"], "feedbacks": ["<p>Peering is transitive only for directly connected subnet routes shared by default; dynamically learned routes (from Interconnect/Cloud Router) require explicit custom route export/import — they are not shared automatically, so this statement is false</p>", "<p>There is no 'peering' next-hop type available for user-created static routes in Google Cloud; you cannot manually point a static route at a peering connection — route exchange over peering is controlled only through the custom route export/import settings on the peering configuration itself</p>", "<p>Replacing the peering connection with a VPN is unnecessary, disruptive to the existing analytics workload connectivity, and doesn't leverage the native custom route exchange capability that peering already supports for this exact use case</p>", "<p>VPC Network Peering only auto-shares each network's own subnet routes by default. Routes learned dynamically via Cloud Router (from Interconnect or VPN) are custom routes and are NOT propagated across a peering connection unless you explicitly enable 'export custom routes' on the side that owns the routes (host-prod) and 'import custom routes' on the receiving side (partner-vpc). This is a documented, exam-relevant nuance distinct from basic subnet-route sharing.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company stores sensitive datasets in BigQuery within a shared VPC across multiple projects. Security team must prevent any GCP identity from copying data out of the org's BigQuery datasets into external projects or exporting it, while still permitting an on-premises fraud-detection application (connected via Dedicated Interconnect) to query the data. Which approach BEST meets these requirements?", "prompt": {"question": "<p>A financial services company stores sensitive datasets in BigQuery within a shared VPC across multiple projects. Security team must prevent any GCP identity from copying data out of the org's BigQuery datasets into external projects or exporting it, while still permitting an on-premises fraud-detection application (connected via Dedicated Interconnect) to query the data. Which approach BEST meets these requirements?</p>", "answers": ["<p>Configure IAM Conditions on the BigQuery datasets to restrict the bigquery.tables.export permission for all users</p>", "<p>Create a VPC Service Controls perimeter around the projects containing the BigQuery datasets, with an access level that requires the corporate on-prem IP range reachable via Interconnect</p>", "<p>Enable Cloud DLP inspection jobs on the datasets to automatically redact sensitive fields before queries run</p>", "<p>Apply an Organization Policy constraint restricting the allowed resource locations for the datasets</p>"], "feedbacks": ["<p>IAM Conditions can restrict specific API calls but don't create a comprehensive exfiltration boundary across all data-movement paths (e.g., cross-project copy jobs, client library access) the way a service perimeter does.</p>", "<p>VPC Service Controls creates a service perimeter around BigQuery (and other supported APIs) that blocks data exfiltration to resources outside the perimeter, regardless of IAM permissions. An access level scoped to the on-prem IP range allows the Interconnect-based application through while blocking copy/export to external projects.</p>", "<p>Cloud DLP inspects and can redact sensitive content, but it does not prevent data from being copied or exported to unauthorized projects — it's a classification/redaction tool, not a perimeter control.</p>", "<p>Resource location constraints control where new resources can be created (data residency), not whether existing data can be exfiltrated to other projects.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A healthcare organization must use encryption keys that are generated and remain stored entirely within their own on-premises hardware security module (HSM), while still allowing Google Cloud services such as BigQuery and Compute Engine to perform encryption operations using those keys via API calls. Google must never have access to the raw key material at any point. Which key management approach should the architect select?", "prompt": {"question": "<p>A healthcare organization must use encryption keys that are generated and remain stored entirely within their own on-premises hardware security module (HSM), while still allowing Google Cloud services such as BigQuery and Compute Engine to perform encryption operations using those keys via API calls. Google must never have access to the raw key material at any point. Which key management approach should the architect select?</p>", "answers": ["<p>Cloud External Key Manager (Cloud EKM) integrated with a supported external key management partner</p>", "<p>Customer-managed encryption keys (CMEK) using Cloud KMS</p>", "<p>Customer-supplied encryption keys (CSEK) passed with each API request</p>", "<p>Google-managed default encryption at rest</p>"], "feedbacks": ["<p>Cloud EKM lets Google Cloud services call out to an external, customer-controlled key manager (including on-prem HSM-backed partners) at the time of each cryptographic operation, so the raw key material never resides inside Google Cloud infrastructure while still supporting services like BigQuery and Compute Engine.</p>", "<p>CMEK keys are generated and stored inside Cloud KMS, which runs on Google infrastructure — the key material would still reside within Google's environment, violating the requirement.</p>", "<p>CSEK requires the caller to supply the raw key with every request and is only supported by a limited set of services (primarily Compute Engine persistent disks and Cloud Storage) — it doesn't scale to BigQuery and isn't the standard 'never leaves on-prem HSM' solution.</p>", "<p>Google-managed encryption gives the customer no control over key material at all, which is the opposite of what's required.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An architect wants to enforce, at the organization level, that no Compute Engine VM instance anywhere in the resource hierarchy can ever be assigned an external (public) IP address, with no project able to override this. Which Organization Policy constraint should be enforced?", "prompt": {"question": "<p>An architect wants to enforce, at the organization level, that no Compute Engine VM instance anywhere in the resource hierarchy can ever be assigned an external (public) IP address, with no project able to override this. Which Organization Policy constraint should be enforced?</p>", "answers": ["<p>constraints/compute.vmExternalIpAccess set to deny all</p>", "<p>constraints/compute.requireOsLogin</p>", "<p>constraints/compute.restrictVpcPeering</p>", "<p>constraints/iam.disableServiceAccountKeyCreation</p>"], "feedbacks": ["<p>constraints/compute.vmExternalIpAccess is the specific Organization Policy constraint that controls which VM instances (if any) may be assigned external IP addresses; setting it to deny-all at the org node and inheriting down enforces the requirement with no project-level override.</p>", "<p>requireOsLogin controls whether OS Login is mandated for SSH access management — it has nothing to do with public IP assignment.</p>", "<p>restrictVpcPeering controls which projects a VPC can peer with, not whether instances get external IPs.</p>", "<p>disableServiceAccountKeyCreation prevents creation of user-managed service account keys — unrelated to networking/public IP exposure.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A DevOps team runs its CI/CD pipeline in GitHub Actions and needs to deploy resources to Google Cloud. The security team mandates that no long-lived service account keys may be downloaded or stored as CI/CD secrets. Which solution allows GitHub Actions to authenticate to Google Cloud securely while meeting this requirement?", "prompt": {"question": "<p>A DevOps team runs its CI/CD pipeline in GitHub Actions and needs to deploy resources to Google Cloud. The security team mandates that no long-lived service account keys may be downloaded or stored as CI/CD secrets. Which solution allows GitHub Actions to authenticate to Google Cloud securely while meeting this requirement?</p>", "answers": ["<p>Generate a service account key, base64-encode it, and store it as an encrypted GitHub Actions secret</p>", "<p>Configure Workload Identity Federation to establish trust between GitHub's OIDC token issuer and a Google Cloud service account, exchanging short-lived tokens</p>", "<p>Grant the GitHub Actions runner's static IP address access through a firewall rule and authenticate using a shared service account password</p>", "<p>Use Identity-Aware Proxy to allow unauthenticated access from GitHub's published IP ranges</p>"], "feedbacks": ["<p>This is exactly the practice the security team prohibited: a long-lived downloadable key stored as a secret, which creates ongoing exfiltration and rotation risk.</p>", "<p>Workload Identity Federation allows an external identity provider (GitHub's OIDC issuer) to be trusted directly, so the pipeline exchanges a short-lived OIDC token for a short-lived Google Cloud credential impersonating a service account — no long-lived key is ever created, stored, or downloaded.</p>", "<p>Google Cloud service accounts don't authenticate via 'passwords', and IP-based allowlisting is not a supported or secure authentication mechanism for API access.</p>", "<p>IAP is designed to protect access to web apps/VMs for human users behind a load balancer or SSH; it is not a mechanism for CI/CD pipelines to authenticate to Google Cloud APIs.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Before loading customer support chat transcripts into BigQuery for analytics, a company needs to automatically identify and mask credit card numbers, email addresses, and phone numbers embedded in free-form text, without manually writing regex patterns for every possible format. Which Google Cloud service should be used in the data pipeline?", "prompt": {"question": "<p>Before loading customer support chat transcripts into BigQuery for analytics, a company needs to automatically identify and mask credit card numbers, email addresses, and phone numbers embedded in free-form text, without manually writing regex patterns for every possible format. Which Google Cloud service should be used in the data pipeline?</p>", "answers": ["<p>Cloud Data Loss Prevention (Cloud DLP) API using built-in infoType detectors</p>", "<p>Cloud Armor with custom WAF rules</p>", "<p>BigQuery column-level security using policy tags</p>", "<p>Cloud KMS envelope encryption applied to the entire transcript field</p>"], "feedbacks": ["<p>Cloud DLP provides pre-built infoType detectors (CREDIT_CARD_NUMBER, EMAIL_ADDRESS, PHONE_NUMBER, etc.) that use pattern matching, context, and checksums to find sensitive data in free text and can automatically de-identify/mask it as part of an ingestion pipeline — no custom regex required.</p>", "<p>Cloud Armor protects HTTP(S) load balancers from web attacks (DDoS, SQLi, XSS) — it has no capability to inspect or redact content within a data pipeline.</p>", "<p>Policy tags control who can view specific BigQuery columns after the data is loaded; they don't detect or mask PII embedded within unstructured free-text fields.</p>", "<p>KMS encryption protects the entire field at rest/in transit but doesn't identify or selectively mask specific PII patterns within the text — encrypting the whole field also breaks the ability to analyze non-sensitive parts of the transcript.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An architect is designing IAM policies for a large enterprise with hundreds of engineers across dozens of teams. Following least-privilege best practices, which approach should be used to grant engineers only the permissions they need for their job function, avoiding both overly broad primitive roles and the excessive maintenance overhead of building fully custom roles for every function?", "prompt": {"question": "<p>An architect is designing IAM policies for a large enterprise with hundreds of engineers across dozens of teams. Following least-privilege best practices, which approach should be used to grant engineers only the permissions they need for their job function, avoiding both overly broad primitive roles and the excessive maintenance overhead of building fully custom roles for every function?</p>", "answers": ["<p>Grant the primitive Editor role to every engineer at the project level, since it covers most day-to-day needs</p>", "<p>Assign predefined IAM roles that closely map to job functions (e.g., roles/bigquery.dataViewer, roles/compute.instanceAdmin.v1), reserving custom roles only for specific gaps</p>", "<p>Create a fully custom IAM role for every distinct job function across the organization</p>", "<p>Grant the Owner role to all engineers but restrict its effect using Organization Policy constraints</p>"], "feedbacks": ["<p>Editor grants broad read/write access across nearly all resource types in a project, far exceeding least-privilege needs for most job functions.</p>", "<p>Predefined roles are curated, service-specific bundles of permissions maintained by Google that align closely to common job functions, giving finer granularity than primitive roles without the ongoing maintenance burden of managing fully custom roles for every use case — custom roles are reserved for narrow gaps predefined roles don't cover.</p>", "<p>Fully custom roles for every function create significant ongoing maintenance overhead (tracking permission changes across GCP service updates) and are only recommended when predefined roles don't fit.</p>", "<p>Organization Policy constraints govern resource configuration behavior (e.g., allowed locations, external IPs) — they do not scope down or restrict what an IAM role like Owner grants; Owner still confers near-full project control.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A healthcare company's BigQuery datasets and Cloud Storage buckets span 12 projects inside a single GCP organization. A compliance audit requires that no user or service, even one with valid IAM permissions on the resources, can copy or export regulated data to any resource outside the organization's projects. Analysts must still be able to run cross-project queries within the org, and a research team connecting from an on-premises data center over Cloud Interconnect must retain query access. Which design meets these requirements?", "prompt": {"question": "<p>A healthcare company's BigQuery datasets and Cloud Storage buckets span 12 projects inside a single GCP organization. A compliance audit requires that no user or service, even one with valid IAM permissions on the resources, can copy or export regulated data to any resource outside the organization's projects. Analysts must still be able to run cross-project queries within the org, and a research team connecting from an on-premises data center over Cloud Interconnect must retain query access. Which design meets these requirements?</p>", "answers": ["<p>Apply the Organization Policy constraint iam.allowedPolicyMemberDomains to block granting IAM roles to external identities, and rely on default IAM permissions for cross-project queries</p>", "<p>Enable Cloud DLP inspection templates on all BigQuery datasets to automatically redact sensitive fields before any export job can complete</p>", "<p>Create a single VPC Service Controls perimeter containing all 12 projects, define an access level scoped to the on-prem IP range and corporate device policy for Interconnect access, and let the perimeter block API calls that would move data to resources outside it</p>", "<p>Enable customer-managed encryption keys (CMEK) via Cloud KMS on every BigQuery dataset and Cloud Storage bucket so that only key-holders in the org can decrypt exported data</p>"], "feedbacks": ["<p>Domain-restricted sharing only controls who can be granted IAM roles (blocking grants to non-org identities); it does not stop an already-authorized insider from copying data to a project outside the perimeter that they still have legitimate access to.</p>", "<p>Cloud DLP redacts or classifies sensitive data fields but doesn't block data movement itself; a full unredacted export could still occur unless DLP is wired into a blocking workflow, and it doesn't address the org-boundary exfiltration requirement.</p>", "<p>VPC Service Controls creates a security perimeter around resources so that even users/service accounts with legitimate IAM permissions cannot exfiltrate data to services or projects outside the perimeter via APIs (copy, export, etc.). Access levels let you allow specific trusted network sources — like an on-prem range reaching in via Cloud Interconnect — to access resources inside the perimeter without weakening the exfiltration protection.</p>", "<p>CMEK protects data at rest from unauthorized decryption if keys are compromised, but any user already authorized to read the decrypted data (which is the normal case for legitimate analysts) can still export it outside the org; CMEK does not enforce network/API-level exfiltration boundaries.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company's CI/CD pipeline runs on GitHub Actions and needs to deploy resources to a GCP project. The security team's compliance policy prohibits storing any long-lived, downloadable service account keys anywhere, including in secret managers, and requires that all machine-to-machine authentication to GCP be short-lived and auditable per pipeline run. Which configuration satisfies this requirement?", "prompt": {"question": "<p>A company's CI/CD pipeline runs on GitHub Actions and needs to deploy resources to a GCP project. The security team's compliance policy prohibits storing any long-lived, downloadable service account keys anywhere, including in secret managers, and requires that all machine-to-machine authentication to GCP be short-lived and auditable per pipeline run. Which configuration satisfies this requirement?</p>", "answers": ["<p>Configure Workload Identity Federation to trust GitHub Actions' OIDC token issuer, mapping specific repository/branch claims to permission to impersonate a dedicated GCP service account with no key ever created</p>", "<p>Generate a service account key, store it as an encrypted GitHub Actions secret, and configure a Cloud Scheduler job to rotate the key automatically every 24 hours</p>", "<p>Deploy Identity-Aware Proxy in front of the deployment target and require the pipeline to authenticate through the IAP OAuth consent flow using a shared client secret</p>", "<p>Create a service account key, store it in Secret Manager with a 90-day expiration label, and configure an IAM Conditions policy that denies use of the key after 90 days</p>"], "feedbacks": ["<p>Workload Identity Federation lets an external OIDC-compliant identity (like GitHub Actions' built-in OIDC token, scoped to specific repo/branch claims) exchange its token for short-lived GCP credentials via impersonation of a service account — no service account key is ever generated, stored, or rotated, and each exchange is tied to a specific workflow run for auditability.</p>", "<p>Even with rotation, this still creates and stores a downloadable long-lived service account key at some point, directly violating the 'no long-lived key' compliance requirement, and rotation via Cloud Scheduler doesn't eliminate the key material itself.</p>", "<p>Identity-Aware Proxy is designed to protect access to web applications and HTTP(S) endpoints for human/browser-based authentication; it is not the mechanism for authenticating a CI/CD pipeline's API calls to deploy GCP resources, and a shared client secret is itself a long-lived credential.</p>", "<p>IAM Conditions can restrict when a credential is usable, but a service account key is still created and stored (even if labeled with an expiration), which is exactly the long-lived key artifact the policy prohibits — labels don't enforce actual key deactivation.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "After a major production outage, a Cloud Architect is asked to design the incident review process going forward. The goal is to determine root cause accurately, avoid repeat incidents, and maintain team trust so future issues are reported quickly. Which approach best achieves this?", "prompt": {"question": "<p>After a major production outage, a Cloud Architect is asked to design the incident review process going forward. The goal is to determine root cause accurately, avoid repeat incidents, and maintain team trust so future issues are reported quickly. Which approach best achieves this?</p>", "answers": ["<p>Have engineering leadership hold a closed-door meeting to identify which individual caused the outage and note it in their performance review</p>", "<p>Skip formal documentation since the incident was resolved within the SLA window, relying on the team's Slack history as the record</p>", "<p>Have the on-call SRE write a purely technical log summary with no stakeholder communication or action-item tracking</p>", "<p>Conduct a blameless postmortem documenting the incident timeline, contributing factors, customer impact, and specific remediation action items with owners and due dates, then track them to closure</p>"], "feedbacks": ["<p>Assigning individual blame discourages transparency and future incident reporting, and does not address systemic causes — this is explicitly the anti-pattern the exam tests against</p>", "<p>Skipping documentation loses the timeline and root-cause analysis needed to prevent recurrence, and Slack history is not a durable or structured record for stakeholders or compliance</p>", "<p>Omitting stakeholder communication and action-item tracking means fixes are never verified as implemented, allowing the same failure to recur</p>", "<p>Blameless postmortems focused on systemic contributing factors (not individual blame) with tracked action items are the standard SRE/PCA practice for continuous improvement — they surface true root causes and encourage future incident reporting rather than concealment.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A company with a 3-person platform team must retain application logs for 2 years to satisfy compliance audits and support ad hoc analytical queries from the compliance team. Which approach best balances time-to-value and total cost of ownership?", "prompt": {"question": "<p>A company with a 3-person platform team must retain application logs for 2 years to satisfy compliance audits and support ad hoc analytical queries from the compliance team. Which approach best balances time-to-value and total cost of ownership?</p>", "answers": ["<p>Build and operate self-managed Elasticsearch clusters on Compute Engine to retain full control over indexing and query performance</p>", "<p>Store raw logs in Cloud Storage and write a new custom Dataflow job every time the compliance team requests a different query pattern</p>", "<p>Have the platform team develop a proprietary log indexing and search engine in-house to avoid recurring vendor costs</p>", "<p>Route logs through Cloud Logging, configure a log sink to export them to BigQuery, and use standard SQL for compliance reporting and ad hoc analysis</p>"], "feedbacks": ["<p>Self-managed Elasticsearch requires significant ongoing operational effort (patching, scaling, tuning) that a 3-person team cannot sustain alongside other duties</p>", "<p>Writing bespoke Dataflow jobs per query defeats the purpose of ad hoc analysis and creates high engineering overhead for every compliance request</p>", "<p>Building a proprietary search engine is a major multi-year engineering investment far exceeding the cost and risk of using an existing managed analytics service</p>", "<p>With a small team and a defined 2-year retention need, using managed Cloud Logging sinks into BigQuery gives fast time-to-value, low operational burden, and native SQL ad hoc querying — a clear 'buy/use managed service' win given limited engineering headcount.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "A financial services company must satisfy regulatory requirements for documented, auditable approval of every production change while also increasing deployment frequency. Which process should the architect recommend?", "prompt": {"question": "<p>A financial services company must satisfy regulatory requirements for documented, auditable approval of every production change while also increasing deployment frequency. Which process should the architect recommend?</p>", "answers": ["<p>Implement a CI/CD pipeline in Cloud Build with automated testing, a required manual approval gate before the production deployment step, and Binary Authorization to enforce that only attested, policy-compliant container images can deploy</p>", "<p>Continue quarterly release cycles where every change, regardless of risk, is manually reviewed by a change advisory board (CAB) before release</p>", "<p>Allow developers to deploy directly to production using gcloud, relying on Cloud Audit Logs for after-the-fact review</p>", "<p>Route every code change through the CFO for manual sign-off before it can be merged, since this is a regulated financial company</p>"], "feedbacks": ["<p>An automated CI/CD pipeline with an enforced approval gate and Binary Authorization satisfies auditable change control (every deployment is traceable and gated) while enabling much higher deployment frequency than manual quarterly reviews — directly balancing compliance and velocity.</p>", "<p>Quarterly CAB review for every change regardless of risk severely limits deployment frequency and does not scale with modern delivery expectations</p>", "<p>Direct production deploys with only after-the-fact audit logging provides no preventive control and fails regulatory requirements for pre-deployment approval</p>", "<p>Requiring CFO sign-off on every code merge is operationally infeasible and conflates financial oversight with technical change control, unrelated to the actual regulatory requirement</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "Utilization analysis shows a workload has a stable baseline of 20 vCPUs running continuously plus predictable business-hours bursts up to 60 vCPUs. Which cost optimization strategy best fits this pattern?", "prompt": {"question": "<p>Utilization analysis shows a workload has a stable baseline of 20 vCPUs running continuously plus predictable business-hours bursts up to 60 vCPUs. Which cost optimization strategy best fits this pattern?</p>", "answers": ["<p>Purchase a 1-year Committed Use Discount sized for the full 60 vCPU peak and run that capacity flat at all times</p>", "<p>Purchase a 1-year Committed Use Discount for the 20 vCPU baseline, and configure a managed instance group with autoscaling to burst up to 60 vCPUs on-demand during peak hours</p>", "<p>Run the entire workload on preemptible/Spot VMs to minimize cost, regardless of the workload's availability requirements</p>", "<p>Avoid any commitment and pay on-demand pricing continuously for the full 60 vCPU peak capacity to preserve maximum flexibility</p>"], "feedbacks": ["<p>Committing to the full peak wastes money paying for 40 vCPUs of committed capacity that is unused most of the day</p>", "<p>Committing the stable, continuously-used baseline (20 vCPUs) locks in the discount where usage is guaranteed, while autoscaling on-demand capacity for the variable burst avoids paying for committed capacity that sits idle outside business hours — this is the standard CUD + autoscaling cost pattern tested on the exam.</p>", "<p>Spot/preemptible VMs can be reclaimed at any time, which is inappropriate if the workload has any availability requirement during business-hour bursts, and doesn't optimize the steady baseline discount opportunity</p>", "<p>Paying full on-demand rates for the entire peak continuously ignores the guaranteed baseline usage that qualifies for a substantial committed-use discount, unnecessarily raising cost</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "Product management is pushing for rapid feature delivery while the engineering team reports that accumulating technical debt in the monolithic application is slowing development and increasing incident rates. Which recommendation best balances these competing priorities?", "prompt": {"question": "<p>Product management is pushing for rapid feature delivery while the engineering team reports that accumulating technical debt in the monolithic application is slowing development and increasing incident rates. Which recommendation best balances these competing priorities?</p>", "answers": ["<p>Halt all new feature development for two quarters to fully rewrite the monolith as microservices before resuming feature work</p>", "<p>Ignore the technical debt concerns and dedicate all engineering capacity to new features to meet business deadlines</p>", "<p>Establish a policy reserving a fixed percentage of each sprint's capacity for addressing critical technical debt items, prioritized by risk and incident impact, while continuing incremental feature delivery</p>", "<p>Let individual engineers refactor code informally whenever they have spare time, without tracking debt items or measuring their impact</p>"], "feedbacks": ["<p>A full multi-quarter freeze on feature work is high risk, delays business value, and a full rewrite often introduces its own new defects and delays — rarely the recommended approach over incremental improvement</p>", "<p>Ignoring technical debt entirely leads to increasing incident rates and eventually slower delivery, which is the exact problem being reported and needs to be addressed</p>", "<p>A sustained, measured allocation of capacity to risk-prioritized technical debt alongside ongoing feature delivery is the standard approach for balancing business velocity against long-term system health — it prevents both stalled delivery and unchecked debt accumulation.</p>", "<p>Ad hoc, untracked refactoring has no visibility into whether the highest-risk debt is being addressed and provides no measurable progress to report to stakeholders</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization's engineering teams are siloed strictly by technical function (frontend, backend, operations) with no cross-training, and management wants to migrate the monolithic application to a microservices architecture. Which recommendation best reflects sound architectural guidance given the organizational constraints?", "prompt": {"question": "<p>An organization's engineering teams are siloed strictly by technical function (frontend, backend, operations) with no cross-training, and management wants to migrate the monolithic application to a microservices architecture. Which recommendation best reflects sound architectural guidance given the organizational constraints?</p>", "answers": ["<p>Migrate immediately to a fully decomposed microservices architecture, since this is considered current best practice regardless of team structure</p>", "<p>Recommend reorganizing engineering into small, cross-functional teams aligned to service boundaries before or alongside decomposition, and provide targeted training, since system architecture tends to mirror organizational communication structures</p>", "<p>Keep the monolith unchanged indefinitely, since reorganizing engineering teams falls outside a cloud architect's scope of responsibility</p>", "<p>Outsource the entire migration to a third-party contractor without involving internal teams, since the existing team structure cannot realistically change</p>"], "feedbacks": ["<p>Decomposing into microservices without addressing team structure typically results in services that still require cross-team coordination for every change, defeating the purpose of the migration</p>", "<p>Per Conway's Law and the exam's explicit coverage of aligning architecture with team/org constraints, a microservices migration is unlikely to succeed if the org structure and skills remain siloed by function; the architect should address the org and skills gap alongside the technical migration plan.</p>", "<p>Cloud architects are explicitly expected to weigh organizational and team constraints as part of solution design on this exam — org structure is in-scope, not out-of-scope</p>", "<p>Fully outsourcing without any internal involvement leaves the organization unable to operate or evolve the new architecture and does nothing to resolve the underlying skill/structure mismatch</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "An organization has adopted Google's SRE practices, including formal error budgets tied to a 99.9% availability SLO for a customer-facing API. This quarter, three separate production incidents caused by rushed deployments consumed the entire error budget by the second month of the quarter. Engineering leadership wants a recommendation that is consistent with SRE error budget policy and the organization's stated goal of balancing reliability with delivery speed. Which action should the cloud architect recommend?", "prompt": {"question": "<p>An organization has adopted Google's SRE practices, including formal error budgets tied to a 99.9% availability SLO for a customer-facing API. This quarter, three separate production incidents caused by rushed deployments consumed the entire error budget by the second month of the quarter. Engineering leadership wants a recommendation that is consistent with SRE error budget policy and the organization's stated goal of balancing reliability with delivery speed. Which action should the cloud architect recommend?</p>", "answers": ["<p>Raise the SLO target to 99.5% so future minor incidents no longer exhaust the error budget as quickly</p>", "<p>Halt new feature releases for the API and redirect the team's effort to reliability work until the error budget is restored</p>", "<p>Require the on-call engineer responsible for the most recent deploy to complete a formal disciplinary review before any further releases are approved</p>", "<p>Continue the existing release cadence since the product roadmap commitments to customers take priority over the internal error budget metric</p>"], "feedbacks": ["<p>Arbitrarily lowering the SLO to make the metric easier to hit undermines the entire purpose of error budgets, which are meant to reflect a real user-experience commitment agreed with stakeholders, not be adjusted reactively to avoid consequences.</p>", "<p>The core mechanism of an error budget policy is that when the budget is exhausted, feature velocity is throttled and the team's priority shifts to reliability improvements until the budget recovers. This directly ties technical process (release management) to the agreed business/technical trade-off codified in the SLO.</p>", "<p>SRE culture explicitly practices blameless postmortems; assigning individual blame and requiring disciplinary action contradicts the psychological safety principle needed for honest incident analysis and process improvement.</p>", "<p>Ignoring an exhausted error budget defeats its purpose as a governance mechanism; the entire point of the policy is that it triggers a real change in team behavior (slowing releases), not just tracking a number stakeholders can override at will.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A retail company runs its CI/CD pipeline on a self-managed Jenkins cluster hosted on Compute Engine. The two-person platform team spends over 50% of its time patching Jenkins plugins for recurring CVEs and manually scaling build agents during peak release periods. Business stakeholders have set a goal of cutting time-to-market for new features by 40% this year, but the company has no budget approved to grow the platform team. Which change best optimizes the technical process while respecting the stated business and staffing constraints?", "prompt": {"question": "<p>A retail company runs its CI/CD pipeline on a self-managed Jenkins cluster hosted on Compute Engine. The two-person platform team spends over 50% of its time patching Jenkins plugins for recurring CVEs and manually scaling build agents during peak release periods. Business stakeholders have set a goal of cutting time-to-market for new features by 40% this year, but the company has no budget approved to grow the platform team. Which change best optimizes the technical process while respecting the stated business and staffing constraints?</p>", "answers": ["<p>Migrate the pipeline to a Google Cloud managed CI/CD service such as Cloud Build, removing the operational burden of patching and scaling the underlying build infrastructure</p>", "<p>Re-architect Jenkins to run on a self-managed GKE cluster so build agents can autoscale more elastically than on Compute Engine VMs</p>", "<p>Request approval to hire two additional DevOps engineers dedicated to patching Jenkins plugins and managing agent capacity</p>", "<p>Introduce a formal change advisory board that reviews and approves every Jenkins plugin update before it is applied to production</p>"], "feedbacks": ["<p>Moving to a managed CI/CD service eliminates the recurring toil of patching and manual scaling, directly freeing the platform team's time to focus on delivery work, which aligns with both the stated business goal (faster time-to-market) and the hard staffing constraint (no budget for new headcount).</p>", "<p>Moving Jenkins onto self-managed GKE still leaves the team responsible for patching Jenkins itself and now adds Kubernetes cluster operations on top, increasing rather than reducing operational toil.</p>", "<p>The scenario explicitly states no budget exists to grow the platform team, making this option infeasible regardless of its technical merit, and it does not eliminate the root cause of the toil.</p>", "<p>Adding a change advisory board for every plugin update adds process overhead and slows down patching and releases further, which works against the stated goal of reducing time-to-market and does not address the underlying maintenance burden.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A team uses Cloud Deploy to progressively roll out a new microservice version across dev, staging, and prod GKE clusters. During the canary phase in prod, they want the rollout to automatically halt and roll back if the service's error rate exceeds an SLO threshold defined in Cloud Monitoring — without any human intervention. Which approach BEST satisfies this requirement?", "prompt": {"question": "<p>A team uses Cloud Deploy to progressively roll out a new microservice version across dev, staging, and prod GKE clusters. During the canary phase in prod, they want the rollout to automatically halt and roll back if the service's error rate exceeds an SLO threshold defined in Cloud Monitoring — without any human intervention. Which approach BEST satisfies this requirement?</p>", "answers": ["<p>Configure the GKE Horizontal Pod Autoscaler to automatically remove pods that report HTTP 500 responses during the canary phase.</p>", "<p>Add a postdeploy hook to the canary phase that queries Cloud Monitoring for the error-rate SLO and fails the phase if it is breached, combined with Cloud Deploy's rollback-on-failure setting.</p>", "<p>Create a nightly Cloud Build trigger that redeploys the previous stable container image to production.</p>", "<p>Have the on-call engineer watch the Cloud Monitoring dashboard during the rollout and manually trigger a rollback from the console if needed.</p>"], "feedbacks": ["<p>HPA reacts to CPU/memory or custom metrics for scaling, not for evaluating SLO breaches or triggering a deployment rollback.</p>", "<p>Cloud Deploy supports custom postdeploy (and predeploy) hooks that can run verification logic, such as querying a Cloud Monitoring SLO/alert condition. If the hook exits non-zero, the phase is marked failed, which — combined with Cloud Deploy's automatic rollback-on-failure configuration — prevents promotion and rolls back without manual action.</p>", "<p>A nightly redeploy is not real-time and does not react to the canary phase's live error rate; it's reactive, not automated rollback logic.</p>", "<p>Manual dashboard watching fails the stated requirement of a fully automated, no-human-intervention rollback.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["b"]}, {"assessment_type": "multiple-choice", "question_plain": "A platform team wants to manage core GCP infrastructure (VPCs, subnets, IAM policy bindings) using Kubernetes-style YAML manifests that are continuously reconciled by a controller running inside a GKE cluster, fitting into an existing GitOps workflow. Which tool should they use?", "prompt": {"question": "<p>A platform team wants to manage core GCP infrastructure (VPCs, subnets, IAM policy bindings) using Kubernetes-style YAML manifests that are continuously reconciled by a controller running inside a GKE cluster, fitting into an existing GitOps workflow. Which tool should they use?</p>", "answers": ["<p>Cloud Deployment Manager</p>", "<p>Terraform Cloud with manual apply approvals</p>", "<p>Cloud Asset Inventory with a Pub/Sub feed</p>", "<p>Config Connector (KCC) running in the GKE cluster</p>"], "feedbacks": ["<p>Deployment Manager is a deprecated, apply-once declarative tool with no continuous in-cluster reconciliation loop.</p>", "<p>Terraform with manual approvals is apply-driven (one-time runs), not a continuously reconciling controller, and doesn't natively use Kubernetes manifests.</p>", "<p>Cloud Asset Inventory only provides visibility/inventory of resources; it does not provision or reconcile infrastructure.</p>", "<p>Config Connector installs as a Kubernetes CRD controller in GKE and continuously reconciles GCP resources defined as Kubernetes manifests, which is exactly the GitOps-style, controller-driven reconciliation model described.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "Multiple engineers on a team run Terraform against the same GCP project. They occasionally run 'terraform apply' at the same time, resulting in corrupted state files. Which change to their Terraform configuration BEST prevents this going forward?", "prompt": {"question": "<p>Multiple engineers on a team run Terraform against the same GCP project. They occasionally run 'terraform apply' at the same time, resulting in corrupted state files. Which change to their Terraform configuration BEST prevents this going forward?</p>", "answers": ["<p>Store the Terraform state file in a version-controlled Git repository alongside the configuration files.</p>", "<p>Migrate the state to a Cloud SQL for PostgreSQL instance and use row-level locks.</p>", "<p>Configure a GCS bucket as the Terraform backend; the GCS backend natively provides state locking to prevent concurrent applies.</p>", "<p>Switch from Terraform to Cloud Deployment Manager, which does not require external state locking.</p>"], "feedbacks": ["<p>Git storage of state has no locking mechanism and is explicitly discouraged since state may contain secrets and Git doesn't prevent concurrent writes.</p>", "<p>Terraform does not natively support a Cloud SQL backend for state; this is not a valid or supported configuration.</p>", "<p>The GCS backend for Terraform state uses object generation preconditions to implement locking automatically — when one apply is running, a second concurrent apply will fail to acquire the lock, preventing state corruption.</p>", "<p>Switching tools doesn't address the underlying need to keep using Terraform, and doesn't map to a supported, minimal fix.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "An architecture team suspects engineers have been making manual changes to a GKE cluster's configuration directly through the Cloud Console, causing drift from the Terraform-managed definition. Which approach BEST detects and systematically prevents this drift going forward?", "prompt": {"question": "<p>An architecture team suspects engineers have been making manual changes to a GKE cluster's configuration directly through the Cloud Console, causing drift from the Terraform-managed definition. Which approach BEST detects and systematically prevents this drift going forward?</p>", "answers": ["<p>Enable a Cloud Asset Inventory feed to log all IAM and resource changes for later auditing.</p>", "<p>Switch the cluster to GKE Autopilot mode so Google manages all node-level configuration.</p>", "<p>Instruct engineers to notify the platform team by email whenever they make a manual change in the console.</p>", "<p>Schedule terraform plan to run in a CI pipeline on a recurring basis to detect drift, and restrict direct edit permissions on the cluster to the automation service account only.</p>"], "feedbacks": ["<p>An asset inventory feed only logs changes after the fact; it doesn't detect drift against the Terraform state or prevent future manual edits.</p>", "<p>Autopilot manages node-level infrastructure but does not prevent console-level changes to cluster-level settings managed by Terraform.</p>", "<p>Relying on manual email notification is not systematic or enforceable and doesn't scale.</p>", "<p>Scheduled terraform plan runs surface any drift between actual and declared state, giving early detection, while restricting IAM edit permissions on the cluster to only the automation service account enforces that all future changes must go through the pipeline — addressing both detection and prevention.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}, {"assessment_type": "multiple-choice", "question_plain": "An architect wants to deploy a new App Engine service version so it can be validated at its version-specific URL before any production traffic is routed to it. Which gcloud app deploy flag achieves this?", "prompt": {"question": "<p>An architect wants to deploy a new App Engine service version so it can be validated at its version-specific URL before any production traffic is routed to it. Which gcloud app deploy flag achieves this?</p>", "answers": ["<p>--quiet</p>", "<p>--stop-previous-version</p>", "<p>--no-promote</p>", "<p>--version=v2</p>"], "feedbacks": ["<p>--quiet only suppresses interactive prompts; it has no effect on traffic routing.</p>", "<p>--stop-previous-version stops the old version's instances, which is unrelated to controlling traffic to the new version and can be disruptive if done prematurely.</p>", "<p>The --no-promote flag deploys the new version without automatically routing production traffic to it, allowing testing via the version-specific URL before manually promoting it with traffic splitting.</p>", "<p>--version just assigns a name/ID to the deployed version; by default deploying still promotes it to receive all traffic unless --no-promote is also specified.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A company has an SLO of 99.95% availability for its public API measured over a rolling 28-day window. Monitoring shows the current burn rate will exhaust the entire error budget in 3 days. The product team wants to ship a major new feature this week that adds significant new code paths to the same service. What should the architect recommend?", "prompt": {"question": "<p>A company has an SLO of 99.95% availability for its public API measured over a rolling 28-day window. Monitoring shows the current burn rate will exhaust the entire error budget in 3 days. The product team wants to ship a major new feature this week that adds significant new code paths to the same service. What should the architect recommend?</p>", "answers": ["<p>Halt non-critical feature launches and prioritize reliability engineering work until the error budget recovers</p>", "<p>Redefine the SLI measurement window from 28 days to 90 days to reset the error budget calculation</p>", "<p>Proceed with the launch since the current availability still satisfies the customer-facing SLA, which is lower than the SLO</p>", "<p>Increase the SLO target to 99.99% availability to create additional error-budget headroom for future incidents</p>"], "feedbacks": ["<p>This is the standard SRE error-budget policy: when the burn rate indicates the budget will be exhausted, feature launches that add risk are paused and engineering effort shifts to reliability work until the budget recovers. This protects users while still allowing normal release velocity once risk decreases.</p>", "<p>Changing the measurement window to game the calculation doesn't reduce actual risk to users and is considered manipulating the metric rather than managing reliability.</p>", "<p>The SLA is a contractual, looser threshold than the SLO; satisfying the SLA does not mean the SLO commitment to users is honored, and shipping risky code while burning budget increases the chance of an SLA breach too.</p>", "<p>Raising the SLO target tightens the requirement and shrinks the error budget further — it moves in the wrong direction and would make the current burn rate worse, not better.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "A critical OLTP workload currently runs on a single-region Cloud SQL for PostgreSQL instance. The business now requires an RPO of 5 minutes and an RTO of 15 minutes in the event of a full regional outage, with minimal ongoing operational overhead. Which approach best meets these requirements?", "prompt": {"question": "<p>A critical OLTP workload currently runs on a single-region Cloud SQL for PostgreSQL instance. The business now requires an RPO of 5 minutes and an RTO of 15 minutes in the event of a full regional outage, with minimal ongoing operational overhead. Which approach best meets these requirements?</p>", "answers": ["<p>Configure a cross-region read replica for Cloud SQL and manually promote it during a regional outage</p>", "<p>Rely on Cloud SQL automated backups with point-in-time recovery restored to a new instance in another region</p>", "<p>Migrate the workload to Cloud Spanner configured as a multi-region instance</p>", "<p>Set up a nightly cross-region database dump-and-restore process to a standby Cloud SQL instance</p>"], "feedbacks": ["<p>Cloud SQL cross-region read replicas use asynchronous replication, so replication lag can exceed the 5-minute RPO during high load, and manual promotion adds operator-dependent delay that risks exceeding the 15-minute RTO.</p>", "<p>Restoring from automated backups/PITR only recovers to the last backup or log position and requires provisioning a new instance, which typically takes well over 15 minutes and can lose more than 5 minutes of data depending on backup frequency.</p>", "<p>Cloud Spanner multi-region configurations use synchronous, Paxos-based replication across regions, providing near-zero RPO and automatic failover with minimal manual intervention, comfortably meeting a 5-minute RPO and 15-minute RTO with low ongoing operational burden.</p>", "<p>A nightly dump-and-restore process has an RPO measured in hours, far exceeding the 5-minute requirement, regardless of how fast the restore itself runs.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A microservices application running on GKE experiences intermittent high latency on certain user requests. The team needs to visualize the full request path across multiple services and pinpoint exactly which downstream service call is adding the delay. Which tool should they use?", "prompt": {"question": "<p>A microservices application running on GKE experiences intermittent high latency on certain user requests. The team needs to visualize the full request path across multiple services and pinpoint exactly which downstream service call is adding the delay. Which tool should they use?</p>", "answers": ["<p>Enable Cloud Profiler on each microservice to capture CPU and memory usage</p>", "<p>Configure Cloud Monitoring dashboards with aggregated custom latency metrics per service</p>", "<p>Instrument the services with Cloud Trace to visualize per-request latency across the call graph</p>", "<p>Enable structured JSON logging in Cloud Logging and correlate log entries by request ID manually</p>"], "feedbacks": ["<p>Cloud Profiler analyzes CPU and memory consumption within a single service's code over time; it does not show the cross-service request path or per-hop latency.</p>", "<p>Aggregated custom metrics in Cloud Monitoring show trends over time per service but do not tie together a single request's journey across services, so isolating one problematic hop for one request is difficult.</p>", "<p>Cloud Trace is purpose-built for distributed tracing: it captures per-request latency data as a request flows through multiple services and renders the call graph so the specific slow hop can be identified directly.</p>", "<p>Manually correlating logs by request ID can theoretically work but is slow, error-prone, and doesn't provide the automatic timing/visualization that Cloud Trace gives out of the box — it's not the efficient, purpose-built solution.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A team runs several services on App Engine and Cloud Run. They want unhandled exceptions from all services automatically aggregated and grouped by root cause (deduplicating identical stack traces) and to be notified when a new error type first appears. Which Google Cloud tool is designed specifically for this?", "prompt": {"question": "<p>A team runs several services on App Engine and Cloud Run. They want unhandled exceptions from all services automatically aggregated and grouped by root cause (deduplicating identical stack traces) and to be notified when a new error type first appears. Which Google Cloud tool is designed specifically for this?</p>", "answers": ["<p>Error Reporting</p>", "<p>Cloud Trace</p>", "<p>Cloud Logging log-based metrics with alerting policies</p>", "<p>Security Command Center</p>"], "feedbacks": ["<p>Error Reporting automatically aggregates and groups exceptions across App Engine, Cloud Run, GKE, and Compute Engine by analyzing stack traces, deduplicates recurring errors, and can notify when a new error group is first detected — exactly matching the requirement.</p>", "<p>Cloud Trace focuses on distributed request latency and timing across services, not exception aggregation or stack trace grouping.</p>", "<p>Log-based metrics and alerts can be built manually to approximate this, but they require custom configuration for grouping/deduplication and don't natively cluster stack traces by root cause the way Error Reporting does automatically.</p>", "<p>Security Command Center is focused on security posture, vulnerabilities, and threat findings, not application exception handling.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["a"]}, {"assessment_type": "multiple-choice", "question_plain": "An architect needs to configure a canary release for a service running on GKE, routing approximately 5% of traffic to the new version. No service mesh (such as Istio/Anthos Service Mesh) is installed, and native Kubernetes objects must be used. Which configuration achieves this?", "prompt": {"question": "<p>An architect needs to configure a canary release for a service running on GKE, routing approximately 5% of traffic to the new version. No service mesh (such as Istio/Anthos Service Mesh) is installed, and native Kubernetes objects must be used. Which configuration achieves this?</p>", "answers": ["<p>Run kubectl rollout pause on the existing Deployment update to hold 5% of pods on the new revision</p>", "<p>Create a separate Ingress resource routing to a canary namespace</p>", "<p>Deploy the new version as a separate Deployment sharing the same Service label selector as the stable Deployment, and scale replica counts to approximate a 5% traffic ratio</p>", "<p>Configure a HorizontalPodAutoscaler to scale the canary Deployment to 5% of total replicas based on CPU utilization</p>"], "feedbacks": ["<p>kubectl rollout pause only pauses an in-place rolling update of a single Deployment; it does not create a controlled, sustained traffic split by percentage and isn't intended as a canary traffic-splitting mechanism.</p>", "<p>A separate Ingress pointing to a separate namespace routes based on host/path rules, not a percentage-based random traffic split, and by itself does not achieve a 5% weighted distribution.</p>", "<p>Without a service mesh, the standard native-Kubernetes canary pattern is to create two Deployments with identical pod labels matched by a single Service's selector. Since a Service load-balances round-robin across all matching pod endpoints, controlling the ratio of stable-to-canary replica counts (e.g., 19 stable pods and 1 canary pod) approximates the desired traffic percentage.</p>", "<p>An HPA scales pod replicas based on observed metrics like CPU utilization; it does not maintain a fixed traffic percentage and will drift as load changes, making it unsuitable for a controlled canary ratio.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["c"]}, {"assessment_type": "multiple-choice", "question_plain": "A production outage was caused by an engineer making a manual configuration change directly in production without following the documented change-management process. During the post-incident review, which action best aligns with Google's SRE blameless postmortem culture?", "prompt": {"question": "<p>A production outage was caused by an engineer making a manual configuration change directly in production without following the documented change-management process. During the post-incident review, which action best aligns with Google's SRE blameless postmortem culture?</p>", "answers": ["<p>Identify the engineer who made the unauthorized change and issue a formal written reprimand</p>", "<p>Restrict production deployment access to only senior engineers going forward</p>", "<p>Document the incident internally only if it breached the SLA, and keep the report private since it was resolved quickly</p>", "<p>Focus the review on the systemic process and tooling gaps that allowed an unreviewed change to reach production, and implement automated safeguards</p>"], "feedbacks": ["<p>Reprimanding the individual is the definition of a blame-focused postmortem, which discourages future incident transparency and doesn't address the underlying process gap that allowed the change through.</p>", "<p>Restricting access to only senior engineers is a blunt, punitive control that reduces team throughput without necessarily fixing the root cause (e.g., missing automated change validation) and can still allow the same mistake by a senior engineer.</p>", "<p>Postmortems should be conducted and shared regardless of SLA breach, and transparency/documentation is a core tenet of SRE culture — hiding or skipping reports based on impact severity undermines organizational learning.</p>", "<p>Blameless postmortems focus on identifying and fixing systemic weaknesses (e.g., lack of automated guardrails, insufficient change review enforcement) rather than assigning individual blame, since punishing individuals discourages honest reporting and doesn't prevent recurrence; the goal is durable, process-level fixes.</p>"], "relatedLectureIds": [], "links": []}, "correct_response": ["d"]}], "expected": 45}];
  const csrf=(document.cookie.match(/csrftoken=([^;]+)/)||[])[1];
  const H={'Content-Type':'application/json','X-Csrftoken':csrf,'Accept':'application/json'};
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const log=(...a)=>console.log('[PT-LOADER]',...a);
  const patch=(cid,qid,b)=>fetch(`/api-2.0/courses/${cid}/quizzes/${qid}/`,{method:'PATCH',headers:H,body:JSON.stringify(b)});
  let TOK=0,TFAIL=0;
  for(const t of TESTS){
    const list=await fetch(`/api-2.0/courses/${t.cid}/quizzes/?page_size=100&fields[quiz]=title,type,num_assessments`,{headers:H}).then(r=>r.json());
    const existing=(list.results||[]).find(q=>q.type==='practice-test'&&q.title===t.name);
    if(existing && existing.num_assessments>=t.expected){ log('SKIP complete:',t.name,existing.num_assessments,'Q'); await patch(t.cid,existing.id,{is_published:true}).catch(()=>{}); continue; }
    if(existing){ log('Delete incomplete:',t.name,existing.num_assessments,'Q'); await fetch(`/api-2.0/courses/${t.cid}/quizzes/${existing.id}/`,{method:'DELETE',headers:H}); await sleep(400); }
    log('Creating:',t.name);
    const cr=await fetch(`/api-2.0/courses/${t.cid}/quizzes/`,{method:'POST',headers:H,body:JSON.stringify({title:t.name,type:'practice-test',description:t.name,duration:t.duration,pass_percent:t.pass_percent})});
    if(!cr.ok){ log('  ERROR create',cr.status,(await cr.text()).slice(0,120)); continue; }
    const quiz=await cr.json();
    // CRITICAL: put quiz into editable (unpublished) state before adding questions
    await patch(t.cid,quiz.id,{is_published:false}); await sleep(200);
    let ok=0,fail=0;
    for(let i=0;i<t.questions.length;i++){
      let done=false;
      for(let a=0;a<4&&!done;a++){
        try{ const r=await fetch(`/api-2.0/quizzes/${quiz.id}/assessments/`,{method:'POST',headers:H,body:JSON.stringify(t.questions[i])});
          if(r.ok){ok++;done=true;} else { if(a===3){fail++;log('   Q'+(i+1)+' fail',r.status,(await r.text()).slice(0,90));} await sleep(600);} }
        catch(e){ if(a===3){fail++;} await sleep(600);} }
      await sleep(110);
    }
    await patch(t.cid,quiz.id,{is_published:true});
    log('  ->',t.name,'inserted',ok,'failed',fail,'(published)'); TOK+=ok; TFAIL+=fail;
  }
  log('ALL DONE. inserted',TOK,'failed',TFAIL,'. Reload each course Curriculum to confirm.');
})();
